window.POEM_DB=window.POEM_DB||{};POEM_DB["ming_024"]={"n":"湛若水","dyn":"明","poems":[{"t":"井井亭","f":"古风","c":["有亭井井，山下出泉。","以静而清，浚发天源。","汲之不勤，德之日新。","唯德日新，以济渴人。"]},{"t":"石潭","f":"古风","c":["水行石上，用柔破刚。","涓涓成渊，蛟龙是藏。"]},{"t":"翩翩者棣三章赠潘希召之弟归辰阳","f":"古风","c":["翩翩者棣，花萼相及。","夫我不见，兄弟异邑。","兄弟异邑，相送于南，涕泪以泣。","翩翩者棣，花萼相成。","夫我不如，兄弟异京。","兄弟异京，相送于野，涕泪沾缨。","翩翩者棣，花萼瞱瞱。","庇兹本根，永以为惬。","言抚其根，言采其花。","道远莫致，掷之长嗟。"]},{"t":"赠徐曰仁守祁州三物三章章六句","f":"古风","c":["有徂怀人，赠之纨扇。","辟元规尘，助清谈衍。","以除民热，以蔽大暵。","有徂怀人，赠之长鞭。","慎数马尾，勇著争先。","以起民罢，以驱蹊田。","有徂怀人，赠之缄书。","圯下之帙，寔帝者师。","毋咀其皮，而哜其胔。"]},{"t":"习古斋","f":"古风","c":["习之习之，古自我作。","习乎自然，学而不学。","化工在手，天机可握。","误笔成蝇，运斤去垩。"]},{"t":"恐斋","f":"古风","c":["临深履薄，匪曰觳觫。","震不丧匕，心非槁木。","上帝若临，天君自靖。","有所于恐，不得其正。"]},{"t":"命吴生?字泳中诗四章章八句","f":"古风","c":["厥初生民，昊天降极。","如冰斯寒，如火斯炽。","相协尔居，日用饮食。","尔识尔知，莫匪尔德。","物有挠之，遂淫其则。","其则不远，民用僣忒。","鸡犬其心，见鹄思射。","先民有言，不有博弈。","眇兹寡陋，学也不力。","若存或忘，终罔有得。","汨汨厥灵，桑榆日逼。","告尔同志，毋忘夕惕。","上帝其临，兢兢翼翼。","敬恭尔思，戒尔颇僻。","载锄其骄，灵根其植。","涵而泳之，河浸膏泽。"]},{"t":"古劳二章章十二句","f":"古风","c":["古劳之下，有川洋洋。","洋洋曷以，可濯可航。","泛彼兰舟，与子同行。","时届重阳，朗天清霜。","临流怀旧，伊人云亡。","俛仰今昔，云胡不伤。","古劳之上，云山霅霅。","霅霅曷以，以跻以悬。","乘此柴车，与子同联。","峍乎郁葱，于葵之根。","登高望远，伊人不存。","爰卜幽宅，以慰精魂。"]},{"t":"藤江雨中","f":"古风","c":["腊月既望，我徂自藤。","云木翳翳，零雨其冥。","有山如戟，有石如城。","云餐雨立，仆夫于征。","联我兰舟，与子同行。","念彼室处，感兹靡宁。"]},{"t":"平南遣兴","f":"古风","c":["渔渊水深，采芝云迷。","寄怀云水，抗志高栖。","严霜陨木，归鸿背飞。","天寒日短，途长行迟。","岁云暮矣，我心则悲。","神游八极，身囿两仪。","宇宙为旅，万物为徒。"]},{"t":"爱日二章章十句","f":"古风","c":["瞻彼爱日，实慰我心。","自我室处，天光下临。","我行千里，弥月霾阴。","仆夫痡矣，修途阻深。","我行不辰，昊天何心。","爱日熙熙，实系我思。","于盘之子，尔暄尔曦。","自我弥旬，风雨凄凄。","我心忧矣，阻于涂泥。","实命不偶，昊天何私。"]},{"t":"敬止","f":"古风","c":["风云自天，龙蛇起陆。","君子敬止，渊渊穆穆。"]},{"t":"睍睆二章章六句","f":"古风","c":["睍睆黄鸟，遗音千山。","怀我良朋，声闻其先。","我之思矣，矧兹德言。","黄鸟睍睆，响传千岑。","怀我好友，弗思德音。","我之忧矣，矧彼盍簪。"]},{"t":"赋东山","f":"古风","c":["瞻彼东山，巍巍南极。","我怀君子，于山之侧。","有渰其云，不雨而泽。","秪以淹望，永言思德。","将哦将思，陈侯是式。","谁其赋之，少师无斁。"]},{"t":"凝道之什","f":"古风","c":["坎坎击鼓，于樵之巅。","乃荐乃献，尹公之贤。","于贤维何，德义迁迁。","坎坎击鼓，烟霞之下。","乃咏乃歌，饯尹公者。","于咏维何，德音雅雅。","亦既击鼓，亦既考钟。","以宴以乐，公坐于宫。","维公在宫，威仪颙颙。","击鼓喤喤，考钟锵锵。","以乐以宴，公坐于堂。","维公在堂，德容不忘。","维钟维鼓，维瑟维琴。","何以假之，嗣此德音。","维此德音，维樵之岑。","维琴维瑟，维钟维鼓。","维以足蹈，维以手舞。","其乐未央，公晏灵府。","作乐歌舞，出饯尹公。","声影悬矣，送之九龙。","九龙跃跃，导之以樵风。","谁其主之，兀厓来同。"]},{"t":"西征凯旋雅","f":"古风","c":["皇天眷德，全畀所覆。","至于海隅，薄广左右。","惟兹两广，实惟荒遐。","顽氓聚啸，互相爪牙。","屡廑南顾，屡简重臣。","顺抚逆戮，均之圣仁。","韩公用武，以严厥始。","朱公用文，克和厥中。","文武并济，将在今公。","既和而玩，治久而隳。","习为姑息，如病痿痹。","天子神圣，天子曰嘻。","顾兹不振，畴克振之。","惟尔萧卿，懋兹六德。","仁信智勇，文武是克。","惟兹六德，乃懋厥功。","率时六馆，奏尔鼎镛。","公拜稽首，对扬天休。","臣罔于家，聿来胥谋。","惟时桂林，爰始兴事。","贼方跳梁，将骄卒敝。","公始下车，不遑煖席。","亲秉旄钺，勇气有激。","智以先之，仁以结之。","信以成之，我军张威。","六月于征，载穷其巢。","俘获十千，凯旋告劳。","广人有言，昔若奄奄。","中丞是作，顽懦有廉。","广人有言，昔尚萎靡。","萧公来严，士皆作气。","文武严和，成自公今。","侯谁记之，守臣周任。","周侯记之，太史文之。","以奏成功，以告鼎彝。"]},{"t":"题画二首 其一 圯桥进履","f":"古风","c":["进履之心，可以授道。","惜哉师传，未闻何奥。"]},{"t":"题画二首 其二 希夷睡图","f":"古风","c":["不醒是梦，醒亦是梦。","既同是梦，长年何用。"]},{"t":"高氏祖庙诗 其一","f":"古风","c":["奕奕大族，世于乐清。","维诗维礼，维以簪缨。","匪维缨也，维礼维诗。","维彼瓜瓞，胤庆无期。","奕奕令族，世于高奥。","维孝维弟，勿替尔祚。","匪伊祚矣，维以孝弟。","维以慈让，于庆千祀。"]},{"t":"示诸学者","f":"楚辞体","c":["心无一物，天理见前。","何为天理，本体自然。","廓乎浑兮，四时行焉。","勿忘勿助，圣则同天。"]},{"t":"潘生子嘉姑母贞节诗","f":"古风","c":["忘独忘寡，忘寡忘贫。","七十六春，忘厥女身。","贞一不分，乃通于神。","是谓圣善，奚节之云。","姥如未信，询尔舅孙。"]},{"t":"题金芝呈瑞卷","f":"古风","c":["煌煌金芝，维山之辉。","云谁之瑞，玉厓维祺。","玉厓巍巍，金芝离离。","金玉交映，君子以之。","我有灵根，先天地春。","美斯毓斯，维天维人。","光于宇宙，瑞于无垠。","思遗怀人，道远奚因。"]},{"t":"朔风","f":"古风","c":["朔风飕飕，送子归舟。","出饯于江，写我离忧。","虽则离忧，匪厉则逸。","人亦有言，召命不日。"]},{"t":"答侍御朱君诗 其一","f":"古风","c":["陟彼泉山，其山崇崇。","其崇曷以，坯土之丛。","坯土之受，坯土之积。","于千万仞，维以崇德。","崇德曷以，忠信其址。","谁学此山，子朱子礼。"]},{"t":"感忠楼诗 其一","f":"古风","c":["奕奕钜汪，司马昌之。","嗣子胤孙，无匮其祺。","昭昭越王，生而前知。","神明日发，不可测思。","不可测思，矧可忘思。"]},{"t":"感忠楼诗 其二","f":"古风","c":["视彼牛尾，牧者骇异。","威慑六州，六州控制。","有而不有，于唐之世。","留守九宫，王号是畀。","矧可忘斯，念兹厥始。"]},{"t":"感忠楼诗 其三","f":"古风","c":["登源之茔，萎木再荣。","千春枯槁，谓匪神功。","氓曰神哉，曷感而通。","鞠哉冢宰，树此感忠。","树此感忠，念祖无忘。"]},{"t":"感忠楼诗 其四","f":"古风","c":["其忠维何，岭表寔多。","积十馀稔，经略威和。","亦职海道，朗机扬波。","公乘长风，夺其长技。","曷不怀嗟，曷不怀嗟，念此荣柯。"]},{"t":"感忠楼诗 其五","f":"古风","c":["何以怀云，视尔赤心。","贼濠逆天，奋戈入擒。","言誓妻子，告尔有神。","所不如愿，宁殒厥身。","宁殒厥身，顾念忠勋。"]},{"t":"感忠楼诗 其六","f":"古风","c":["忠勋念兹，何日忘之。","君尔忘身，公尔忘私。","摅谋决策，坐亡群疑。","惟此忠悃，惟帝眷知。","感兹眷忠，无忝孝思。"]},{"t":"感忠楼诗 其七","f":"古风","c":["思彼槁木，犹感忠诚。","矧伊人矣，云胡不灵。","感忠以劝，联楼峥嵘。","拄地撑天，聿怀永宁。","聿怀永宁，勿替休徵。"]},{"t":"偶笔示张廷佐都司马金挥使","f":"古风","c":["天地合德，为阴为阳，为雨为霜。","圣人合德，为喜为怒，为文为武。","或以揖让，或以毅果。","如人一身，弛张在我。","在我弛张，文武一道。","一道在我，无施不可。"]},{"t":"寿宝安任君砚斋先生华诞诗","f":"古风","c":["我怀铁江，宝安之阳，隔水汤汤。","有美一人，水中之央。","水中之奇，中气粹之。","何彼德星，生宁馨儿。","其馨维谁，柱也之材。","黄堂之祯，邦家之维。","亦治九华，寿祝无涯。","维以大耋，维德之遐。","维神斯听，竹实是徵。","颍川之治，凤凰来鸣。","遐以寿昌，遐以显扬。","寿斯永斯，君子之光。"]},{"t":"寿张母封太孺人华诞","f":"古风","c":["陈乐高堂，华筵广张。","寿山为俎，北海引觞。","贞哉圣善，笃生二郎。","维孟有轲，维范有滂。","伯供戏彩，仲捧翟裳。","伯氏吹埙，仲氏吹篪。","乐从天来，人自不知。","宛宛王母，宴于瑶池。","三千之实，偷桃之儿。","昭昭圣善，亦严亦慈。","既寿且荣，封章有辉。","自兹古希，万寿无期。"]},{"t":"昔我三章章六句","f":"古风","c":["昔我视尔，兄弟不犹。","今尔既立，视我如雠。","虽则如雠，我心不尤。","事我之心，转而他人。","凡今之人，薄如秋云。","虽如秋云，我心贞珉。","昔操我戈，今入我室。","匪则入室，道命不一。","其一不一，我心中实。"]},{"t":"九章赠别 其一","f":"五言律诗","c":["窈窕者谁子，绝代亮无双。","不谙小姑性，以直终见伤。","虽则终见伤，中情容何妨。","谁为别鹄吟，此曲多慨慷。"]},{"t":"九章赠别 其二","f":"五言律诗","c":["迟迟别帝都，迟迟胡乃尔。","臣躯易弃捐，臣心讵能死。","天王会圣明，帝阍亦孔迩。","援琴不成声，掩抑泪横泗。"]},{"t":"九章赠别 其三","f":"五言古诗","c":["黄鸟亦有友，空谷遗之音。","相呼上乔木，意气感人深。","君今脱网罟，遗我在远林。","自我初识君，道义日与寻。","一身当三益，誓死以同襟。","生别各万里，言之伤我心。"]},{"t":"九章赠别 其四","f":"五言古诗","c":["北风吹湖船，帆挂南岳树。","祝融下玉坛，却立问来去。","知君有仙骨，相期事轻举。","胡为淩风波，恐为蛟龙取。","君若访五峰，愿留共君住。"]},{"t":"九章赠别 其五","f":"五言律诗","c":["行行过湘浦，举首望九疑。","若见重华墓，为我三拜之。","三拜之不足，稽首重致辞。","都俞事久阔，嗟予将安归。"]},{"t":"九章赠别 其六","f":"五言律诗","c":["我有三尺木，囊括久不弹。","一朝遇知音，为君初上弦。","上弦含清响，未弹意先传。","赠君别鹤操，报我以孤鸾。"]},{"t":"九章赠别 其七","f":"五言律诗","c":["皇天常无私，日月常盈亏。","圣人常无为，万物常往来。","何名为无为，自然无安排。","勿忘与勿助，此中有天机。"]},{"t":"九章赠别 其八","f":"五言律诗","c":["穷索不穷索，穷索终役役。","若惟不穷索，是物为我隔。","大明无遗照，虚室亦生白。","至哉虚明体，君子成诸默。"]},{"t":"九章赠别 其九","f":"五言律诗","c":["天地我一体，宇宙本同家。","与君心已通，离别何怨嗟。","浮云去不停，游子路转赊。","愿言崇明德，浩浩同无涯。"]},{"t":"用韵","f":"五言古诗","c":["长鱼有奇种，运鬣翳南溟。","一朝生羽翼，九万起云程。","二仪范淑质，日迈月斯征。","霜风吹百草，百草为不馨。","愿言自栽培，不逐众衰荣。"]},{"t":"过严子陵祠","f":"五言古诗","c":["吾慕严先生，殊非巢许徒。","出处似合道，为义匪为高。","宾友分已定，从官何乃劳。","展足卧故人，故态知狂奴。","欠伸动天象，况乃人主乎。","惜哉帝王真，大老归江湖。","孰谓天地量，徒见客星孤。","公卿满汉庭，纷纷索谶图。"]},{"t":"过玉山望怀玉巍峨感兴有作","f":"五言律诗","c":["步出草萍关，举首见怀玉。","超然动遐想，中有彩云屋。","山高天宇空，安知白日速。","翩翩青鸟使，暮归玉台宿。"]},{"t":"朴水渔舟","f":"五言绝句","c":["渔者乐水浅，鱼性乐水深。","渔鱼各有欲，虚舟本无心。"]},{"t":"别后与赵元默言怀四首 其一","f":"五言古诗","c":["子房报韩心，毛公捧檄意。","衷曲谁能亮，举世皆非是。","圣哲明几先，众人视成事。","浊水出磨泥，一朝迥神异。","士志各有定，肯为俗下比。"]},{"t":"别后与赵元默言怀四首 其二","f":"五言古诗","c":["嘐嘐嗟断金，悠悠结同心。","同心苟不固，胶漆亦未深。","杯酒出肺腑，按剑起知音。","朝为鱼水欢，暮为商与参。","同学张陈子，干戈竟相侵。","去去请息交，鸥盟蚤当寻。","钟期或未死，吾且囊吾琴。"]},{"t":"别后与赵元默言怀四首 其三","f":"五言律诗","c":["桃李默不言，流莺语春风。","语默各有性，此理谁能穷。","羁靮不由人，圣人有天工。","岂无神化术，能使蛇作龙。"]},{"t":"别后与赵元默言怀四首 其四","f":"五言古诗","c":["闲处有真忙，忙处有真闲。","始知真闲忙，不在闲忙间。","在人有万变，此心无往还。","往还在通塞，坐与事物关。","无适无不适，物物有至神。","嗟彼游心子，求之蓬莱山。"]},{"t":"过匡庐","f":"五言古诗","c":["匡庐何所极，苍苍阁晴空。","兄弟事幽讨，同日蹑奇踪。","炼形化精魄，列为五老峰。","物固有不朽，万代垂高风。","我欲访其居，道远谁能从。","长揖入翠微，冥栖结云松。","从予以朱鸟，閒骑一苍龙。"]},{"t":"赠周文都赴应天府判","f":"五言古诗","c":["送别崇文郊，欲别还踟蹰。","别远会恐难，延缘且斯须。","与君会此地，十六星火除。","后会安可必，人事靡常居。","松柏化为薪，平陆成沮洳。","变态若风云，念此心烦纡。","江流罔昼夜，钟山郁葱如。","万变皆在人，无事应簿书。","人生驹过隙，日月倏转车。","崇德贵及时，愿君爱玉躯。"]},{"t":"戊辰腊廿七日夜梦王伯安兄","f":"五言古诗","c":["四时有去来，逐客久不至。","天运尚可量，人事谁能计。","昨夜梦见之，仿佛精神契。","语久声弥低，画地示予字。","灭没不可辩，了了得其意。","言别何匆匆，路远会难继。","合欢讵知梦，是梦聊足慰。","借如平生魂，亢爽不可致。","念之生悲凄，达旦不能寐。"]},{"t":"除夕","f":"五言古诗","c":["阴阳无停机，天道常流转。","除夕依辰至，岁月忽已晚。","感节念年非，令人发悲惋。","少壮多志气，白发已乱短。","行年逾不惑，知命途尚远。","誓当师继日，畏此流光遄。"]},{"t":"新春写怀三首 其一","f":"五言古诗","c":["促促笼中鸟，脉脉念远林。","远林在何许，乃在增城阴。","增城云九重，结巢最高岑。","自罹尘网内，胡乃独伤心。","仰见云间翼，窅然遗我音。","愿言养奇翅，高举待秋深。"]},{"t":"新春写怀三首 其二","f":"五言古诗","c":["阳气回管律，百虫已惊蛰。","彼虫尚有情，草木皆萌蘖。","君心亮匪石，坠井不复发。","三年事远游，一去无书札。","天道苟好还，君当终言旋。"]},{"t":"新春写怀三首 其三","f":"五言古诗","c":["黄鹂出幽谷，款款闻新音。","感我伐木篇，长言被弦琴。","小弦意迫切，大弦纡思深。","馀韵托南风，翻作龙场吟。","上以期琢玉，下以期断金。"]},{"t":"赠寇子之南都三首 其一","f":"五言古诗","c":["一莺或两莺，嘤嘤若求善。","意气正相感，忽值时节变。","时节日已变，君行日已远。","一隔如参商，咫尺不相见。","相见不尽情，相思难嗣声。"]},{"t":"赠寇子之南都三首 其二","f":"五言古诗","c":["烨烨璞中玉，重拟连城赀。","戒之在雕琢，勿为人所欺。","君身有至宝，灵瑩无瑕疵。","去去求名工，无为强凿之。","败甲与枯草，尚可决吾疑。"]},{"t":"赠寇子之南都三首 其三","f":"五言古诗","c":["形下下影响，形上上神奇。","智愚一以远，慎哉此毫釐。","上下匪一体，何由知彰微。","修之在敬义，人力非天机。","请勿信我语，亲见乃不疑。"]},{"t":"孙氏曲水观鱼图","f":"五言古诗","c":["大化在咸若，渔利及小鲜。","喜戚以我故，口腹为心缘。","闻有直钩子，此道今莫存。","丈人濠上翁，回溪有潜鳞。","悠然观澜处，或跃见天真。","物情有冥会，此乐未易言。","因思网罟设，自古无全仁。"]},{"t":"客有别号莲塘者以自附于濂溪之说予谓之曰于中通得圣人之体于外直得圣人之用于不支蔓得圣人之真于出淤不染得圣人之清遂感而赋之","f":"五言古诗","c":["清清塘中莲，亭亭思公贤。","思公爱公莲，欲往隔湖天。","通直得自性，芳意谁与传。","岂无牡丹艳，徒为俗子怜。","扳荷玩水珠，弄化不成圆。","何因动遐想，敛衽莲峰前。"]},{"t":"中秋感兴二首 其一","f":"五言古诗","c":["明月当中天，逍遥步前庭。","问是此何时，昏中正虚星。","嗟叹良独久，化机倏流行。","白鸟会中昃，海蟾岂常盈。","粲粲彼姮娥，皎洁含天灵。","长风扫云翳，率土仰贞明。","所嗟时不待，几见天河清。"]},{"t":"中秋感兴二首 其二","f":"五言古诗","c":["孤居感名节，三四见星虚。","漫漫中夜心，良人自远徂。","昔忧见面难，不谓无简书。","感叹嗟何及，吞声涕涟如。","明月云无私，不为照区区。","会合一何欢，隔离一何冤。","耿耿离合情，万里同月圆。"]},{"t":"南溪四景 其一","f":"五言绝句","c":["南溪春何如，泱泱映涟漪。","涟漪绿何如，白鸥来染衣。"]},{"t":"南溪四景 其二","f":"五言绝句","c":["南溪夏何如，漾漾浩瀰漫。","瀰漫深何如，满意看浴云。"]},{"t":"南溪四景 其三","f":"五言绝句","c":["南溪秋何如，澄澄澹清幽。","清幽皎何如，可鉴鱼虾游。"]},{"t":"南溪四景 其四","f":"五言绝句","c":["南溪冬何如，涓涓细清浅。","清浅静何如，寻源观蟹眼。"]},{"t":"赠人游南雍","f":"五言古诗","c":["游子涉江去，采采南涧芹。","采之欲何为，岁暮寄怀人。","怀人自不远，岁暮行当返。"]},{"t":"海印寺镜光阁登高二首 其一","f":"五言律诗","c":["镜光前无路，才行始通窍。","窈窕入云磴，攲侧行木杪。","凭虚知天高，俯下觉形小。","诣道如是观，洒落万物表。"]},{"t":"海印寺镜光阁登高二首 其二","f":"五言律诗","c":["镜光本胜游，匪为谢尘扰。","登高舒远眸，习静观众妙。","风景翻多忧，履危愈悄悄。","悠然望旷野，目尽意不了。"]},{"t":"赠吾廷介致仕归开化诗四首 其一","f":"五言古诗","c":["我或求珷玞，人或畀璚玖。","非不爱璚玖，向人难启口。","启口恐吠声，听听国多狗。"]},{"t":"赠吾廷介致仕归开化诗四首 其二","f":"五言古诗","c":["我或抱荆璞，人或誇燕石。","非不诬此石，向人难历历。","历历恐伤明，明者当自识。"]},{"t":"赠吾廷介致仕归开化诗四首 其三","f":"五言古诗","c":["人或采桃李，我或赠芙蓉。","非偏爱芙蓉，直外仍通中。","静直春风表，不为众芳容。"]},{"t":"赠吾廷介致仕归开化诗四首 其四","f":"五言古诗","c":["无极我之先，大块我之后。","问我是何物，见之亦无有。","纷纷形迹间，聚散讵能久。"]},{"t":"送侍御清戎","f":"五言古诗","c":["绣衣乘青骢，矫矫气如龙。","霜蹄振山岳，踏躞生秋风。","问君何所如，直指湖西东。","问君何所事，皇命肃清戎。","戎籍亦已繁，号声上通天。","仍闻父老叹，逃亡尚未还。","室有新寡妇，膝有新孤孱。","何当见使君，长跪告此冤。"]},{"t":"秋怀三首寄王庐陵阳明子 其一","f":"五言律诗","c":["秋月缺复圆，客行久不还。","不还岁亦暮，念子屡长叹。","叹罢继以歌，歌竟泪如泉。","何时得会晤，所怀万一宣。"]},{"t":"秋怀三首寄王庐陵阳明子 其二","f":"五言律诗","c":["涉园采桃李，持以赠所知。","非贵桃李颜，不言自成蹊。","岂无兰桂好，质以香自亏。","默默牛医子，心期浩无涯。"]},{"t":"秋怀三首寄王庐陵阳明子 其三","f":"五言律诗","c":["封书寄燕雁，雁不过衡阳。","封书寄江鱼，鱼沉江水长。","江水亦有竭，封书永不灭。","耿耿无由宣，心绪自中结。"]},{"t":"漱石二首 其一","f":"五言古诗","c":["涧水何泠泠，涧石何磷磷。","漱之欲奚为，石苔自无尘。","安得石上泉，漱我耳中喧。"]},{"t":"漱石二首 其二","f":"五言古诗","c":["涧水漱幽石，漱之何太勤。","幽石本贞白，粲粲无缁磷。","安得山下泉，漱我胸中尘。"]},{"t":"画","f":"五言绝句","c":["群雀下啄泥，仰唤竹间侣。","竹亦有嘉实，若为相赠许。"]},{"t":"冥鹏","f":"五言古诗","c":["冥鹏将图南，去以六月息。","试问何太迟，物以久而积。","冥鹏起扶摇，九万一朝极。","试问何太速，风积有馀力。","嗟彼蜩鴳徒，枪榆聊自适。","枪榆不崇朝，孰辨垂天翼。"]},{"t":"送林君信节推之台州","f":"五言古诗","c":["秋高天宇空，河汉净如澄。","月华皓无际，亭亭照子行。","凉风起天末，金石为之鸣。","回薄西山岑，摇摇吹客旌。","风以比君清，月以比君明。","清飙频远播，明照无遗情。"]},{"t":"赠王德徵户曹谪官之肇庆驿丞","f":"五言古诗","c":["卞和献荆璞，言尽继以泪。","虽以三刖足，于心曾不悔。","岂不知保身，徒以识为累。","楚国有大宝，弃之如瓦块。","何况以暗投，按剑或相待。","大易贵藏器，龙蛇亦何害。"]},{"t":"壬申二月七日出京驻通州有怀","f":"五言古诗","c":["秉节降金台，徘徊瞻斗杓。","斗杓东回旋，北极终不摇。","下直长安西，三二骨肉交。","骨肉谁忍割，矧此多危途。","含凄感悲风，羞作儿女号。","长弧射天狼，拥彗扫旄头。","日月会中天，聚首是何朝。","各自养时晦，慎言思寡尤。"]},{"t":"双松颂通州王彦声侍御行台","f":"五言古诗","c":["松枝何太高，高可撑青天。","松根何太深，深可彻黄泉。","松叶何太繁，繁可庇颠连。","高以比君节，繁以比君仁。","深以比君智，宜续甘棠编。","呜呼如此树，宜种君堂前。"]},{"t":"德州吟 其一","f":"五言古诗","c":["南风起浩荡，吹我德州航。","黄尘翳白日，白日无辉光。","顺逆固有数，风伯亦何伤。"]},{"t":"舟泊梁家庄檃括与应原忠语","f":"五言古诗","c":["万物宇宙间，混沦同一气。","充塞与流行，其体实无二。","就中有粲然，即一为万理。","外此以索万，舍身别求臂。","逝川及鸢鱼，昭昭已明示。","我心苟不蔽，安能出于是。","知止乃有定，动静原非异。","见之即浑化，是名为大智。","其次在敬养，敬有为心累。","勿忘以勿助，其机极简易。","嗟彼世间儒，憧憧起私意。","自然本无为，廓之配天地。"]},{"t":"临清吟","f":"五言古诗","c":["壬申仲春尾，问道临清流。","寒泉汲短绠，新草弥荒洲。","去鸟历微霭，焉知光景遒。","感物发长叹，云日令人愁。","群公递倾盖，所语皆兵筹。","折冲在千里，虎噬犹未休。","如闻复内向，独抱杞人忧。","安得汉骠骑，一鼓清神州。"]},{"t":"太湖二章 其一 东洙","f":"五言古诗","c":["刺船过东洙，东洙风景奇。","莫打东洙水，惊我白鸥飞。","白鸥飞尚可，翠柳鸣黄鹂。"]},{"t":"太湖二章 其二 西崦","f":"五言古诗","c":["刺船过西崦，西崦风光幽。","莫唾西崦石，渐近太湖头。","太湖烟波阔，洞庭渺难收。"]},{"t":"泛太湖访九和侍讲聚坞别业","f":"五言古诗","c":["少非风尘姿，雅志在丘壑。","偶从野王舟，春夜太湖泊。","茆公向我揖，为我举云幕。","雨后空宇澄，天高极寥廓。","七十二峰峦，缥缈天际落。","日短意不穷，更上湖边阁。"]},{"t":"登琴台","f":"五言律诗","c":["陟登千仞冈，超然坐琴台。","长倚青琅玕，举手望蓬莱。","不见瑶台月，但见青鸟来。","弱水几清浅，念之令人哀。"]},{"t":"自天竺过灵隐","f":"五言律诗","c":["已辞鄂王宫，迢递入天竺。","鸟道烟萝深，履声落空谷。","一溪度飞来，泠泠更幽独。","无为独木桥，于此巢云竹。"]},{"t":"钱塘观潮","f":"五言律诗","c":["乘月步层台，独立倚长塔。","逍遥望东海，天地归吐纳。","夜潮殷如雷，涛头雪山立。","病骨怯虚寒，四月欺缊纳。"]},{"t":"过塘江将访大冢宰王先生有怀阳明","f":"五言古诗","c":["迢迢涉江去，江介生凄风。","涉之将奚为，南湖采芙蓉。","美人在远道，我心忧忡忡。","登山足夔魅，蹈海多鱼龙。","俯仰天地内，去子谁予从。"]},{"t":"访阳明洞天","f":"五言古诗","c":["道经蓬莱馆，溪穷到阳明。","下看东南峰，苍苍入青冥。","不诣此真境，焉知匪虚名。","踧踖步岩石，山高岂无灵。","子乔不可见，伫立魂屏营。","草木若有识，欣欣向予荣。","采之欲谁寄，岁晏难为情。"]},{"t":"严州诗三首 其一 小阳","f":"五言律诗","c":["弭棹小阳头，小有藏春屿。","隔竹十数家，风日美清渚。","山木苦未多，空林一鸟语。","即事岂知幽，浣纱此溪女。"]},{"t":"严州诗三首 其二 大阳","f":"五言律诗","c":["弭棹大阳头，大有藏春坞。","深林隔尘寰，苍石辨太古。","岩岫千千重，重重起烟雨。","疑有蛟龙居，全身应九五。"]},{"t":"严州诗三首 其三 邬子","f":"五言古诗","c":["投暮宿瑞洪，际晓过邬子。","薄云递轻凉，微雨湿芳沚。","高帆信天风，断港出湖涘。","因动江湖思，便欲泛彭蠡。","遥揖五老峰，汀洲采蘋芷。","乘流直东下，无乃瞬息耳。"]},{"t":"谒徐高士墓二章章十句 其一","f":"五言古诗","c":["蔼蔼东都季，群公青云器。","耿耿陈窦心，时违势自踬。","哲人方龙蛇，沉冥西江汜。","下榻岂无论，栖栖欲奚俟。","载诵厦木言，时之用大矣。"]},{"t":"谒徐高士墓二章章十句 其二","f":"五言古诗","c":["严陵卧扶汉，段生偃藩魏。","古来素业流，沮溺乃救世。","我拜墓中人，伊人骨已蜕。","我拜墓前木，此木栋梁器。","载感厦木言，时之用大矣。"]},{"t":"过十八滩","f":"五言古诗","c":["行行十八滩，一滩度一劫。","劫尽逢水源，平澜见明月。","踏月逾庾关，于兹是小歇。","人世多滟滪，寻常互倾灭。","我身在风涛，阅月百圆缺。","此事难重陈，重陈五情热。"]},{"t":"蛋子","f":"五言律诗","c":["蛋子何眇眇，自得同水族。","缓桨荡朝暄，落日依阴谷。","将舟无远梦，下上清溪曲。","得失在一鱼，岂识荣与辱。"]},{"t":"三妇辞","f":"五言古诗","c":["大妇厌糟糠，中妇足粳粱。","小妇何绰约，装金调玉浆。","愁乐各未终，微日落阴冈。"]},{"t":"明月吟三章 其一","f":"五言古诗","c":["举首望明月，明月沉海中。","举手招白云，白云游太空。","白云不可结，明月不可缝。","揽袂长叹息，星火忽已终。","安得飞仙子，借我一苍龙。"]},{"t":"明月吟三章 其二","f":"五言古诗","c":["明月出海东，照入我怀中。","两手捧怀笑，浮云生我胸。","移枕见远山，开窗得清风。","适意非有期，至道末有从。","蓬莱隔弱水，无力谁能杭。"]},{"t":"明月吟三章 其三","f":"五言古诗","c":["仰看明月殿，灿灿姮娥居。","我欲跳身入，飞空骑蟾蜍。","归来启灵府，中有明月珠。","佩之当明月，圆光满八区。","愿扫浮云翳，本来无外须。"]},{"t":"曲江吟","f":"五言律诗","c":["曲江江水长，欲济川无梁。","美人不可即，风度安可量。","飞鸟择高枝，鸣凤在朝阳。","黄唐世已远，千载空翱翔。"]},{"t":"武溪吟","f":"五言律诗","c":["武溪溪水深，欲往隔云浔。","美人在何许，风采空遗音。","忧思满南北，托之被弦琴。","惟有江门石，可以写我心。"]},{"t":"憩南华方丈","f":"五言律诗","c":["应变意弥定，到寺心颇动。","泥空乃多修，无事有大用。","溪行得自身，云卧无尘梦。","迢遥隔岭钟，风吹过阴洞。"]},{"t":"出漕溪即事","f":"五言律诗","c":["夜宿漕溪边，云深失归径。","山空白露下，林迥玄风定。","火轮明东海，魄渊薄西岭。","举手问两崖，此中是何景。"]},{"t":"同赵元默联舟如江门","f":"五言古诗","c":["今夕乃何夕，复与子同携。","舟楫更相将，灯烛仍交辉。","念彼旧游地，一落多路岐。","欲恸杨朱泣，泪下不可挥。","举首望黄云，太山久已颓。","哲人不可作，与子其从谁。"]},{"t":"谒石翁墓三首 其一","f":"五言律诗","c":["哲人久已逝，山水有遗光。","履地益怀人，况此埋玉乡。","登山勿采松，采之恐枝伤。","临水勿汲源，汲之流不长。"]},{"t":"谒石翁墓三首 其二","f":"五言律诗","c":["夫君有嘉惠，赠我云锦裳。","中绣自然字，服之永不忘。","忍着君遗物，为人作新妆。","酹酒矢心曲，敬进南丰香。"]},{"t":"谒石翁墓三首 其三","f":"五言律诗","c":["凤凰去不返，万仞空高冈。","升冈望孤凤，何时复来翔。","感此笼中鸟，眷彼旷世祥。","黄唐代已远，五色徒文章。"]},{"t":"黄丹道中即事","f":"五言古诗","c":["客子念前路，居人慕岁功。","舒眸望南荒，林木郁葱葱。","借问此何时，日度玄枵中。","落叶靡堕影，来雁无遗踪。","自非朔风发，何以辨玄冬。","乃知天地大，因兹穷始终。"]},{"t":"春情将至贵县有感而作","f":"五言古诗","c":["青青江蓠草，茫茫隔周道。","有女携倾筐，采采忽日暮。","日暮把不盈，持此感春情。","自君之戍矣，江草八九荣。","草荣他人赏，孤居益惆怅。","王孙归不归，春草飞蛾长。"]},{"t":"立春后七日过三十里滩乍闻莺声","f":"五言古诗","c":["客行卅里滩，款款闻绵蛮。","声嫩语犹涩，翅新飞且还。","感我故园念，春来人未旋。","北雁今已归，南枝久当残。","归去来山中，春草游王孙。"]},{"t":"新岁","f":"五言古诗","c":["俗情爱新岁，寒暑运之常。","常运委我去，感兹翻慨慷。","慨慷亦奚为，有志不获将。","悠悠万里道，税驾未有方。","岂无鬓如丝，那堪补君裳。"]},{"t":"古邕州忽见故人龚谦之赠之归潮阳","f":"五言古诗","c":["人生如浮云，散在天一涯。","天涯又飘泊，浩荡成离披。","风吹一朝合，聚会岂有期。","闲云不出山，奇鱼不离溪。","行矣归毋迟，春山多紫芝。"]},{"t":"自龙州至凭祥道中","f":"五言古诗","c":["癸酉王正月，望舒忽已圆。","登望凭祥陆，暂辞龙州船。","杭苇始断港，前旌出回峦。","隐见万山中，初翳疑无门。","转忽或有通，上与青空连。","洒落观群山，芙蓉秀晴烟。","烟与山俱淡，心与境相关。","倏然若有得，殊土元同天。"]},{"t":"仆山驿道中","f":"五言古诗","c":["侧径通幽崖，淩风放高躅。","下有百尺渊，上荫千寻木。","冷泉漱溪毛，回飙动脩竹。","超然生奇怀，情结清溪曲。","中有无名禽，于兹媚幽独。"]},{"t":"丕礼驿夜坐","f":"五言古诗","c":["路驰心有往，俗忤气屡发。","蛮貊苟可行，笃敬功尚缺。","悠悠卧虚馆，咄咄书空札。","惕然发深省，揽衣坐㵳泬。","夜久空宇澄，三籁俱已灭。"]},{"t":"回宿丕礼晓枕夜梦先师石翁先生正月初三日","f":"五言古诗","c":["鸟鸣客初觉，檐隙光渐发。","欲起仍迟留，省事心已折。","哲人夜入梦，遗我一书札。","恍惚不可读，意了字灭没。","展转隔幽明，哀歌思盈闼。"]},{"t":"予与潘黄门使安南还憩龙州同州守赵良弼游仙岩即席赋此时正德癸酉年二月十日","f":"五言古诗","c":["峥嵘矻野次，石壁开岩扉。","山木虽未多，白云暮来归。","小憩登陟馀，超然生远思。","凉飙起新霁，高歌递微晖。","风云一飘散，浩荡本无期。"]},{"t":"游三州岩","f":"五言古诗","c":["昔欲访名岩，匪为恣盘游。","闻有先哲踪，因兹仰前修。","野云埋古院，光风满层丘。","伊人不可见，顿令我心忧。","溪莲有佳实，欲采渺无由。"]},{"t":"初宿凤凰山栖凤窝","f":"五言古诗","c":["凤凰阁千仞，九重增城庐。","城中藏洞府，市上隐悬壶。","云卧毛骨寒，冥栖心境娱。","楼堞几席下，群山入窗虚。","就枕见山色，悠然睇遐墟。","俯仰宇宙内，此乐复何如。"]},{"t":"九月二十二日同巡按高侍御登六榕寺塔","f":"五言古诗","c":["秋高气初清，云净天宇澄。","迢遥上危塔，凭虚步青冥。","仰近北辰次，下看南极星。","达观众妙理，俯察群动情。","斯人苦长勤，日夕竞营营。","惟彼江流水，朝宗去不停。"]},{"t":"题飞来寺","f":"五言古诗","c":["名刹来何方，幻迹飞青天。","天光照岩洞，闪烁云霞间。","云霞散倏忽，上与苍穹连。","空山无人迹，高鸟暮独还。","和光本无路，逝水自有澜。","仲尼久不作，此意谁与言。"]},{"t":"同南雄李太守林通府冷节推宴饮登浮屠","f":"五言古诗","c":["嘉筵籍兰若，宿雨清埃氛。","广宴开云峤，清歌临水滨。","爱客感贤守，鼓瑟愧嘉宾。","狎坐飞羽觞，更酬倒琼樽。","奇怀寄登眺，危塔淩青云。","舒眸碧海际，浩荡观无垠。","游目周四野，歌啸声相闻。","乃知非盘乐，游息至理存。"]},{"t":"吴东湖于清远行台构处远亭","f":"五言古诗","c":["青山拥高台，新亭何翼然。","长桥卧寒波，清池汇门前。","筑者吴季子，伯夷所鸠僝。","江湖孰云远，覆帱同一天。","旭日下亭阶，顿首重致言。","愿垂中天照，蔀屋见颠连。","我欲将此屋，化作千万间。","遍庇逃亡者，圣仁覆人寰。"]},{"t":"漫天","f":"五言古诗","c":["漫天雪霏霏，遍地生寒威。","一方寒可逃，漫天将安违。","仆夫寒吁天，天若不闻知。","天普而无为，羲和愆其期。","三旬竟不返，阳道亦孔微。","将匪羲和愆，云雨有常师。","彼哉胡不仁，亦已焉乎而。"]},{"t":"癸酉除夕","f":"五言古诗","c":["伊昔垂髫年，逢岁辄欢喜。","喜欢将何如，数日仍屈指。","事与年侵寻，世网固缠己。","物态迁性情，感节悲怀起。","四序恒不居，天地有剥否。","眇兹血气躯，神理会颓圮。","四大非我物，安能保妻子。","骨肉尚不顾，官爵宁久恃。","困鱼乐深渊，龌龊思脱屣。","何当淩高风，采薇西山趾。"]},{"t":"送人之荆州搉木","f":"五言古诗","c":["尹铎轻茧丝，冯驩燬券钱。","汲公置焚斗，矫诏赈饥氓。","火辰僣天纪，木德受其燔。","遂令山岳赭，转使民物烦。","民物烦以冤，号声迸高旻。","时当云雷屯，经纶在群贤。","子今万里去，衣佩何翩翩。","燕雀尚堂室，溟鹏薄云天。","形影日以远，思子心凄然。","荆楚多遗迹，问俗重延缘。","倘然得一木，能支大厦颠。"]},{"t":"甲戍正月十七日潘仲鲁黄门诸友游金华双龙赤松诸洞二首 其一","f":"五言古诗","c":["晓出兰溪门，逍遥望名山。","望之已可爱，而况游其间。","窈窕藏境胜，夷旷令心閒。","白云昼冥冥，溪流日珊珊。","不见牧羊子，化石只依然。","心迹俱寂寞，怅望未能还。"]},{"t":"酬姜仁夫用阳明韵见赠兼怀阳明四首 其三","f":"五言律诗","c":["高堂今宴会，明日就泥途。","保命欲骞举，忘身在网虞。","涉江防滟滪，即陆愁崎岖。","嗟予将安之，平地成险阻。"]},{"t":"仁和李掌教白夫求予赠言白夫尝编燕享乐谱一帙见示故终篇以音乐言","f":"五言古诗","c":["白夫广文杰，访我黄金台。","苦意协管律，雅颂釐清吹。","音乐缺已久，闻此喜且疑。","未理金石奏，八音安可裁。","声本起于无，谁解穷往来。","鱼马诚异类，感应何神哉。","乃知太和气，不谢嶰谷材。","圣人假物用，八风谁能回。","此可悟神理，当与西山推。"]},{"t":"北都自严寄阳明子","f":"五言古诗","c":["玉台有名果，成之三千春。","当其未成时，凡品不足珍。","持以赠世人，涩口反见嗔。","白璧按剑起，青蝇止棘频。","圣人诫囊括，明哲贵保身。","云龙会有时，感应岂无因。","不惜知音寡，所惜不能琴。"]},{"t":"送黄小江佥宪进表毕还广州四首 其一","f":"五言古诗","c":["弱龄尘外志，点也与为徒。","微尚夙所敦，俛仰一纪馀。","伤哉力不竞，沦落在泥涂。","中夜起兴叹，揽衣步前除。","咎己有馀裕，尤人尚忧虞。","行年四十九，将与伯玉俱。","知非在今始，言为知者摅。"]},{"t":"送黄小江佥宪进表毕还广州四首 其二","f":"五言古诗","c":["凤鸟旷世出，一鸣三千年。","寥寥抱真士，韬光自委身。","我慕牛医子，沈冥以不言。","之子小江秀，翩翩五陵间。","家学存令德，发愤追前贤。","夙昔游文艺，于今溯真源。","努力同爱日，日月如奔川。"]},{"t":"送黄小江佥宪进表毕还广州四首 其三","f":"五言古诗","c":["昔于阳明子，邂逅初见君。","初见意气合，稍亲直谅闻。","中途遭屯厄，彼此各风尘。","处坎心以亨，委顺道固存。","晤言惬心赏，盛德观日新。","遇利若阻梗，逐义如转轮。","逊志乃有获，过化惟存神。"]},{"t":"送黄小江佥宪进表毕还广州四首 其四","f":"五言古诗","c":["送子出崇文，崇文日照人。","朔风卷长陌，登高临水滨。","河梁一抗手，孤影随形分。","形分瞩望眼，望绝继以音。","所愿崇明德，酬此百年身。","易简理斯得，超诣在忘言。","溟鹏具大翼，九万待风骞。"]},{"t":"陪祭皇陵有述","f":"五言古诗","c":["下马东陵道，北风漫浩浩。","举手拂尘翳，超然见穹昊。","极目望泱茫，王气郁苍苍。","地高逼象纬，彩云浮建章。","群后圣以神，穆穆格明禋。","虎豹开九关，六龙驭众真。","衣冠翕然会，小臣亦骏奔。","皇图愿永固，天寿同无垠。"]},{"t":"与郑伯兴朱守中余子华昌平道中遇风","f":"五言古诗","c":["朔风吹广陌，回合野晴微。","我马亦已瘏，与君同驱驰。","驱驰竟何适，无事信多岐。","道胜境斯惬，情旷途自夷。","况与三益友，同行得所师。","共励淩风节，勿使愿相违。"]},{"t":"拟赠内南归","f":"五言古诗","c":["萍生无根蒂，聚散故不常。","结缔水中荇，牵引随波浪。","荇性有本根，行子念故乡。","忆昔与子别，八九度星霜。","誓同鸿与雁，北徂以随阳。","一息在天涯，万里永相望。","昨日寄书至，两载病喉疮。","令我中情热，矧子讵能忘。","别长苦会短，子独去踉蹡。","岂无儿女情，歌竟长慨慷。"]},{"t":"母病不寝而作","f":"五言古诗","c":["溪莲水晶秀，结子心独苦。","抚己良自惜，不若忘忧草。","昨忻菽水欢，今病心如捣。","肺肝倘可疗，岂但慕割股。","肝肺亦已摧，安得悲速老。","老态发日逼，发白心转赤。","暮暮与朝朝，左右进药食。","食苦谁能甘，食甘谁能释。","视膳古为孝，一气共忻戚。","何日上高堂，彩衣奉颜色。"]},{"t":"陪陈睡乡如先墓致祭","f":"五言古诗","c":["晓雨净炎氛，疏云霭朝阳。","与子誓言迈，肩舆鸣相将。","山花向人笑，好鸟翱还翔。","景物虽可乐，悲怀翻感伤。","引望埋玉处，白云起荷塘。","墓草忽已青，岁序易炎凉。","感君絮酒意，中心讵能忘。"]},{"t":"吴方伯王宪副过小瀛同登楼泛艇为乐","f":"五言古诗","c":["新晴天气佳，轻波动微曛。","被蒙君子顾，画船联海滨。","小堂高宴会，海错亦前陈。","一笑群忧馀，六载此倾樽。","泛艇小瀛外，虚阁淩青云。","舒怀共远眺，聊用慰良辰。"]},{"t":"甘景阳司训自郡中还过小瀛","f":"五言古诗","c":["客舟何悠悠，来自天际头。","水荇动微飙，旭日孤帆收。","云是樗里子，薄言与同游。","维南有嘉木，好鸟时相求。","对此终日夕，聊以忘吾忧。","未应小瀛月，虚系荡湖舟。"]},{"t":"将如江门系舟海珠寺谒李文溪新复祠像","f":"五言古诗","c":["峥嵘起孤根，四面迥无隣。","云是文溪筑，当作李公墩。","屹立彼中流，以墩肖于人。","废兴无定主，此事亦迷沦。","万物理固然，自馀何纷纷。","瞻像绕三匝，感慨复何言。","藤萝附高木，得意干青云。","惟有夕阳鸦，江水自冬春。"]},{"t":"夕发广城如江门谒墓晓望西樵怀旧卜之地途中有作","f":"五言古诗","c":["伐鼓以宵征，寥寥进所如。","夕挂穗城帆，旦梦黄云墟。","畏途发戒心，志在故欢愉。","迢递遵回岸，逍遥度广渚。","秋波漾溪毛，晓云映燬规。","悠然见远巘，一鸟入丛株。","西樵招隐地，未可先吾师。"]},{"t":"夜泊嘉会楼","f":"五言古诗","c":["十年两系艇，几度还登楼。","楼前餐果核，长树与楼头。","日午下疏阴，横塘门径幽。","彼树乃如此，令人生百忧。","废兴递相寻，今古共悠悠。","寂寞孤舟夜，潇条虚柝秋。","满天灿星月，渺渺银河收。","哲人嘉会地，不废长江流。"]},{"t":"谒石翁先生墓","f":"五言古诗","c":["瑟瑟秋风肃，霜高草木黄。","物情何所迫，嗷嗷雁南翔。","美人别云浦，相忆泪浪浪。","天地有尽期，炎飙变为凉。","贤哲皆有死，谁为金石刚。","念昔我夫子，乘云归帝乡。","迢迢十八载，望之云路长。","俯仰松下土，安得不为伤。"]},{"t":"附渡北行夜阻风山旗坑寄怀陈睡乡马怀瑞诸同宴","f":"五言古诗","c":["旦从故人宴，洒落坐高轩。","一为风水别，中阻荒洲壖。","起视迷四野，相忆夜漫漫。","青蝇附马尾，利钝故随人。","贞女托所天，忧乐由夫君。","总为物所误，中立无缠牵。","缠牵累千里，万事理固然。","因兹悟至道，与君同勉旃。"]},{"t":"卜石翁改葬皂帽峰柬仲采","f":"五言古诗","c":["皂帽何处峰，青天敛芙蓉。","屼峍昆仑顶，窈窕蓬莱宫。","本自同大块，精气有所钟。","洒落看诸山，诸山赴海同。","群峰与万壑，拱揖如朝宗。","壁立千万仞，凤凰翔高风。","于兹拟埋玉，可以配我公。","二纪犹此劫，五百隐奇踪。","一朝迥神异，冀北马群空。"]},{"t":"将访西樵寄怀邓子","f":"五言古诗","c":["方子石泉卜，廿年吾意中。","风尘坐迟暮，高锡未淩风。","我卜异于是，烟霞与尔同。","碧云与云端，一以寄幽踪。","且不离烟火，兼可巢筠松。","居僯有二仲，或得共游从。"]},{"t":"宿宝峰寺","f":"五言古诗","c":["秋深天气肃，雨馀亭馆凉。","逍遥登梵阁，寂寞坐僧房。","地高天宇空，云露沾衣裳。","虚磬发林杪，传灯泛云光。","端居疑寂灭，感节故悲伤。","色空云同体，根尘何必忘。"]},{"t":"有客过西樵烟霞洞有作答之","f":"五言古诗","c":["我庐在烟霞，逍遥出云端。","天空鸟道绝，江迥柴门閒。","翩翩者谁子，放歌来叩关。","昔为青衿彦，今为入幕贤。","手持纲成策，爽气淩高寒。"]},{"t":"赠邓生君恪二首 其一","f":"五言绝句","c":["邓生或清者，爱我泉边石。","若无愧此泉，许尔坐泉侧。"]},{"t":"赠邓生君恪二首 其二","f":"五言绝句","c":["君恪慕晦者，晦名在烟霞。","知是素心人，宜住洞西家。"]},{"t":"题第一峰泉二首 其一","f":"五言律诗","c":["双泉驾群峰，大科乃泉窦。","科比泉高卑，已过十八九。","碧云与紫姑，无乃科麓乎。","是为第一峰，斯名岂云诬。"]},{"t":"题第一峰泉二首 其二","f":"五言律诗","c":["大科樵中尊，双泉在科南。","泉比科上下，已过十二三。","宝鸭与双鱼，无乃流之馀。","是为第一泉，斯名讵云虚。"]},{"t":"三水候送郭总戎不至二首 其一","f":"五言律诗","c":["戴星出西樵，见月望三水。","愁愆美人期，君命恐不俟。","朔风吹船头，寒沙齧船趾。","开蓬瞻停云，未忍中道已。"]},{"t":"三水候送郭总戎不至二首 其二","f":"五言律诗","c":["厥明泊水涯，楼船来未来。","舍舟步曲岸，登高望所怀。","所怀久不至，渺渺令人猜。","自古难前期，人事多好乖。"]},{"t":"从郭总戎三水之会夜归二首 其一","f":"五言绝句","c":["稍稍将船去，倏尔度三辰。","朝去暮知还，多愧山中云。"]},{"t":"从郭总戎三水之会夜归二首 其二","f":"五言绝句","c":["将船中夜归，潮到翳门溪。","孤帆背月收，白云还满衣。"]},{"t":"得垂虹泉悬壁岩","f":"五言古诗","c":["东行度龙溪，遵岭北而西。","回望烟霞洞，中居控四维。","前得垂虹泉，珊珊落云端。","壁立如斩削，鸟道孤岩悬。","于兹宜揽结，或可作小歇。","洗耳与枕流，长以师峻洁。"]},{"t":"示诸生兼告同志","f":"五言古诗","c":["圣人亦人为，诸子早辨志。","持此忠信资，何远不可至。","尧舜称大圣，其道孝弟耳。","孝弟谁不然，鲜或见天理。","天理天所为，超然绝人伪。","夫谁能举之，聪明与睿智。","兹理何由臻，执事自敬始。"]},{"t":"考室","f":"五言古诗","c":["丁丑孟冬吉，湛子辟烟霞。","虽非鹿门胜，亦携庞公家。","乃开正义堂，乃建崇经楼。","乐阁在堂前，茹芝在楼头。","有亭面西壁，丽泽双泉北。","退轩后洞居，峻洁垂虹侧。","亦或考金钟，亦或击石鼓。","前抚卧龙吟，后引九龙舞。","七曜明天经，三水察地理。","俯仰参两间，其道一而已。"]},{"t":"酬方吏部石泉与烟霞同板筑","f":"五言古诗","c":["石泉在樵东，烟霞在樵西。","同家宇宙内，况复同藩篱。","若欲散沈郁，登高以眺遐。","方子于斯时，不弃来烟霞。","若欲翕发散，入谷听潺湲。","湛子于斯时，不厌过石泉。","春暮方发育，石泉颇幽独。","万水与千山，烟霞堪寓目。","秋冬美朝暾，烟霞颇高寒。","晞发与炙背，石泉宜借眠。","绕泉为盘阻，谁复争子所。","伏虎与盘龙，呵禁乎不可。","诸子游大科，亦须从大路。","有或非吾徒，攻之以石鼓。"]},{"t":"浚烟霞后洞新泉得七石榻","f":"五言古诗","c":["有客晨叩门，劝我浚新泉。","适当连雨天，工暇土脉匀。","发石玉已喷，除壤榻自陈。","布列象斗极，可以坐七贤。","尹公几中尊，次左湛子焉。","邓子居右方，方君左临渊。","甘也接邓膝，南上秩有伦。","馀二若有待，不备惟其人。","清如此泉者，来居无厚颜。"]},{"t":"题万竹台","f":"五言律诗","c":["九龙樵三昧，竹台在九曲。","岩与台近隣，相看爱无俗。","根根一根同，曷以多为喜。","此君正耻独，绕台是君子。"]},{"t":"送赵元默见过烟霞还龙江","f":"五言古诗","c":["南山有隐豹，十日雾雨中。","惄焉忍长饥，引项吸天风。","蟠家曲树底，甘以矢自终。","不啖人间食，卓为汉士雄。","故人扣我关，舒啸凭高峰。","六夕烟霞里，浮云迷去踪。"]},{"t":"题直庵","f":"五言古诗","c":["世有好直者，直行悲途穷。","直视不仰天，直立不俯躬。","若有用直者，如绳无曲木。","如弦有高音，如矢利于镞。","或有徒直者，心不藏丝毫。","与人无可否，于物忘卑高。","我直异于是，用一而化二。","生理本不回，修之敬为地。"]},{"t":"过波罗二首 其一","f":"五言绝句","c":["片帆出扶胥，潮打虎门开。","正爱远山青，白鸟閒飞来。"]},{"t":"过波罗二首 其二","f":"五言绝句","c":["举手望飞云，鸣桡过黄木。","舣舟江上亭，虚空观日浴。"]},{"t":"李亲秉衷过烟霞赠之","f":"五言古诗","c":["抱病烟霞居，与世日相遐。","不见交亲至，惟见白云过。","孟夏风云会，送子来大科。","洞门修且深，窈窕入烟萝。","群彦翕然集，宴饮酣且歌。","警发同文会，言笑靡及他。","岂无欲君意，未敢言琢磨。","不谓即言旋，白云如子何。","贱躯因晨风，饯子山之阿。"]},{"t":"喜东山陈宗享复到山论学兼示诸生","f":"五言古诗","c":["吾爱蘧伯玉，五十能知非。","吾慕卫武公，耄期不忘规。","芳名垂典训，百世诚吾师。","嗟彼誇毗子，沾沾自满攲。","隙光讵全照，掩鉴犹蔽亏。","井蛙不知天，瓮里蒙醯鸡。","日月普空宇，万物含光辉。","高明与广大，临照无隐微。","圣哲崇弘毅，小器非大知。","全功在知性，尽心乃不遗。"]},{"t":"送杨士德还潮","f":"五言古诗","c":["送子翳门关，上上官山渡。","自渡还自济，千圣同大道。","下樵苦不难，上樵苦不早。","有形岂不滞，出入更如主。","短景倏如流，永怀岁将暮。","且莫笑杨朱，杨朱泣岐路。"]},{"t":"何亲邦仁将北上来别烟霞","f":"五言绝句","c":["有客来烟霞，告我游燕北。","送子以愁心，徘徊瞻斗极。"]},{"t":"和杨少默九日怀菊之作用九章韵而约之","f":"五言古诗","c":["采采篱内花，少间复耻独。","采之欲何为，幽香难入俗。","吾衰虑芳歇，岁晏日不足。","薄言采群芳，天地归一掬。","霜高草木黄，孤秀媚空谷。","自非金刚姿，孰致后凋曲。","圣人贵松柏，卫风咏菉竹。","爱此柴桑操，纳尔于大麓。","登高发雅颂，被之三尺木。","手弄无弦君，眦决飞鸿目。","谁能继此曲，此曲情何极。","顾谓二三子，菁莪歌乐育。","一育草木蕃，永言自求福。","我福在百顺，神不疾而速。","四时自运行，天道尚往复。","怀人倘不遐，吾以献芹曝。"]},{"t":"南京刘秋江至烟霞","f":"五言古诗","c":["有鸟振奇羽，周游隘八区。","嗟彼抢榆翅，一枝徒自娱。","素啄秋江水，今将睨天池。","偶值云端树，况是千寻枝。","积风负大翼，殊量非小知。","语君九万程，君志定何如。"]},{"t":"寄题眠云","f":"五言绝句","c":["白云满空山，山在白云里。","心若似云閒，与君同睡此。"]},{"t":"赠四川王公子敬之","f":"五言古诗","c":["嗟予语敬之，敬之当听予。","敬亦无不在，语子敬读书。","当其未读时，天君自俨如。","及其对书册，万象涵太虚。","是谓以我观，勿以此丧志。","舍之求放心，离物以为二。","学问与思辨，古训乃其地。","无在无不在，事事亦如是。"]},{"t":"檃括格物之说","f":"五言古诗","c":["大学崇至善，格物为实地。","格者意身心，是谓至其理。","如彼之国都，亲见乃知至。","平地说相轮，伯淳所以耻。","格之厥功何，知行并时诣。","终日及终身，惟此一大事。","何为齐治平，即前物理是。","万一本同原，体用元非二。","道丧千载馀，支离为简易。","谁能一扫之，敢以告吾子。"]},{"t":"送继宗","f":"五言古诗","c":["陈生古梅秀，三载拜小瀛。","访予避地处，远扣烟霞扃。","云栖百尺阁，明月几亏盈。","经始开书院，置田赡诸生。","冷淡世人笑，在古或垂名。","咄咄夸此子，睚眦愤所争。","持此赠之归，以为乡里荣。"]},{"t":"代简答黄应期太常","f":"五言古诗","c":["故人莲峰子，约我到罗浮。","罗浮众仙人，伫望大石楼。","缥缈度飞云，超然见丹丘。","自我小蓬瀛，可以至十洲。","试问莲峰子，与我烟霞不。"]},{"t":"东山","f":"五言律诗","c":["东山众东山，爱之即我有。","若然不知爱，其土等培塿。","宣尼曾一登，聊以小东鲁。","因君感吾心，吾将随步武。"]},{"t":"菊轩","f":"五言古诗","c":["秋菊已可爱，况复当高轩。","坐轩对新菊，南山见悠然。","此景世间有，所恨难其人。","何期闹市中，聊复见蒋君。","可是元卿裔，三径开白云。","菊吾甚爱之，借轩閒一眠。"]},{"t":"湛泉为张天叙","f":"五言律诗","c":["谁为开湛泉，先得吾姓号。","知是爱泉人，可与结心素。","移居近泉头，对之心益幽。","因达虚明体，于以长泳游。"]},{"t":"与韶守","f":"五言古诗","c":["里奚非智士，公奇为忠臣。","何期数载下，共沐新主恩。","入疆问贤守，高宴具前陈。","忧馀发孤笑，痛定说酸辛。","晴祠拜舜日，愤惋吊荒坟。","愿持精一学，献之重瞳君。"]},{"t":"寿董中峰乃尊八十","f":"五言古诗","c":["我爱东山高，东山有佳色。","匪爱东山色，中有幽人宅。","昔为谢公居，今下董子帏。","丈人日夕往，斑衣此儿戏。","郎今侍仙府，寿以金茎露。","丈人进一杯，我为一歌侑。","歌竟将若何，为祝东山寿。"]},{"t":"侍御林君钺乃尊紫霞先生寿","f":"五言古诗","c":["有子骑青骢，青骢何桓桓。","我马愧不如，谁马气如云。","下马为拜之，因以知其人。","若人抱忠孝，君家有严君。","再试乃卷怀，临世濯垢氛。","我欲从紫霞，遨游于无垠。","聊用谢短世，永以寿千春。"]},{"t":"题双石为郑于成","f":"五言古诗","c":["孤石已可爱，况复双嶙峋。","物情无美恶，损益在所任。","一以砺吾行，一以砺吾心。","砺行得人钦，砺心得神歆。","神人既两协，为谢他山吟。"]},{"t":"送戴员外","f":"五言律诗","c":["戴君工垂佐，业出石镜阴。","邂逅道知素，因忆齐云岑。","国计赴留司，若过桑梓林。","为予借石镜，可照万古心。"]},{"t":"送南京大鸿胪刘克柔","f":"五言古诗","c":["鸿胪出尚方，飘飘下五云。","踟蹰即长路，瞻恋犹枫宸。","朱光发大夏，长养同维新。","阳刚尚微郁，阴姤讵能沦。","两都景不殊，欣戚齐疏亲。","斗杓解斟酌，羲和无停轮。","谁能回元气，祈此万年春。"]},{"t":"题探源","f":"五言绝句","c":["君家在宝潭，潭中有真源。","若欲求至宝，更窥九层渊。"]},{"t":"送李上舍归宜兴","f":"五言古诗","c":["翩翩毗陵子，浴德璧水涯。","十年不入官，藏器以待时。","四海仰明圣，天运转璿玑。","遐不共帝臣，之子亦来归。","观光五云里，际会千载期。","阳德会光大，阴霭尚朝曦。","时事异厝薪，凤凰亚鸡栖。","献璞或见刖，按剑专相疑。","苍苍阳羡峰，微微江月晖。","送子归山中，山中多蕨薇。"]},{"t":"题拟松亭","f":"五言律诗","c":["岳顶亦松耳，托根故不同。","遂为人所慕，拟置幽亭中。","得之亭益幽，浩浩生高风。","若有抚松人，等视无卑崇。"]},{"t":"大理杨司厅调南礼部赠之","f":"五言古诗","c":["番山一时秀，君才似杨修。","况当机云年，文价迈等流。","双双矫云翼，意气隘九州。","中年一垂翅，抢彼枳棘休。","列第太常右，交辉花萼楼。","鹦鹉诉北寒，越鸟思南游。","法星化奎文，一夜光芒浮。","我有停云念，岂无看云愁。","南宫省署静，文苑开清修。","六朝佳丽景，楚尾与吴头。","我祖膺戎狄，山河为增优。","夫何根本地，犹有兵食忧。","大风拔陵木，江涨浮尸游。","今年灾疫仍，千室无人收。","频下修省诏，悔祸天启谋。","此当属春官，送子发长讴。","若有南征赋，可以献纳不。"]},{"t":"赠常德车别驾之湖南","f":"五言古诗","c":["佩玉身若槁，志在朱陵天。","襟怀全楚阔，胸荡洞庭烟。","使君乘别驾，冠盖何翩翩。","去问常德俗，令我心飘然。","圣师问得人，澹台部下贤。","身心是公事，何烦入室焉。","若访蒋生径，宁无切琢言。"]},{"t":"寿杨石翁少师诞日适赐宴礼部","f":"五言古诗","c":["少师群伦表，朗豁夙天人。","骥驹已超类，岐嶷与岳嶟。","蔼蔼文苑秀，皇皇秉丝纶。","垂翅权奸际，云雷见居屯。","藏纳似梁公，龙蛇十六春。","贤者固叵测，终复唐乾坤。","我师富才力，张弛在北辰。","浊河上滔天，清济中不浑。","先皇幸南北，留后报主身。","时与三二公，内外协同寅。","旄头出东南，帷幄坐清尘。","深忧在心腹，岂但宁与彬。","城社杀狐鼠，事势岂易论。","及乎抱弓泣，危疑难重陈。","寅夜定大策，翊运扶紫宸。","圣人御皇极，正诏下高旻。","积弊一旦革，大礼无前因。","众论正嚣嚣，国狗亦狺狺。","处人骨肉间，两宫恩义均。","自非中理解，谁能定逡巡。","天子曰劳止，策勋命谆谆。","三让不拜封，世禄控亦频。","天子自仁孝，手敕加私亲。","从容对数语，封纳了不嗔。","自馀一召对，侃侃复訚訚。","帝亦为之慰，格君可渐臻。","公方论年秩，闭门解朝绅。","帝命加太傅，赐宴倍臣隣。","三四获所辞，乃饮春官醇。","皋夔皆赓歌，殊锡感明禋。","此日是何日，重阳更越旬。","寔维公华诞，岳降生甫申。","福德代不数，无乃天逸麟。","天寿且平格，周召古所伦。","永命在祈天，国脉亦以新。","维时贺宾至，公醉在帝闉。","贵介盛珠屦，所宝惟贤仁。","狄门多桃李，宁无入幕宾。","水也则狂简，滥竽亦效颦。","敬赋南山诗，万寿祝无垠。"]},{"t":"送屠侍御之南都","f":"五言古诗","c":["司寇东湖公，文学饰吏治。","凤毛两翀霄，乘骢乃仲氏。","从予拜乞言，服之为砭剂。","予久拙言词，感君故来义。","请从文厚言，静重如厚地。","卓哉万仞冈，壁立不可比。","青天何昭昭，白日靡霞翳。","雷霆迅奋击，去来复何意。","流水与行云，浩荡行无事。","物情有常则，君行为君记。"]},{"t":"送太常博士李九皋养病还金华","f":"五言古诗","c":["名玉方在璞，隐隐含辉光。","不有卞和子，忽焉终韫藏。","物情有感遇，世岂无明良。","胡为抱之泣，徒尔重自伤。","李君温如玉，独负圭璧章。","我乃他山石，磨琢以相望。","进思正斋居，君已谢奉常。","局促笼中鸟，插翅慕云翔。","金华为益高，浙水为益长。","玉尔明德躯，慰我金石肠。"]},{"t":"谩题送人","f":"五言古诗","c":["杞人忧天亏，共工怒地缺。","天地且反覆，人事何足说。","物理故不齐，人乎天使之。","天人莫之致，此咎将安归。","大易贵时义，蠖屈乃求伸。","危言亦何为，祇以危其身。","去矣勿复道，龙德在存神。"]},{"t":"送梁以顺尹如皋","f":"五言古诗","c":["澧州吾旧契，于子为姻㜕。","况尔朴茂资，古道期跻攀。","兹将牧如皋，令我心惕然。","已闻江南北，饿殍盈郊阡。","静坤为屡震，乾玑失常旋。","狐死兔且悲，骨肉相啖残。","死者未掩骼，生者留孤孱。","古人尚平格，三极谁复论。","调燮自一邑，以为诸牧先。"]},{"t":"汶上县作","f":"五言古诗","c":["沿流及汶上，问是古中都。","宣尼有流化，男女别行途。","有堂表思圣，遗准存圣模。","治者平偏党，学以平卑高。","扩之遂相鲁，东周其庶乎。","水也未升堂，入室安可图。","寄语都人士，希圣无自诬。"]},{"t":"谒阙里庙庭","f":"五言古诗","c":["悠悠宇宙内，斯人独长勤。","谁立万古心，所赖大圣人。","六籍开知见，耳目长得新。","元气岂岳降，此地传绂麟。","佳气远弥蔼，况乃亲炙存。","杏坛沛时雨，高弟集如云。","当时侍讲席，所志皆求仁。","仁也人心耳，五十何无闻。","稽首奠心曲，诱衷希圣神。"]},{"t":"题画二首 其一","f":"五言绝句","c":["吾闻青精鸟，鸣则有大水。","列之在旌旗，为世智者耻。"]},{"t":"题画二首 其二","f":"五言绝句","c":["鸲鹆学人言，翻能避罗网。","人迷祸福途，徒居万物上。"]},{"t":"赠何道亨转北工部侍郎理易州厂","f":"五言古诗","c":["宇宙何寥邈，造化苦长勤。","绵绵初生条，倏忽摧为薪。","采薪须采枝，采薪休采根。","枝伤可复生，根蹶难为春。","牛山既濯矣，乃尚寻斧斤。","斧斤亦易缺，生理亦易灭。","畴若予草木，帝咨益重烈。","往谐周虞衡，咸若夏鱼鳖。","尽物斯尽人，性分在调燮。"]},{"t":"送陈静斋少宰考满","f":"五言古诗","c":["皇穹尚不宰，阴阳运时功。","所以乾坤尊，六子代有终。","蔼蔼贤少宰，庐山起高踪。","昔为翰苑秀，于今代天工。","词华照青阳，玉色倾群公。","扬历遍台省，文武兼折冲。","报政趍当宁，新春向和融。","留都盛冠盖，出饯江之东。","江花发文藻，江水鉴清容。","行矣无迟迟，宵旰正重瞳。"]},{"t":"送都宪高先生总督漕运","f":"五言古诗","c":["飞挽地僵仆，海运天翻波。","圣皇制国计，全功在漕河。","河水亦有竭，民力岂云多。","榜卒晨告痡，及暮靡啸歌。","妻孥终岁别，生死在网罗。","去年千里赤，十室九蓬科。","骨肉且相食，他人将若何。","根蠹花不实，生理宁有他。","君子秉明德，调剂使平和。","干禄有恺悌，刚柔无僣差。","如何民物遂，国祚同无涯。"]},{"t":"送庄西峰还江浦","f":"五言古诗","c":["峨峨定山尊，苍苍出云里。","望之不可即，盈盈隔江水。","何以爱此山，爱此山中云。","涔涔不成雨，念之徒伤神。","定山不可见，得见西峰子。","爱之若定山，聊以慰予意。","之子度江去，渺然一苇杭。","登高赋将归，于以写不忘。"]},{"t":"送陈太仆谢病还福建","f":"五言律诗","c":["暂辞太仆马，采药归武夷。","武夷多异人，九曲或见之。","若逢云谷老，为予重致辞。","精一事久旷，千载空尔为。"]},{"t":"题淮浦为杨敬之太仆","f":"五言律诗","c":["泠泠淮浦水，水清人亦清。","有客来照影，浩然歌濯缨。","岂但可濯缨，坐使心神澄。","无穷川上意，日夜注沧溟。"]},{"t":"陪诸公瀛洲胜会 其一","f":"五言古诗","c":["广宴开钟阜，群彦集瀛洲。","新晴美朝晖，重阴豁然收。","主人爱敬客，感格天与谋。","八榻依云列，眇予岂其俦。","因思竹林会，当时亦何修。","醉心以明德，岂伊杯酒酬。"]},{"t":"陪诸公瀛洲胜会 其二 呈朱玉峰冢宰","f":"五言古诗","c":["吾慕朱修撰，持敬终不破。","千载仰其人，庶以警予情。","蔼蔼玉峰子，云间一硕果。","大华谢雕镌，至性本无作。","桃李自成蹊，此言可喻大。","默默太宰公，恭敬倾四座。"]},{"t":"陪诸公瀛洲胜会 其三 呈赵类庵少宗伯","f":"五言古诗","c":["清献本狷介，琴鹤适相随。","峻洁殊绝俗，家风君独追。","昔予与宗伯，内馆日徘徊。","因兹契衷素，卓然出风埃。","何其廿载下，共把金陵杯。","杯到莫停手，有诏行当回。"]},{"t":"陪诸公瀛洲胜会 其四 呈李蒲汀少宰","f":"五言古诗","c":["翩翩李供奉，世号谪仙人。","帝赍锦绣襟，笔下如有神。","明公泰山秀，鼎甲自宸遴。","不薄南国游，渺渺江东云。","玉堂忝嘉会，律转物华新。","再枉琼瑶篇，涤我胸中尘。"]},{"t":"陪诸公瀛洲胜会 其五 呈何柏斋太常","f":"五言古诗","c":["太常抱荆璞，肮脏尝遗荣。","拜诏感明主，买舟扬越行。","虚疑是何逊，吟笑春风生。","寄怀托秋奕，远心在沉溟。","清修我所师，维以咏周行。","今夕同嘉宴，欲子子心明。"]},{"t":"陪诸公瀛洲胜会 其六 呈郭杏东翰长","f":"五言古诗","c":["当时李郭舟，望者如登仙。","君家在瀛洲，君知然不然。","我本南溟客，家住增城巅。","凡骨久未蜕，阴功六十年。","感子琼浆酌，报以金石言。","神理各保爱，逝水趋东川。"]},{"t":"陪诸公瀛洲胜会 其七 呈陈琴溪少司成","f":"五言古诗","c":["三吴多秀士，藉藉皆贤豪。","元方与季方，雅获一臂交。","昔联翰苑辔，今共璧水游。","季冬木叶脱，已见新萌抽。","群公修胜会，德言亦交酬。","敬赋无衣篇，誓与子同仇。"]},{"t":"于观音阁饯梁天壶宗烈同府","f":"五言古诗","c":["兹辰风日佳，秋空极寥廓。","四美翕然臻，群英亦趋约。","结集逍遥游，临江更登阁。","阁迥江不流，澄心坐超脱。","高歌饯嘉宾，遗响天际落。","展足贵千里，去去崇明德。"]},{"t":"赠唐京兆得命送母还乡","f":"五言古诗","c":["翩翩一朱鸟，毓德祝融丘。","羽映五云色，将母来神州。","亦有游子衣，慈母手中线。","何如京兆君，日日侍亲膳。","天子至仁孝，诏许扶亲归。","亲欢日不足，皇命有程期。","直知归荣欢，勿言别时苦。","我歌北山诗，子为彩衣舞。"]},{"t":"送谢考功显之任福建少参","f":"五言古诗","c":["昔行长千里，欣然得贞幽。","斋分金屋色，门带玉河流。","中有天曹星，光照闽海陬。","丈夫抱经济，及时展才猷。","手挹上林春，去播薇垣秋。"]},{"t":"奉赠叶时举之任广南","f":"五言古诗","c":["朱光正中天，阳和倏南流。","行迈越万里，山川何阻修。","长风负大翼，六月须云游。","遐以酬宿昔，道义敦所投。","夫君工垂佐，一麾守遐州。","踟蹰临岐路，执手野绸缪。","王风四海同，毋曰蛮荒陬。","君其嗣德音，慰此友生求。"]},{"t":"于朱玉峰太宰宅修会得匏字","f":"五言古诗","c":["诸公青云器，鄙人长系匏。","九载面石壁，烟霞与游遨。","知匪适时韵，世网忽复遭。","天官开胜会，满座皆贤豪。","人豪事自胜，蓬瀛何必高。","作者已七人，伊予惭续貂。"]},{"t":"于李蒲汀少宰宅修会得巽字","f":"五言古诗","c":["清风东南来，阳德方在巽。","抚己感时物，天道有常运。","八位皆乘时，万年如转瞬。","荣华逐飘风，柔条为煨烬。","是形岂不坏，万有归空尽。","何以觅真常，至道在贞信。","敬告同盟子，无忘金石论。"]},{"t":"于何柏斋奉常宅修会得牛首秋云","f":"五言古诗","c":["主人且莫言，听我歌秋云。","逍遥望牛首，神爽已翛然。","牛首夫何如，我尝造其区。","坐小西南峰，蒸郁浮翠虚。","人言秋云薄，我爱秋云淡。","淡以明我心，薄以忘世念。","白衣与苍狗，变态竟何有。","此山长尊居，万化有形后。","山高有大云，云大能施雨。","若待春阳时，万物皆煦煦。"]},{"t":"陈琴溪司成于凭虚阁修会得绳字","f":"五言古诗","c":["主人如酒清，未对心先澄。","酒似主人意，不尽来如绳。","清宴依兰若，回席近前楹。","江山献佳丽，乐极悄怀生。","六朝豪俊地，风花忽飘零。","维彼长江水，滔滔去不停。"]},{"t":"送太学生蔡羽归洞庭山","f":"五言古诗","c":["昔我游太湖，欲访洞庭山。","匪为爱僻绝，自古多隐贤。","翠壁浮大泽，洪涛卷高天。","道阻不可致，怅望二十年。","蔡生从予游，秀出西山巅。","爱之如爱山，神爽超尘凡。","虚无指归路，渺渺在云间。","为我卜角里，先扫茅公坛。"]},{"t":"送张别驾之琼州","f":"五言古诗","c":["忆昔张公子，倾盖淮南道。","宛宛青阳色，侃侃金玉吐。","邂逅金陵游，抚臆道衷素。","往来二十霜，头颅各非故。","君今渡琼台，海岸孤绝处。","别驾展骥足，千群看独步。"]},{"t":"题毖斋","f":"五言古诗","c":["三阳舒盛德，万物皆发生。","试问胡乃尔，隆冬闭元精。","天道专乃直，地道翕而辟。","欲会天地心，毖之在恭默。","小毖通神明，大毖天地贞。","毖之复毖之，上下同流行。","查子开名斋，独得毖之义。","不愧此屋漏，可以配天地。"]},{"t":"题东湖书院","f":"五言古诗","c":["中丞谢司空，书院开湖渚。","静观山下泉，因知水来处。","湛然涵太虚，馀波欲东注。","湖光入帘明，照见先生语。","逝者其如斯，自然本无作。","一画起于无，六经皆我注。","自以我自观，自感还我悟。","寄语湖外人，湖源尔当溯。"]},{"t":"赠何公志别驾事竣还湖州","f":"五言古诗","c":["忆予年向立，同君西瓮闾。","尔年方二六，志气千里驹。","君今已二毛，我衰当何如。","别驾展骥足，会计赴留都。","把酒谈故旧，美恶成虚无。","君自崇明德，爱此金玉躯。"]},{"t":"寓思图诗","f":"五言古诗","c":["悠悠寸草心，荡荡三春德。","亲恩比昊天，昊天元罔极。","罔极何所思，目击双坟白。","双坟不可见，游子沅湘客。","泪下斑竹枝，染泪图坟色。","于以寓孝思，孝思本无迹。","体魄归黄壤，神理陟玄寂。","潜思无不通，见之在恭默。"]},{"t":"于中和桥饯毛古庵黄门式之即席赋赠","f":"五言古诗","c":["晨光曜白日，宿雪倏然消。","借问乘除理，阴阳谁与调。","适此中和天，送君中和桥。","此桥君自度，自度还自超。","行行戒多岐，天路谅不遥。"]},{"t":"予友方子思道弃湖广宪佥逃归三衢山筑室以居号逋吏窝寄题数语","f":"五言古诗","c":["逋吏不逋吏，逋吏莫逋心。","逋吏吏身洁，逋心心不神。","不神乃滞物，天理自微灭。","兀兀此窝中，无言自超越。","我则何所逋，八方皆我闼。"]},{"t":"送邹司徒考绩之京","f":"五言古诗","c":["留都根本地，兵食夙告亏。","闻有颜司徒，旋斡如神输。","蔼蔼黄山公，画一守不违。","后先协乃心，会计靡毫遗。","月计一不足，岁计今几馀。","秣马腾槽鸣，壮士歌以嬉。","春光入报政，南风满征旗。","幸承前席问，请进阜财诗。"]},{"t":"送沈宗伯三年考绩之京","f":"五言古诗","c":["草树动微旭，江介清风生。","都城尽冠盖，出饯春官卿。","际此晴和天，矧伊皇路平。","揽辔即长阪，去去觐朝廷。","伯夷典三礼，夙夜惟寅清。","会见神人协，几年南教成。"]},{"t":"送少司空何燕泉谢病归衡山","f":"五言律诗","c":["君来钟山秀，君去衡山高。","问山何以高，为有人之豪。","山高得撑天，炼石可补地。","君今采药行，为我重留意。"]},{"t":"赠人出守严州","f":"五言律诗","c":["五马何跄跄，朱轮何喤喤。","青天曜白日，送子之大邦。","钓台有清风，世远道弥光。","为我一再拜，山高流水长。"]},{"t":"赠彭鹤泉黄门汝寔考绩之京","f":"五言律诗","c":["鹤泉我所慕，爱之如爱鹤。","独立雪山高，意气轻寥廓。","一鸣天以清，再鸣地以宁。","去去淩紫云，对扬在王庭。"]},{"t":"送萧山张先生","f":"五言律诗","c":["萧山何高高，白云何游游。","白云有去来，此山屹不摇。","朝出暮知归，白云为我师。","寄语萧山灵，主人今款扉。"]},{"t":"送陈静斋中丞致仁还泰和","f":"五言律诗","c":["螺川接南浦，岭雪通鸟道。","送君归快阁，因思我来处。","天道好乘除，有来孰不去。","我若归西樵，访子洲之浒。"]},{"t":"于盛符台宅会郑君邦教语及畏暴求为藩僚赠此","f":"五言古诗","c":["潮客金陵游，邂逅谈暴虎。","南山有白额，白日食人脑。","嗟予几不免，藏身入藩府。","非爱曳长裾，惴惴戒馀暴。","地虎尚可撄，飞虎谁能捕。","寄语虐政人，归来学周处。"]},{"t":"送少司空韩信山致仕归东鲁","f":"五言古诗","c":["鲁有柳下圣，士师亦三黜。","直道古难容，焉往而不屈。","送君江水东，正是开笼日。","羁鸟得旧林，安能顾俦匹。","若过展禽祠，为我一拜之。","身屈道弥尊，千秋映馀辉。"]},{"t":"送司马周贞庵之京","f":"五言古诗","c":["北虏瞰天关，长廑宵旰忧。","谁能请长缨，系取单于囚。","挽弧射天狼，拥彗扫旄头。","元戎十乘出，胡骑宵奔遒。","本兵得贤佐，深沉出智谋。","庙堂有成算，群公更运筹。","折冲在尊俎，全功幸蚤收。"]},{"t":"赠少司徒王舆浦之京","f":"五言古诗","c":["负疴颓檐下，嗒然若无怀。","清飙东南来，吹我灵襟开。","舆浦有好音，召命从天来。","邦储得佐理，兵食靡遗乖。","朝廷有正人，四方无厉阶。"]},{"t":"送大司空胡静庵奉诏改掌都宪","f":"五言古诗","c":["平生子魏子，称道十年前。","夙闻艰贞节，兼知文武贤。","倾盖金陵下，初赋缁衣篇。","秋风爽鸠鸣，鸾凤为鹰鹯。","淩厉翀九霄，众鸟皆回旋。","独自持风裁，肃肃都城天。"]},{"t":"送李逊斋冢宰赴召之京","f":"五言古诗","c":["维皇立民极，冢宰为天官。","何名为天官，心亦如天然。","好恶一不作，天鉴何昭全。","君子抱明德，心学自家传。","我素慕其人，神交倾盖前。","一朝简帝心，四海望平平。","山公日有启，野人献无芹。","迹以参商隔，浩浩心同天。"]},{"t":"送冢宰朱玉峰致政还姑苏","f":"五言律诗","c":["丈夫负志气，投笔当封侯。","奇文抱经纬，星斗罗清秋。","甲科取太魁，仕宦至将相。","收身归五湖，鸿飞紫冥上。"]},{"t":"题方西樵宗伯凤鸣朝阳图","f":"五言古诗","c":["朝阳出东方，仪凤正皇皇。","凤鸣自有时，得时为休祥。","会看日中天，普照弥八荒。","照见箫韶鸣，五彩成文章。","宣尼有遗叹，礼乐空虞唐。","何期千载下，重见春官堂。"]},{"t":"题趣菊","f":"五言古诗","c":["菊亦有何趣，趣之存乎人。","花光映天地，自性求灵根。","植根植欲深，采花采其神。","欲辨神灵理，南山已忘言。","我闻子云子，藏心亦云渊。","寄语趣菊翁，难为俗人传。"]},{"t":"题三石","f":"五言古诗","c":["仰观有三光，俯察有三石。","谁能参两间，许尔齐三极。","三极本同原，是名为一体。","世惟精一者，可以与于此。","在天则成象，在地则成形。","无违大父母，子道自完成。"]},{"t":"戊子三月上巳同毛古庵黄门梁天壶长史周纪善诸生游善权三洞","f":"五言古诗","c":["善权善洞府，神仙逸其名。","嘉名吾夙慕，于兹扣岩扃。","地气通灵窍，天神启虚明。","谁能履兹境，可游神之庭。","明公翕然至，如云集诸生。","心同理有惬，景澹心自澄。"]},{"t":"赠马溪田纳言归陕右","f":"五言古诗","c":["圣途日芜秽，宇宙何寥焉。","天下皆尚同，人人信其贤。","自我抱兹独，世贤多烦冤。","蔼蔼溪田子，倾盖独相怜。","见嗟大科训，交契十年前。","邂逅金陵游，载歌伐木篇。","岂伊人事乖，聚散如云烟。","风云安可期，见月忆同天。"]},{"t":"送胡樾冈少司徒六载考绩之京","f":"五言古诗","c":["见君廿载前，倾盖湖西东。","重逢每追想，惚惚如梦中。","君才本明哲，所志在事功。","足迹亘南北，威声动虏戎。","功成尚久次，六七阅春冬。","手持经济策，于以献重瞳。"]},{"t":"送何柏斋少司空应召迁北部","f":"五言古诗","c":["秋高霜露繁，木落雁南迁。","南鹏幸相遇，息养待时骞。","江东送司空，飞盖如云烟。","寒江深碧流，白日曜青天。","瞻望嗟弗及，北斗紫微前。"]},{"t":"董东湖道卿母挽","f":"五言古诗","c":["道义骨肉爱，异姓如周亲。","而母亦吾母，一体同戚忻。","尊慈享善养，况乃及百春。","即化何遗憾，而令吾戚焉。","子爱本罔极，吾母仅八旬。","哀哀蓼莪篇，吾宁为子陈。","显扬乃不朽，相期未死前。"]},{"t":"为牛举人恺寿母","f":"五言律诗","c":["牛生久侍侧，因知慈母贤。","念长衣上线，心苦手中丸。","曷报三春晖，愿寿三千年。","努力显扬事，行道在尔身。"]},{"t":"题都督马君望云思亲图","f":"五言律诗","c":["望云复望云，少间云无存。","云化心不化，如将见其亲。","移忠本在孝，五云扶至尊。","伏波尔世业，狄公为后身。"]},{"t":"送王南渠奉诏终养","f":"五言古诗","c":["王母垂百龄，王子瞻云起。","自兹一日养，岂以三公比。","孝子是忠臣，圣明重孝理。","疏入赐俞允，金紫归闾里。","孝弟人人同，尧舜一而已。","天子崇百年，村落走童稚。","招呼天姥精，寿酒从头起。"]},{"t":"孟母寿诗","f":"五言律诗","c":["既有孟氏子，岂无孟氏母。","经年学不归，寿亲在行道。","暮宿新泉源，朝望滁阳云。","愿酌无穷泉，永言不朽萱。"]},{"t":"答黄生理夫","f":"五言古诗","c":["黄生将北征，停辀问予路。","答云致子知，胡乃更外慕。","纶也避席言，吾心有知觉。","南北又西东，岐径须咨度。","四方与多岐，良知孰带来。","所以贵问学，聪明乃日开。"]},{"t":"送王太常赴京","f":"五言律诗","c":["君随北雁来，又随南雁去。","始悟乘除理，因知去来处。","迟回三纪下，礼乐一朝举。","随子听钧天，谁能插六羽。"]},{"t":"送高司寇之京","f":"五言律诗","c":["日照江水涯，凄风爽鸠飞。","严霜始消尽，正是好春时。","满城送司寇，冠盖何陆离。","登高云雾合，望断继以诗。"]},{"t":"送柴黼庵少光禄进贺中宫笺赴京","f":"五言古诗","c":["云间一青鸟，口衔红锦笺。","遥遥度北极，飞去玉皇前。","之子怀明德，养翮八九年。","大试调羹手，持向紫微垣。","昨宵帝座明，光芒烛中天。","瞻望广寒宫，姮娥正娟娟。"]},{"t":"赴毅斋光禄招游东山翼善寺即席赋此","f":"五言古诗","c":["驱车出正阳，逍遥望东山。","地灵何必高，葱郁浮其巅。","云是谢安宅，莽为梵林禅。","昔时钟鼎地，虚磬空堂悬。","境在豪华尽，时去春自还。","六朝多胜流，衣冠芳草间。","复有争墩子，愚哉一何愆。","衰荣竟奚论，醉歌光禄筵。"]},{"t":"雨中赴杨鸥溪饮清凉山题石壁","f":"五言古诗","c":["清凉如我心，洒落双眸豁。","地高人寰表，天阔诸峰落。","抚境兴已高，何必求庐霍。","暮雨韬天光，朝旭开云幕。","而我以一观，何用不寥廓。","对之已忘言，得意本无作。"]},{"t":"题友泉","f":"五言绝句","c":["举世无可友，可友在山泉。","心若学泉清，许尔来结缘。"]},{"t":"送陈天游京兆致政归浮丘","f":"五言古诗","c":["与君二纪前，看花逐年少。","逢君二纪后，解组去京兆。","君今如冥鹏，我如笼中鸟。","岂不念俦侣，羁迹徒悄悄。","六月奋图南，谁道南溟小。","君若归浮丘，肯访樵云峤。"]},{"t":"送林寺丞升大理寺少卿名有孚","f":"五言古诗","c":["大江淼西来，势浮凤凰台。","凤凰去千载，借问何时回。","送子凤凰西，相看燕两飞。","北风吹爽气，贯城摇清辉。","哲人佐廷尉，刑措期几致。","民物协中和，凤鸟或可至。"]},{"t":"送葛两溪大理赴北","f":"五言古诗","c":["两溪似溪水，澄然清且平。","扬历遍中外，上应执法星。","素手持三尺，五月霜风冷。","若人怀明德，惨舒无容情。","行将是非鉴，努力事廷争。"]},{"t":"送奉常牛西唐致仕归河南","f":"五言古诗","c":["西唐中州秀，秀出金芙蓉。","因君棱层姿，每忆西唐峰。","自君正清卿，接之吾眼明。","见君如见山，矻然两棱层。","北鸟无越想，南翎快朔征。","自得开笼去，安知羁鸟情。"]},{"t":"送吴北川学士召还翰林重脩大明会典","f":"五言古诗","c":["天与锦绣心，岂无锦绣口。","既有锦绣口，岂无锦绣手。","信手摘星辰，开襟见珠斗。","重登白玉堂，经纬罗户牖。","上天抉云汉，五色天章就。","愿开广大胸，点缀周官后。"]},{"t":"送光禄刘毅斋致仕","f":"五言古诗","c":["光禄江阴彦，素业出靖江。","开疆垂百载，维君破天荒。","天道不远人，于人情最真。","好贤与乐义，区区迈等伦。","靖江若桴浮，人烟载浮居。","君今乘桴去，吾欲与尔俱。"]},{"t":"送邹山人归锡山","f":"五言古诗","c":["山人手新编，造我新泉源。","一语尽今古，微言入冥玄。","何以为冥玄，心性维一圈。","非隐亦非显，宇宙何超全。","君今领略后，宇宙在乎手。","万化与万事，敛之亦无有。","有无常相通，一体靡先后。","如彼天地然，高明与博厚。","山人吾爱焉，为爱山之泉。","源泉锡山下，蟹眼长涓涓。","送子归山去，观泉无观澜。","心性如自得，浩浩同渊渊。"]},{"t":"送杨迁乔银台奉诏归淮侍养","f":"五言古诗","c":["淮南靡丽地，门市多纷华。","闭户事太玄，将非杨子家。","寂寞葆清静，上堂致温情。","十年一斑衣，恭命银台省。","陈情如令伯，忠孝帝俞怿。","入门昼锦裳，爱日照颜色。"]},{"t":"为黄理夫寿亲","f":"五言律诗","c":["得道彭祖先，失道殇子后。","得失在一念，修短何足较。","江南八百仙，仙仙可祝寿。","何如握莫穷，天地共不朽。"]},{"t":"题天机感应卷为刘秋官子中","f":"五言古诗","c":["生道以杀人，虽死亦不怨。","因知感应理，不以幽明闻。","为君大书之，用为王道劝。"]},{"t":"送周克道吕汝德入九华兼寄先在山诸君","f":"五言古诗","c":["祝尹开山主，江施擅樾成。","李子尚清修，亦来同经营。","尹生周藩史，长住心期亭。","周吕同声应，翕然迅遐征。","四野云龙集，五星奎壁明。","九华九仙人，举手来相迎。","八君称八逸，归心共惟精。","为山不厌高，山高必有灵。","为水不厌深，水深蛟龙生。","神物贵变化，九仞安可停。"]},{"t":"甘泉山诗","f":"五言古诗","c":["是山皆我乐，何必吾家山。","此山非我有，胡乃名甘泉。","而我有行窝，适在泉山前。","始知天所作，意或遗斯人。","我来陟山巘，翕然集群贤。","谁为引天瓢，谁为酌天泉。","一歃尘虑散，再歃澄心魂。","岂止澄心魂，毛骨皆通神。","安得将此泽，普为天下春。"]},{"t":"东溪诗","f":"五言律诗","c":["东溪何所乐，我乐无东西。","亦复无南北，亦复无高卑。","何以乐东溪，溪月初生时。","乘流观我生，月庭长相随。"]},{"t":"过高仲子思齐园中宴坐","f":"五言古诗","c":["澄心万泉渊，因过仲子园。","时方尚桔槔，抱瓮胡独然。","智或忧不足，愚或有馀欢。","变理畦蔬外，生生对无言。","本自得心性，难为世人传。"]},{"t":"葵轩诗","f":"五言律诗","c":["艺葵复艺葵，艺葵当前轩。","葵心向我赤，我心与葵新。","何以与葵新，维以美灵根。","心心同向日，君家多荩臣。"]},{"t":"题星石亭","f":"五言绝句","c":["在天成星象，在地成石形。","谁能参两间，可住星石亭。"]},{"t":"赠易栗夫归安成","f":"五言绝句","c":["是形有聚散，本心无来去。","如何夜半心，又挂安成树。"]},{"t":"东隐","f":"五言古诗","c":["君隐相江东，东江汇门前。","园涉日成趣，猿鸟相周旋。","问是谁东邻，我屋罗浮烟。"]},{"t":"送张少司成子阳之南雍","f":"五言古诗","c":["昔忝司成席，亦作南雍游。","壁水汇门清，钟山翠空浮。","观光多英才，函丈交问酬。","昔如鱼泳渊，今如鹰上鞲。","君今往持铎，声闻超前修。","为问弦歌地，钟鼓今存不。"]},{"t":"庚寅仲冬三日奉命同大司空章朴庵如西山诸处查看风水因得胜游诗以纪之","f":"五言古诗","c":["恭命历形胜，因兹恣玄览。","仲冬草木落，山色逾古淡。","似我无情游，不爱春芳艳。","天青画幅阔，湖净开一鉴。","遵曲得真源，寻岩履崎巘。","超绝金山巅，寥廓一全瞰。","天山逼斗极，帝座尊而俨。","吾君古尧舜，所务在宽简。","礼乐重留神，制作虑宵旴。","梵宿闻晨钟，悄然动归念。"]},{"t":"赠畅佥宪子实华之西山","f":"五言律诗","c":["山西天下脊，为唐帝皇都。","使君按其地，问俗今何如。","宽简与时雍，于今尚有无。","赠子执中语，政学无两途。"]},{"t":"赠赵惟用分教江阴","f":"五言古诗","c":["吾师闇然翁，一见一百拜。","道高人伦表，忠信世无配。","过乡见乡人，肃肃起敬爱。","矧子久立门，托孤姻娅外。","素衷靡边幅，古器绝雕伪。","持此忠信教，一洗文俗弊。","永佩溪中兰，馨香满江介。"]},{"t":"赠蒋生莅赴镇沅经历","f":"五言古诗","c":["忠信与笃敬，蛮貊云可行。","行迈何壮哉，远涉万里疆。","我心久不远，宇宙如室堂。","华夷本同天，岂不同三光。","此言可书绅，亦可书心肠。","书绅有时违，书心长不忘。"]},{"t":"贺闻人母太孺人六十六华诞诗","f":"五言古诗","c":["今日曷为乐，闻子开寿筵。","小寿逢六六，大寿祈百千。","何以祈百千，不朽无期年。","何为不朽名，圣善流芳声。","母仪自贞则，海日难为兄。","伏生传尚书，卓为女中英。","嘉言不出梱，善行溢家庭。","我为众宾陈，众宾为我听。","兄代弟病毙，母哭子丧明。","一门感慈孝，蔼然为嘉祯。","和德协上下，精诚达穹冥。","仲氏新骑骢，宝应留清风。","帝曰母善是，孺人特褒封。","龙章与凤翟，五色来云中。","风日清大夏，华诞适与逢。","乃悟天人际，感应常相通。","特为王母寿，于以寿无穷。"]},{"t":"为栋塘大人题","f":"五言古诗","c":["美人隔溪岸，岸边双栋木。","高支撑青穹，下荫寒塘曲。","披图动遐想，林深恐幽独。","此中有真境，是为虚灵谷。","有欲往从之，寒泉须濯足。","道逢乘骢郎，问询云中屋。"]},{"t":"送太仆丞陈君钝斋抗疏左迁黄州通判诗","f":"五言古诗","c":["钝斋吾老友，十载拜床下。","抱材恒不售，时已有定价。","叫阍论大礼，不肯诸公亚。","三迁及仆丞，一疏落别驾。","执经睨黄梅，且莫易呵骂。","无住生尔心，可达圣仁舍。"]},{"t":"送夏官正郎伍君左迁安吉判官诗","f":"五言古诗","c":["昔闻云间言，国有古君子。","作者魏陆俦，扁舟五湖里。","翩翩司马郎，遥遥鸱夷裔。","如闻市虎谣，复道投杵起。","垂翼天目游，再奋天门翅。","磨泥在泥中，超然出清泚。","丈夫贵自立，自古多此事。"]},{"t":"送总运李挥使还维扬诗","f":"五言古诗","c":["维扬李挥将，从我甘泉山。","暂尔脱介胄，求闻俎豆间。","文武非二道，折冲即周旋。","今将韬略技，化为转运贤。","异用本同体，君行宜勉旃。"]},{"t":"送周侍御巡盐两淮","f":"五言古诗","c":["圣王公民利，天下为太藏。","盐铁竭山海，山海无辉光。","遂令长者心，千载憾弘羊。","柱史怀忠义，斡旋岂无方。","勇决义利几，载献治平章。"]},{"t":"送汤刘二阴阳领职还乡","f":"五言律诗","c":["吾闻古周官，亦有挈壶氏。","大者赞化育，调燮阴阳理。","大道何洋洋，一阴与一阳。","职思合其德，国士知无双。"]},{"t":"秋官副郎张君允清奉诏归侍其严君天方大夫仲冬七月适遇七十有八华诞之辰予忝旧知诗以侑寿觞焉","f":"五言古诗","c":["昔我北趍召，倾盖过济宁。","一晤语契意，知君自阳明。","兹晨扣我户，告我当南行。","圣明重孝理，俞允侍亲庭。","家君夙谢事，冉冉八十龄。","归当寿筵开，举酒招长庚。","骑鹤众仙人，飘飘吹云笙。","先生正加爵，怡然陶性灵。","一养换三公，讵足为亲荣。","予闻重叹息，世人失其情。","孩提有良知，人爵灭天经。","孝哉张氏子，显亲在扬名。","敬为作此诗，于以侑寿觥。"]},{"t":"送张亭溪少宰终养还蜀","f":"五言古诗","c":["吾爱亭溪好，溪亭生孝思。","溪云悬狄望，溪水照莱衣。","衣中密密线，绵绵念母慈。","寸心逾线长，万里牵慈闱。","拜表昨陈情，微言感天经。","明皇务孝理，辍讲归亲庭。","一养重九鼎，三公为之轻。","眉云喜色动，剑水赐衣明。","慈孝曷相感，天机所由生。"]},{"t":"友兰为张伯彦题","f":"五言律诗","c":["众皆爱兰名，我独爱兰馨。","兰名起人听，兰馨养性灵。","幽兰倚孤石，石边有丛竹。","节砺馨愈幽，君子当三益。"]},{"t":"赠黄门陈应和侃奉诏使琉球国","f":"五言古诗","c":["平生远游志，万里乘长风。","飘飘临倒影，高举淩苍空。","北至北溟北，东至东海东。","何其形迹滞，此愿将莫从。","大鹏罹罗网，戢翼居樊笼。","之子金闺彦，锦绣罗心胸。","文星见眉宇，嘘气如长虹。","又如插六翮，翛然驾高穹。","自言有远役，秉节飞六龙。","何以为前驱，雨师与丰隆。","将命遄朱鸟，呵护先祝融。","予闻为起拜，高歌壮其行。","持被恋入直，安足为士雄。","丈夫志六合，岂在寰堵中。"]},{"t":"题心渔为钱洪甫乃尊","f":"五言古诗","c":["有心不在渔，纵渔亦无心。","所以直钩子，心与寒潭深。","无心亦无弦，吾以忘吾琴。"]},{"t":"寿蕴斋翁陈君华诞诗","f":"五言古诗","c":["两生扣我门，请为陈翁寿。","开图见九老，个个皆耆旧。","三元百八十，共祝千六有。","我寿元无穷，充塞弥宇宙。","混沌在我前，长庚在我后。","持以寿陈翁，可传不可受。","不疾亦不徐，愤捷看下手。","弱水几清浅，蟠桃讵三就。","下视南极星，日月双丸走。"]},{"t":"送程舜敷内翰左迁岭南","f":"五言古诗","c":["道大古难容，斯言得无徵。","子家子叔子，不免涪州行。","而子金闺彦，讲幄侍传经。","一朝丧其朋，同义争死生。","落官万里去，孤雁渺天青。","风波蹈岭海，时复立怔营。","踟蹰望北斗，趍视南极星。","瞻依石翁像，驻楫五羊城。"]},{"t":"已及首夏遂尔寻春与诸同志游胜泉寺时春花已罢遂观源泉怅然啸歌偶而成韵","f":"五言古诗","c":["人生百年内，仅有百回春。","若遭万日劫，倏忽成灰尘。","古人爱春光，可以怡心神。","是春无内外，天地为一身。","何哉浴沂子，暮春六七人。","我游坐迟暮，不见春花妍。","大夏草木盛，生意瀰乾坤。","何以瀰乾坤，四时本同原。","吾以观源泉，啸歌人不闻。"]},{"t":"于礼部后堂同诸公会宴衍圣公得宾字","f":"五言古诗","c":["兹会曷为乐，所乐在嘉宾。","素王有哲裔，蔼蔼温恭人。","南宫荫芳树，宛若杏坛春。","斯文本同家，十哲集如云。","共闻宣圣训，气义即同门。","我尝见羹墙，况接其贤孙。","圣皇重师道，俎豆临成均。","百工骏奔奏，三氏翕然臻。","御宴昭殊锡，初筵亦继陈。","幸逢五百会，文物为一新。"]},{"t":"题邹山人江湖诗舫因以赠之","f":"五言古诗","c":["邹子谈天来，随身带诗舫。","何如坐星槎，浩荡银汉广。","吟弄天婴怀，敲推地劳攘。","天地我虚舟，阴阳荡双桨。","忘言本无诗，超诣天机上。"]},{"t":"送沈大行使山西有事于藩府","f":"五言律诗","c":["三晋多胜迹，唐虞帝王都。","使君往问之，旧俗今有无。","宽简尚熙皞，精一传执中。","咨询如有得，归以献重瞳。"]},{"t":"题芳洲为袁御医作","f":"五言律诗","c":["闻说芳洲好，芳洲吾爱之。","芳洲有名橘，橘井有名医。","名医能医人，大医能医国。","吾怀一寸针，不得起民瘼。"]},{"t":"癸巳八月七日承同志诸君于杜氏园亭饯别对假山见时芳与松柏交发有感即席赋此留别以为诸君赠言之倡","f":"五言古诗","c":["大火变朱夏，微凉递秋阴。","俯睇红芳丛，仰观松柏林。","感此时节改，安得不沉吟。","自强贵及时，流光互侵寻。","众星拱北极，孤鹤遗南音。","所欣宇宙内，万里同此心。"]},{"t":"走笔送刑部谢主事少南改官北上","f":"五言绝句","c":["手持三尺法，气嘘九天云。","岂无造化笔，宇宙能回春。"]},{"t":"寄题沈东园别业","f":"五言古诗","c":["丈人好别业，渺然在东溪。","人号东园公，绮里偕游嬉。","溪梁架飞虹，亭榭还茅茨。","偃坐思贤堂，鱼鸟观鹿麋。","何以爱东园，东园多朝曦。","东园好炙背，东园物先熙。","鸡鸣瑞色动，惊起金乌飞。","金乌既已飞，照见扶桑枝。","左攀扶桑枝，折之为牛箠。","朝牧东园野，夜赋饭牛诗。","以此谢荣慕，岂知尧舜时。","我屋异于是，无南北东西。","洞达开八窗，八风感我帷。","搴帷看时景，乌兔閒追随。","坎止我居静，虚心动应离。","动静随寂感，无为无无为。","丈人闻我言，信乎能不疑。","若询过庭际，谧也能言之。"]},{"t":"题潘司马三锡册后","f":"五言古诗","c":["盘古未分判，乾坤尚鸿濛。","一锡天地辟，再锡民物丰。","三锡人文朗，圣人出弥缝。","乃闻大圣先，三命滋益恭。","佝偻走循墙，铭鼎垂无穷。","莪峰新安秀，簪笏夙显庸。","四方迈宣力，帝锡三褒功。","玺书复叠降，纶綍何殷隆。","父老行叹息，信哉仁者荣。","将以铭肺腑，肺腑难为工。","将以书诸绅，绅亦有违从。","不如志诸册，置座胜鼎钟。","匪以誇稽古，维表事君终。"]},{"t":"治官舍后小圃种蔬大吟","f":"五言古诗","c":["先哲家为山，予独爱坦夷。","后园积土丘，铲高平其低。","我无治平术，仿井理蔬畦。","纵横称疏密，南北方东西。","以兹如我心，周正无斜攲。","抱瓮有代劳，桔皋遂忘机。","老夫自退食，随意行杖藜。","非徒见生意，亦且调燮之。","培灌自时若，雨旸不可期。","怀彼灌园翁，食力无忸怩。","利泽苟公溥，何必拔园葵。","岂无废地力，而况暴殄为。","理蔬不愧高，理蔬不愧卑。","不熟知时馑，举箸思氓疲。","天下尚多山，崎岖不可犁。","安得尽经理，井授无流离。","岂止无流离，乡井无寒饥。","饥寒不切身，礼义生天彝。","四方措兵刑，馨香格神祇。","始知农圃事，是为太平基。","泉叟癸巳冬，理蔬作此诗。"]},{"t":"述先德诗四十韵","f":"五言古诗","c":["维祖奉训初，治中肇德庆。","倦游憩增城，定卜甘泉境。","再传县簿君，民事亦簿领。","元帅出乱季，保障六乡靖。","池鱼贷断死，先期自归命。","他乡绐乞囚，完保士腰颈。","舟师厄苏寇，率义援乃竞。","甘泉名义乡，获免降军令。","孤婴暂微弱，继世复蕃盛。","我祖樵林公，鹡鸰五呼应。","人皆好誇靡，我独乐居静。","冥栖上游庄，林塘互交映。","我师尝卧游，题诗寄高兴。","上苏上游樵，下钓铁江泳。","春至理农桑，蚕熟谷亦颖。","夫人自蚕缫，谷易丝绢并。","以兹广土业，土直宁优剩。","孝友动里闾，行义太丘等。","自兹重乡评，世业保终竟。","显考曰怡庵，高才乃雄逞。","直志靡款曲，正色奸回屏。","强弱以弱强，高义畏乡井。","损己忧人忧，人众天久定。","好士屡济贫，乐友侠游骋。","长洗荤血肠，日啜十瓶茗。","谥妣曰贤母，四十孀居整。","贞智与慈俭，纯诚自天性。","高人阳明子，碑表阐幽行。","恨公不立朝，大节唾奸佞。","水也寔不肖，承德数世永。","每感尹母言，且免咸父订。","妄秉圣途志，岁暮徒耿耿。","特立与群疑，独行耻孤影。","年颓志不酬，挥戈倡予猛。","远道行跛鳖，渊泉汲短绠。","二品蒙素飧，深夜愧私省。","恭逢圣主恩，褒封一朝并。","三世连八座，祖考及予姓。","维昔世田家，迈迹自今炳。","誓当报主恩，出心以为证。"]},{"t":"赠宁波郑太守威","f":"五言古诗","c":["翩翩贤使君，五马仍朱轮。","试问何所之，甬东东海滨。","名郡是宁波，波宁时亦和。","圣人坐明堂，民物无札瘥。","君莫问我言，郡有四明山。","四明如我心，四聪斯豁然。","学山以为明，学海以为平。","平政明照物，颍川凤凰鸣。"]},{"t":"赠大理丞林次厓考绩之京","f":"五言古诗","c":["廷尉八闽秀，意气淩秋旻。","初年入棘寺，抗疏论辅臣。","缙绅皆动色，名誉夷山尊。","中遭长官怒，蠖屈道弥伸。","磨泥出浊水，媚渊光照人。","一作岭表士，贰平天下冤。","尚稽井田制，沟洫入毫分。","岂不有司存，润泽在相君。","三王不同礼，三事古所敦。","此去觐明主，报政因奏言。","民事为国本，笃恭天下平。","食足礼义兴，自馀无足论。","吾衰志明农，圣人起周殷。","复古如有作，愿为受一廛。"]},{"t":"赠季明德左迁辰州","f":"五言古诗","c":["网罟以鱼设，维鸿则罹之。","鱼鸿各有命，乌用尤网为。","季子黑貂弊，贵富会有时。","矧兹性不存，子昔事于斯。","尧舜亦浮云，稷契逢昌期。","丹砂在尘土，一朝发光辉。","何以发光辉，神理可以推。"]},{"t":"云龙吟","f":"五言律诗","c":["食哉兵所天，兵乃国司命。","兵食既两足，二豪来报政。","二人本同心，其利乃断金。","弦琴起瞻斗，送之云龙吟。"]},{"t":"重游牛首山宵行呈同游冼司空罗江","f":"五言古诗","c":["宵征林路黑，七圣亦迷踪。","仆夫随老马，即与吾知同。","大智沛闻见，可以达天聪。","以兹登名山，步步超无穷。","旧游与新游，十载如梦中。","自得新景好，安知旧迹空。"]},{"t":"赠周世清表弟省祭还南海诗十六韵","f":"五言古诗","c":["尔之慈亲家，乃我表姨母。","一体姑舅亲，譬之左右手。","我幼依尔家，直至十八九。","读书学尔叔，深衷自天诱。","微此谁开先，终作田舍叟。","及我显翰林，尔家运不偶。","一兄罹祸罗，二老宵奔走。","尚愧我力微，不能解纷纠。","尔时在弱劣，讵意振周后。","爱尔谨慎姿，贞此三尺守。","怜义不怜钱，狱掾于公厚。","三考入神州，通藉登选部。","省祭归山田，衣冠贲幽牖。","谁莫薄为吏，委吏宣圣受。","曹参以封侯，安期以不朽。","高卑不高卑，太山等培塿。"]},{"t":"赠新举人怀远杨生时秀","f":"五言古诗","c":["翩翩高广文，寄书江东滨。","道逢杨子居，于于来问津。","要津在方寸，平步干青云。"]},{"t":"题两峰书屋诗","f":"五言古诗","c":["两峰在何处，缥渺罗浮东。","鸡鸣海日动，隐映扶桑丛。","中有读书屋，悬崖挂苍穹。","天鉴开龟湖，湖月照九龙。","何以爱两峰，万物一体中。","居两以观一，两峰一峰同。","反观万卷破，一念入无穷。"]},{"t":"题画七首 其一","f":"五言绝句","c":["王母去何处，蟠桃几树幽。","凭君收此画，方朔恐来偷。"]},{"t":"题画七首 其二","f":"五言绝句","c":["洪涛起舂天，天地谁撑拄。","若非画品工，不信中流柱。"]},{"t":"题画七首 其三","f":"五言绝句","c":["盖有千寻木，千秋为栋梁。","安得作大厦，尽庇尔多方。"]},{"t":"题画七首 其四","f":"五言绝句","c":["逝水滔滔去，水流心不流。","舟行戒滟滪，暗石在中洲。"]},{"t":"题画七首 其五","f":"五言绝句","c":["吕纪挥醉笔，能作双鹤鸣。","作者与鸣化，遗鹤在荒汀。"]},{"t":"题画七首 其六","f":"五言绝句","c":["稚子弄影罢，祇供静眼观。","见影不见形，少间亦无存。"]},{"t":"题画七首 其七","f":"五言绝句","c":["我目无全画，翻怜影弄儿。","相怜无了日，相弄无穷期。"]},{"t":"游梅花水","f":"五言绝句","c":["昔观南海水，今见梅花泉。","沛然生我心，因知南海源。"]},{"t":"广德州儒学新建青云楼雅诗","f":"五言古诗","c":["高楼何嶙峋，淩空抉青云。","云间摘明月，海底见朝昕。","试问谁栋宇，广德涂使君。","嗟尔青云子，洒落来凭栏。","见云不见空，变态倏如神。","何以倏如神，是神无长存。","无存还大空，如我心清真。","肤寸起天末，神尧亦放勋。","放勋与清真，可以有无言。","人看云眼青，我见云漠然。","白衣与苍狗，一体相化迁。","立谈取卿相，如平步云烟。","楼外不属楼，天上还有天。","舜禹有天下，所以不与焉。","立己如己高，何以齐泰巅。","以无常观常，常莫为之先。","履危若平地，悠然见参前。","寄语青云子，登楼如是观。"]},{"t":"阳峰","f":"五言古诗","c":["吾爱阳峰子，因之询阳峰。","阳峰何面目，无乃阳峰同。","壁立几万仞，路盘几百重。","秀色入天青，峭削金芙蓉。","匪但爱秀色，阳德当正中。","中山时出云，沛雨瀰西东。","风云一相遇，变化不可穷。","神速在呼吸，调变希神功。"]},{"t":"仰宸楼","f":"五言古诗","c":["仰宸在何处，缥缈奎壁间。","阳山以为经，长江为之权。","经纬应天象，上侵霄汉端。","楼中何所有，天章耀奎文。","回飙吹天花，五色成锦云。","俯首读宸翰，仰面瞻紫宸。","紫宸不可见，心同珠斗旋。"]},{"t":"送大司空何石湖先生乞休还越","f":"五言古诗","c":["宦海挂孤帆，曾联石湖舟。","石湖今到岸，而我犹中流。","五里闻覆载，十里惊石尤。","还家告妻子，色变有馀忧。","出身至卿相，收身相上头。","二疏畏尊名，弓冶有箕裘。","人叹贤大夫，羁鹰脱臂韝。","仰望冥冥翼，神爽与天游。","自非济川材，无成独淹留。"]},{"t":"暮于中和桥玄真观访太行钱采之坐话不觉城门已闭回驾宿玄房得会吴秋官仲敬携酌赋此","f":"五言古诗","c":["阮生泣途穷，不知有回驾。","易贵穷则变，变通道乃大。","达处岂无塞，塞处达斯得。","达塞一以观，何必妄欣戚。","回飙吹我裳，超然坐玄房。","胡为得良友，共此灯烛光。","灯烛同心光，觞酌三相忘。","诣道亦如是，何用而不臧。"]},{"t":"孝思诗","f":"五言律诗","c":["卢生笃孝思，终身念母慈。","绵绵衣上线，见母不见衣。","笑语与居处，优乎见容止。","行道以立身，大孝在吾子。"]},{"t":"送巡按虞侍御还朝","f":"五言律诗","c":["绣衣乘马骢，人好马亦好。","问俗来周南，不践春郊草。","春草春来生，春去愁凋零。","愿言絷其马，使君且莫行。"]},{"t":"送南道宋侍御升真定太守之任","f":"五言古诗","c":["行迈何于于，专城新剖符。","昔骑青骢马，今乘朱轮车。","问是谁刺史，唐时宋大夫。","若人秉明德，福星辉上都。","所重在畿辅，圣主今唐虞。"]},{"t":"寄题心期院诗","f":"五言古诗","c":["心期在何处，十载念存存。","不住五溪流，超然无相前。","无相夫何如，有物为之先。","举手见九华，回头看逝川。","梦中此何景，与我同自然。","前朝谁地主，高人王季文。","昔为讲席地，今化梵林禅。","天道有往复，邪正互相沿。","闻虞并骢马，指顾来开山。","徘徊两书院，仍结心期缘。","黄堂有贤主，吴江诸席珍。","双峰子柯子，同洗金沙泉。","一洗心体真，再洗天地新。","何以天地新，熙穆如初春。","作诗矢心期，他时看浴云。"]},{"t":"送程太守资之南昌","f":"五言古诗","c":["昔在东都时，南守有陈蕃。","孺子本高标，孤榻为之悬。","云卿逾垣来，素飧织屦钱。","三贤久已逝，意气凛犹存。","君乘五马去，缓辔西湖前。","履地若思齐，为我访其人。","君材堪大厦，岂但烹小鲜。","古来多入相，黄霸起颍川。"]},{"t":"送许太守琯之兴化","f":"五言古诗","c":["兴化古名郡，庙为长者留。","何以称长者，筑陂灌民畴。","闻有障海堰，亦有黄公桥。","桥成不自度，鹊去空遗巢。","鱼性恶其网，人情忌其高。","令德全恺悌，吐茹岂刚柔。","民俗望风变，再来段大夫。"]},{"t":"寄题九华山书院","f":"五言古诗","c":["昔年阳明子，为我说九华。","夜夜梦此山，令我胸嵯峨。","九华同一根，是为大极门。","得意何必登，神游九有全。","两君开两堂，二侯为赞襄。","下上如生平，千载同徜徉。","堂在化城外，九华于兹会。","甘泉出堂前，堂胜益可爱。","诸贤若爱泉，人人有真源。","自酌乃自得，且勿信吾言。"]},{"t":"赠少参乔君之陕右昔年乔柱史，抗疏逮金台。一时李陈刘，缧然与偕来。正直且忠厚，邂逅愁颜开。今播陕垣春，凄风为之回寿闻人母王太夫人七十华诞诗","f":"五言古诗","c":["王母下瑶台，开颜宴曾孙。","亦有偷桃儿，闯焉来窥门。","夫人天姥精，圣善女中英。","阳明为之侄，海日为之兄。","盛夏物生长，天地何高广。","有子开寿筵，万寿歌遗响。","何谓寿之道，生生之谓寿。","何以寿生生，天地共悠久。"]},{"t":"送刘祠祭实夫迁宪佥之广右","f":"五言古诗","c":["昔我犹词垣，刘子居黄门。","一挥紫薇幕，为发抗直言。","今我掌南礼，实夫在祠祭。","不减肮脏姿，徐思强人意。","为上不失听，为下不失正。","岂但平贯城，可使天下定。"]},{"t":"福山素心亭诗","f":"五言古诗","c":["福山福何如，百顺之谓福。","左刚而右柔，阴阳合其德。","天一以生水，水泉应心澄。","是名为洗心，是心亦何形。","无形亦无滓，素心无可洗。","吾将携素琴，为君鼓于此。"]},{"t":"题春庵","f":"五言律诗","c":["求春春庵中，春了无可觅。","逍遥坐灵台，生意盎充塞。","问春从何来，来处亦无迹。","化为方寸丹，可起天下瘼。"]},{"t":"送令尹","f":"五言古诗","c":["郎星耀江濒，百里剖符新。","问道乘信车，逍遥入崇仁。","仁者视民伤，割鸡忌烹鲜。","恺悌有干禄，平易为近民。","此地昔多岐，行行戒迷津。"]},{"t":"送李希孟掌教安义","f":"五言古诗","c":["希孟问我言，我言然不然。","语贤以希孟，希圣以希天。","天岂外此哉，万性同一原。","送子去安义，安义斯安仁。","仁义已皆得，遐以不作人。"]},{"t":"寄寿别驾潜庵曾先生华诞诗","f":"五言古诗","c":["罗浮七洞天，增城为近隣。","龟峰与鹤岭，瑞日生紫云。","逢辰思岳降，渺然忆怀人。","若人抱潜德，于我为交亲。","别驾不肯展，凤毛光日新。","望云开寿域，系此斑衣身。","龟以祝奇算，鹤以呈遐年。","我为歌南山，寿之于无垠。"]},{"t":"赠延平太守沈君景明之任","f":"五言古诗","c":["五马何刺史，天曹照延平。","因君履贤地，令我思齐生。","毫釐千里辨，终古有馀情。","为我拜其墓，因之扣天灵。","天灵自不远，参前或倚衡。","之子怀明德，煌煌曜福星。","以兹照民隐，三载治功成。"]},{"t":"题听雪","f":"五言古诗","c":["人皆知雪形，子独知雪声。","雪形知洁白，雪声知轻清。","人皆知形声，我独知性情。","形声得其似，性情契元精。","何以为元精，阴阳无定名。","既已无定名，我诗何足徵。"]},{"t":"赠谢生显归祁门","f":"五言古诗","c":["吾闻谢上蔡，克己最精明。","自谓知本体，主翁长惺惺。","如何习危阶，未去十年矜。","忘助两勿间，天理已自呈。","真机一入手，骄吝何由生。","归哉谢氏子，九万慎途程。"]},{"t":"二子涉长江二章 其一","f":"五言古诗","c":["二子涉长江，采采秋芙蓉。","采之欲奚为，怀彼无极翁。","采花食其实，实里苦心同。","岂但此心同，直外而通中。","自恐采迟暮，凋落随飞蓬。"]},{"t":"二子涉长江二章 其二","f":"五言古诗","c":["二子采芙蓉，因得直通理。","刊落支蔓烦，于以观太始。","尝闻十丈花，孤光映天地。","何以映天地，如船之藕是。","欲窥本来相，来照玉井水。"]},{"t":"江东登舟中流阻风易以小艇乃能抵岸","f":"五言古诗","c":["晓出江东门，遥望江浦埏。","风波咫尺耳，而况万里船。","船大难为用，舴艋吾周旋。","尝闻一苇杭，传说济巨川。","留滞荒洲外，嗟哉行路难。"]},{"t":"谒定山先生祠","f":"五言古诗","c":["巍巍定山孤，高士不入俗。","涔涔定山云，作雨不盈谷。","伊人久云亡，山水留芳躅。","我涂出新江，瞻望宛在目。","涉江采蘋芷，陈词奠衷曲。","蘋芷亦非馨，惟馨在明德。"]},{"t":"观玻璃泉","f":"五言律诗","c":["吾爱玻璃泉，泉与心同渊。","不待酌饮之，心源已涓涓。","涓流作大海，坏土成高山。","山高乃有灵，水深蛟龙蟠。"]},{"t":"泗州夙赴基运山祭告道中","f":"五言律诗","c":["鸡鸣夙严驾，戴月冒秋霜。","皇命事三陵，于焉肃祼将。","踧踖履神地，草莱愁践伤。","生意谅无极，勿使我心慌。"]},{"t":"泗州学讲后作示诸生","f":"五言古诗","c":["圣途久芜秽，吾衰复谁治。","人乃天地心，三才为纲维。","如何餍糠粕，人人醉如泥。","安得独醒者，哺糟啜其醨。","豁然见天地，见南北东西。","见心有六经，见心能百为。","见心本广大，见心本精微。","见心本高明，见心无倚陂。","人心即宇宙，人心即两仪。","两仪与宇宙，吾能握其机。","问机是何为，欲语逼归期。","诸生试自思，反求自得之。"]},{"t":"宿瑞岩道院","f":"五言古诗","c":["悬榻第一山，况在最高峰。","淮流转地轴，高木摇天风。","云卧秋气肃，冥栖晓露浓。","洒落群物表，如身在虚空。","虚空复何有，扰扰将奚从。","鸟欣暂止木，久在樊笼中。"]},{"t":"登泗城北楼","f":"五言古诗","c":["登上城北楼，遥遥望三陵。","王气何郁葱，千载藏威灵。","城面盱眙山，淮泗来绕城。","低回思沐邑，依稀怀镐京。","河流泌洋洋，玄鸟兹降精。","卜年讵有极，祈天岂无徵。"]},{"t":"初宿甘泉山书院楼中","f":"五言古诗","c":["晓下甘泉山，暮宿山下院。","诸贤翕然臻，杏树坛边苑。","超然得予情，楼高原底平。","平原似广大，高楼似高明。","诸贤欲见焉，且须凭楼轩。","各自得自心，吾亦欲无言。"]},{"t":"九日同诸贤登高甘泉山 其一","f":"五言古诗","c":["名节寻名山，四美兼二难。","不知循去步，已历翠微间。","独立在物表，高视乎尘寰。","斯人苦长勤，时去未知还。","高歌发长啸，连山起雾烟。"]},{"t":"芝南篇赠徐子","f":"五言古诗","c":["上上甘泉山，邂逅逢使君。","邀与酌甘泉，意气香袭人。","云生浙水深，家住芝山南。","君子秉明德，馨香发幽岑。","幽岑以韬光，明德在离方。","氤氲塞宇宙，烨熠何皇皇。","一年昔三秀，五百昌期缪。","阔哉何寥寥，绝无而仅有。","灵根入厚地，孤光映穹昊。","藏心美灵根，疾徐应心手。","心手皆自然，忘助一无作。","问何为灵根，此根何处讨。"]},{"t":"九月十一日将从瓜洲渡江游焦山阻风","f":"五言古诗","c":["涉江访焦山，焦山在目前。","风伯有何意，而使不济焉。","不济命乎而，遗予不尽思。","如彼隐德者，缄藏极神机。","草木与崖石，处处皆吾益。","草以观我生，石以砺予力。"]},{"t":"访焦山焦公隐居处","f":"五言古诗","c":["吾闻焦先生，避地来隐沦。","不受天子召，变名匿其身。","当时如弃灰，后世如席珍。","固此一人耳，美恶异等伦。","遗祠依古刹，寂寞江海滨。","因思乘桴叟，夐绝真天人。","安得从之游，究竟所未闻。"]},{"t":"雨登茅山上宫遂宿道院二首 其一","f":"五言古诗","c":["云塞前无路，徐行乃有通。","不知转忽间，脚踏最高峰。","我衣湿寒云，我袖飘天风。","三茅皆失色，万象归玄同。","玄同夫何如，吾以观无穷。"]},{"t":"雨登茅山上宫遂宿道院二首 其二","f":"五言律诗","c":["望山山可怜，到山已忘山。","问我到山意，此意亦忘言。","忘言是忘我，安知山为大。","山上不属山，空中一鸟过。"]},{"t":"赠少司寇潘石泉年兄先生赴召入京","f":"五言古诗","c":["甘泉于石泉，本性同气味。","合是清者流，异派为兄弟。","石泉别甘泉，白日飞黄去。","手持三尺法，五色云生处。","愿酌石下清，为世洗冤滞。","非但洗冤滞，洗彼眼中翳。"]},{"t":"经宪俞子奏最上京诗以送之","f":"五言古诗","c":["秋江秋水清，秋空秋月明。","肃肃霜台客，水月随之行。","明月照子襟，清江濯子缨。","况值清明时，皇路无险倾。","清心以明德，劳谦有终吉。","佝偻走循墙，家庭有遗则。","于己无胜心，于物无德色。","何以上功最，谦者德之益。"]},{"t":"赠倪考功迁任少参之两浙","f":"五言律诗","c":["伯氏乘骢騋，从我游金台。","红尘白日翳，易水悲风回。","爱弟青云器，新参紫薇治。","到家奏埙篪，歌啸致予意。"]},{"t":"偶笔答白川子张秋官嘉秀","f":"五言古诗","c":["东方有白水，西方有黑水。","天地有玄黄，安得有二体。","白水亦是川，黑水亦是川。","同是润下性，万善无二根。","谁来叹逝川，谁来此观澜。","白日白川子，可以洗心言。"]},{"t":"送仪制顾郎中迁山东佥事","f":"五言古诗","c":["仪制本清吏，积弊颇釐革。","吾志在邦礼，尔明赞予力。","以礼达诸刑，伐柯不远则。","尝闻伯夷典，可以折民忒。","五刑属三千，依伦以立极。","以兹协于中，配命在天德。"]},{"t":"赠项精膳迁抚州太守","f":"五言古诗","c":["吾爱项平父，居然受道姿。","自惭立达者，欲人人得知。","之子有至性，谦虚吾不疑。","畏利人称怯，避权时或嗤。","昔在四司僚，今乘千里车。","朱轮入抚境，为拜两贤祠。","两贤问为谁，崇仁与金溪。","其人死不亡，履地当思齐。"]},{"t":"赠医士叶子新还维扬诗","f":"五言古诗","c":["叶生自蒋氏，作用出岐黄。","手持百药匕，捷下回真阳。","造物何小儿，令我病张皇。","痰火炎昆崙，面赭手足僵。","二陈与四物，时医执其常。","之子自扬来，视脉为剂量。","如彼大将谋，应变无定方。","多谢瓜蒌子，洗我腥血肠。","邪涎下数升，正气乃一张。","浃旬水火济，冷焰发辉光。","因兹悟神理，报之合一章。"]},{"t":"过滁州感旧作奉胡时振崔来凤二太仆田叔禾太守兼示二孟生","f":"五言古诗","c":["遵涂出滁阳，望望琅琊山。","昔日阳明子，相期共跻攀。","寂寞卧山房，共话儒释言。","何期廿载下，复此同诸贤。","俯怀丰乐地，壮心与盘桓。","冥搜醉翁处，窥潭有龙蟠。","醉翁醉亦得，蟠龙不可干。"]},{"t":"送大司徒王舆浦先生三载考绩之京","f":"五言律诗","c":["澄澄舆浦水，水清人亦清。","照见公廉慎，照公勤物刑。","委身事明主，三事特一生。","执此行报政，无愧天日明。"]},{"t":"赠唐西洲司徒转北部","f":"五言古诗","c":["君居西洲西，我居东洲东。","东西永相望，中有一水通。","君行北极北，我将南极南。","南北本同天，何用悲商参？","行矣怅予望，望绝继以音。","音书宜慰我，慰我停云吟。"]},{"t":"赠南阳节推陈君羽伯之任诗","f":"五言古诗","c":["才华映青春，行年初向立。","手持郡尉符，溯江胡汲汲。","闻经诸葛墟，为访卧龙室。","何以开诚心？","何以广忠益？","满堂方燕笑，勿使向隅泣。"]},{"t":"送吴纯伯奉诏归侍养宫保白楼翁","f":"五言古诗","c":["吴子秀延陵，拜疏还亲庭。","出门姓字显，归家仁孝成。","上堂事二养，下帷读六经。","孝以顺其亲，仁以成其身。","身亲非二致，致孝本自仁。","我语无徵信，君家有大人。"]},{"t":"赠宁州吏目王君策","f":"五言律诗","c":["昔溯荆溪澜，登歌南岳山。","今见荆溪子，令我心飘然。","之子南岳秀，官卑五马后。","南岳何必高？","壁立有孤操。"]},{"t":"题橘园野仙卷","f":"五言古诗","c":["种橘不种杏，杏多人病多。","橘井有天泉，汲者来自歌。","寄语野仙子，此泉同大罗。"]},{"t":"有瑞堂诗","f":"五言古诗","c":["有瑞复有瑞，有瑞在虞周。","气机一相感，谁辩瑞所由。","邈兹千载下，同气如相求。","下瑞以形化，上瑞与天侔。","洋洋鉴湖水，中有沈隐侯。","闲开有瑞堂，绕堂花遭周。","三葩出并蒂，桃菊葵同休。","鸡冠峨似豸，正色莫与俦。","君子秉明哲，奕世绍箕裘。","阴阳须合德，奇偶会神谋。","达观大化内，天地其同流。"]},{"t":"赠东莞地官正郎李惟肖希说三载考满之京有作","f":"五言古诗","c":["平生子李子，昔会在长干。","世态与时变，旧盟终不寒。","试问何能尔？","恒性若存存。","远迹沧洲外，沈冥白云端。","廿年策天府，三载在郎官。","报政朝天去，嗟嗟行路难。"]},{"t":"题李仲谦昆仲程门立雪图","f":"五言古诗","c":["亭亭高明家，廓然似吾庐。","吾庐夫何如，天下之广居。","入门对两生，无乃游杨欤。","闻有立雪贤，雪深三尺馀。","伊川不可作，举世无师儒。","两生侍立门，又如濂溪徒。","闻有吟卉姿，清风满八区。","世无无极翁，谁传太极乎。","太极在予心，风雪皆真吾。","妆之还灵府，请君卷此图。"]},{"t":"登九华","f":"五言古诗","c":["爱鱼数临渊，安知网罟愆？","爱山见山好，安知上山难？","山高高无极，步步如升天。","有如入大道，疾徐无所先。","无先即高步，造诣何超然？","俯视众山小，洒落如云烟。","特立在中峰，邈矣坐忘言。"]},{"t":"中亭诗","f":"五言古诗","c":["逍遥上九华，洒落山中央。","中央在何处？","山水围书堂。","中坐得中心，中道靡狷狂。","有如诣道者，广大极高明。","幸逢贤郡主，导我从施汪。","施子撰杖履，凌空步中冈。","道夫起中亭，倒影临天光。","昊天及明旦，游衍共出王。","人人有泰山，毋曰让未遑。","我诗●崖石，千秋永不忘。"]},{"t":"过柯双华侍御山居","f":"五言律诗","c":["如我爱双峰，到眼心会景。","爱此峰下人，苗秀方实颖。","云开山露光，云合山色屏。","开合如我心，对之心数省。"]},{"t":"醒老亭诗","f":"五言古诗","c":["谁能名醒老？","阳明独名之。","醒老何以名？","举世醉如泥。","大醉天地昏，小醉丧威仪。","安得独醒者？","哺糟啜其醨。","一醒撤人机，再醒撤天机。","天人既已撤，天地同无为。","天岂去此哉？","先训有家遗。","种秫不种林，秫解忘忧时。"]},{"t":"访静斋少宰陈公书院","f":"五言古诗","c":["凌厉江湖风，风波靡时定。","舍舟扣静斋，斋境与心静。","何以得予怀？","静乃天之性。","看竹如主人，君子予所敬。","凭虚上高楼，楼上閤愈。","仰入飞鸟门，俯鉴蛟龙井。","诣道如是观，超然发深省。"]},{"t":"过梅岭感兴 其一","f":"五言古诗","c":["步出折梅亭，行行且停停。","喜望桑梓迩，肃肃迅霄征。","回思昨宵火，旅魂为怔营。","不能亟极救，如我伤群生。","一城焚尚可，四方若为情。","谁挽天河水？","谁灭天火星？","毋曰既焦烂，乃尚可回生。"]},{"t":"过梅岭感兴 其二","f":"五言古诗","c":["步过梅关西，忽忽如梦归。","屈指十五年，始踏乡土坨。","爵新人惟旧，安足为盈亏？","维有耿耿心，七圣不能迷。","七圣如皆迷，神明自合知。","手写王道疏，奉赋同游诗。","岂谓天盖高？","自是诚悃微。","乘流下曲江，矢心酌武溪。","焚香拜两贤，俯仰正悽悲。","悽悲无奈何，歌啸徒嘘欷。"]},{"t":"过清溪黄太学生绣绪宸谈异泉之胜作此以为他时往观卜筑之张本","f":"五言古诗","c":["吾爱三黄生，排闼临清溪。","吾爱清溪水，浣此胸中泥。","泥滓消且尽，心月澄光辉。","还闻山上泉，灵异天下奇。","朝夕应潮起，其声隐如雷。","乃知气机鼓，通窍靡高卑。","此溪何所自？","此泉何所为？","因悟一本理，共君契玄机。","吾欲卜泉上，相与日追随。"]},{"t":"望罗浮","f":"五言律诗","c":["人事百窘迫，望山心一怡。","苦乐本无门，惟人自召之。","祥禽厌雕笼，幽鸟择高枝。","鹪鹩乃自足，琐琐亦何为。"]},{"t":"罗浮四诗 其二","f":"五言律诗","c":["北风吹宿雾，天宇何寥廓！","罗浮众仙人，为我开云幕。","簪笏非素心，泉石有夙约。","得所自得生，忘景亦忘乐。"]},{"t":"罗浮四诗 其三","f":"五言律诗","c":["步步上飞云，一步度一●。","●尽见真源，一切了缘业。","下看金鸟忙，长啸玉兔捷。","而我本无为，宇宙同超越。"]},{"t":"罗浮四诗 其四","f":"五言古诗","c":["昔欲卜朱明，以为元明宅。","非为绝人境，远道迅所适。","凿石开院门，搴萝补石隙。","闲携二三子，来共散书册。","念此三十年，志愿会须得。"]},{"t":"兼卜朱明两洞","f":"五言古诗","c":["遂卜朱明西，乃兼朱明东。","东西如日月，天地普悬同。","何以爱东洞，虾蟆起青空。","何以爱西洞，麻姑笑芙蓉。","朝日未出时，先见东海红。","新月欲吐夜，坐待西岩中。","日月互来往，吾以观无穷。"]},{"t":"丙申十二月七日偕文明府汤县博伍太和诸友同游娥眉山莲花洞有作","f":"五言古诗","c":["淩晨巾我车，天宇极清廓。","闲从同心人，莲洞视兴作。","兴作夫何为，讲堂开正学。","正学谁同心，令君与县博。","共结逍遥游，散此无怀乐。","天路入虚无，地势干碧落。","三心浣飞泉，千仞书石壁。","遥望飞云峰，忆我朱明宅。","浩气穷八纮，聊兹寄鸿迹。"]},{"t":"再宿莲洞作","f":"五言古诗","c":["吾爱娥眉山，娥眉淡不如。","吾爱莲花蕊，花光映太虚。","出门重延望，随意命柴车。","淩虚入鸟道，绝境寻吾庐。","入暮迅登陟，志往忘崎岖。","后蹑聚星石，前望三台虚。","侧身度飞流，秉烛观崖书。","险尽履平地，孤笑多艰馀。","枕簟依云岫，玉露沾衣裾。","衣裾沾尚可，毋使愿相违。"]},{"t":"美邑尹文侯诗","f":"五言古诗","c":["尝闻恺悌人，刚柔靡茹舍。","厥德用允修，是为循良者。","吾增今文翁，纯然用德化。","莅顽有笑谈，琴堂无叱吒。","发摘钩筒外，挞辱莆鞭下。","游息吏治馀，燕喜乐育暇。","开我莲洞堂，定我赡田价。","诸生日云集，斯道亦风播。","以仁化不仁，不仁当避舍。","泉叟敬作诗，循良绩以大。"]},{"t":"观清溪灵泉书院刻崖石","f":"五言古诗","c":["暮泊清溪隈，朝登凤凰台。","凤凰去千载，遗台尚崔嵬。","肩舆向名山，春山花烂然。","如锦屏匝地，如剑戟插天。","上山觅灵泉，灵泉有如神。","我到泉倏来，阐彼舆皂言。","此泉应潮汐，莫或爽时刻。","其动若雷殷，其止若龙蛰。","爱泉者黄生，开我甘泉亭。","甘泉与灵泉，同以天一清。","留诗刻泉上，清者来濯缨，于泉何损增。"]},{"t":"题曲江新定行窝壁","f":"五言古诗","c":["宣尼救世心，爱人何汲汲？","人或不受爱，伐木仍削迹。","虽则仍削迹，亦爱不终息。","倾覆与流离，吾道自正直。","嗟予亦何人？","弄影韶石侧。","昔拟相江院，今为行窝室。","成物固不能，反躬当自力。","圣道大如天，渊深安可测？","澄澄相江水，此心或能识。"]},{"t":"竹松清荫诗","f":"五言古诗","c":["尝闻斐君子，外节以中通。","虚心应霜雪，夷险无春冬。","又闻髯大人，柔外且刚中。","霜雪莫之陵，雨露无全功。","以兹庇本支，不与时芳同。","遥遥念先德，毋忝尔芳踪。","若欲问圣学，诣学竹与松。","何以学竹松？","生理一无穷。","刚通本阳德，去去成群龙。"]},{"t":"题天泉书院壁示诸同志","f":"五言古诗","c":["逍遥访名山，早晚至天泉。","天泉夫何如？","天一为之源。","天以一而清，泉以一而灵。","物以一而生，心以一而明。","明者天之德，三才同一极。","自德还自昭，天然绝人力。","此泉君自酌，自酌还自得。","中味鲜能知，人莫不饮食。"]},{"t":"至福山书堂示诸学子诗","f":"五言古诗","c":["趣程访先贤，迤逦寻福山，灵境惬素心，恍疑梦寐间。","奇秀万交目，吾心一以閒。","问心何以閒？","万有性不存。","所性如兼存，万物同浑然。","一石砺心确，一花应心妍。","有鸟对关关，有泉同涓涓。","风云恒变化，我心自存存。","为语山中人，诣道以我观。"]},{"t":"婺源五岭诗","f":"五言古诗","c":["春山绣芙蓉，闪烁入青空。","我来乘云车，缥缈行空中。","芙蓉临对镜，镜光花愈胜。","未见本来面，更须学山静。","静坐看羊队，羊化石空在。","石吾甚爱之，勿使羊践坏。","德胜非人力，而乃见天则。","是德何必胜，日用常饮食。","新岭德胜前，问新何以然。","盛德乃日新，春花自年年。"]},{"t":"题复齐云甘泉旧名","f":"五言古诗","c":["齐云有甘泉，似为甘泉设。","此泉有本源，迸出山石裂。","维甘隽不坏，维泉流不竭。","不竭与有本，问我如何说？","安得挽此泉，尽救天下渴。"]},{"t":"宿斗山书院诗","f":"五言古诗","c":["频年瞻北极，今夜宿斗山。","缥缈入飞磴，超然出人环。","群峰绕列宿，宛在天中间。","居中以应外，比如我心然。","经纬皆文章，后地与先天。","山鸟不尽宣，山花不尽妍。","惟以友求心，圣功妆大全。"]},{"t":"宿和州香泉书院题壁兼寄州守鲁君承恩","f":"五言古诗","c":["卓午辞和川，暨暮宿香泉。","秉烛寻名胜，冒雨淩寒烟。","烟霾鲁叟磬，雨湿梵堂禅。","香泉问何如，温温如暮春。","因动浴沂想，鲜见浴沂人。","何以鲜其人，浴法人莫传。","一浴净毛骨，再浴清心神。","三浴日月光，天地与偕新。","天地既已新，人世无妖氛。"]},{"t":"登峄山感怀 其一","f":"五言律诗","c":["吾音读禹贡，梦寐怀峄山。","今我履真境，亲见胜陈编。","古来穷理人，诣道亦复然。","归来束六籍，面北坐九年。"]},{"t":"登峄山感怀 其二","f":"五言律诗","c":["上下峄山峰，危石度千重。","回头倚岩坐，洒落观大通。","何名为大通？","是身在虚空。","欲归前无路，插趐凌天风。"]},{"t":"登峄山感怀 其二","f":"五言律诗","c":["山阳觅孤桐，孤桐已无树。","虽有千年凤，未知栖泊处。","琴瑟非爱身，太和没六吕。","惟有桐上月，古今自来去。"]},{"t":"登峄山感怀 其三","f":"五言律诗","c":["岩花非可爱，爱之在吾心。","是知真爱处，不在丛花林。","爱花无甚浅，采花无甚深。","问花莫问道，问我深浅吟。"]},{"t":"登峄山感怀 其四","f":"五言律诗","c":["颓垣带峄山，门是纪子郭。","有德不在险，胡乃大去国。","狐狸穴姬垄，猿鸟悲日落。","乐极哀忽生，凄风满寥廓。"]},{"t":"望西山吟示周生荣朱","f":"五言古诗","c":["西山昔爱我，山色如眼青。","今我爱西山，眼与山色明。","山色何为明？","雨后风廓清。","风雨几千度，变易尘与土。","尘土尚变易，人奚不速老？"]},{"t":"题黄中丞公求放心轩","f":"五言古诗","c":["崎岖历荆棘，危途度百千。","道遇安崖公，爱我求心篇。","问安为安崖，不答心坦然。","求心不求心，安安无所先。","君看石头路，险滑不扶颠。"]},{"t":"赠毛后军捧 表之京","f":"五言律诗","c":["闭门谢诸贤，吾亦欲无言。","毛苌对门居，世契知我焉。","我心如月光，随子朝天行。","谁云有凤德？","但闻歌楚狂。"]},{"t":"送胡舍人立之","f":"五言古诗","c":["首夏破群咻，相从金台游。","高秋慰孤寂，相见江东楼。","炎凉变时节，人事安足谋？","匹夫不夺志，志士忘在沟。","达大人无我，独立谁朋俦。","至道本无体，天地与同流。","子去崇明德，吾当行归休。"]},{"t":"送徐枫冈廷尉考绩之京","f":"五言律诗","c":["冠盖何煌煌？","江东送飞黄。","青青枫树林，倏尔染丹霜。","●明照君心，瞻望綵云深。","廷尉天下平，吾以啸且吟。"]},{"t":"送总督宋中丞南塘公入坐院诗","f":"五言古诗","c":["同年宦中外，于今馀十人。","揆之三百中，三十能一存。","其馀未可计，零星与飞烟。","倦鸟思白云，健鹗翀青天。","云散何时合？","高歌开别尊。"]},{"t":"与苏年兄乙峰言别时乙峰报政北上予亦将南归","f":"五言古诗","c":["君家西北边，我家东南埏。","风云偶相会，离合三十年。","云生本无根，风来亦何门？","变态不自由，所慰元同天。","兄移北斗下，我思南斗前。","同心同广居，东西南北人。"]},{"t":"送少司徒静庵公迁北部","f":"五言律诗","c":["我身虽在外，乃心在皇室。","夜夜望帝星，朝朝瞻舜日。","闻公有召命，邻寀来相庆。","我心如日星，随之掖垣省。"]},{"t":"诰封刘母孙太淑人七十寿诗","f":"五言古诗","c":["何物女之贤？","生两文武姿。","伯也提干戈，仲也习书诗。","遥闻蟠桃宴，正是春花时。","綵服两阶舞，天姥千年辉。","伯氏为吹埙，仲氏为吹篪。","王母开颜笑，礼乐母亦知。"]},{"t":"三月五日同曾惟馨郑世迪诸君游三山寺观白鹭洲","f":"五言古诗","c":["公馀静扃户，倏忽已春暮。","生意尚可观，诸子扣门告。","肩舆遵江曲，轧轧向何处？","三山在天外，以远人莫到。","如彼幽深士，不入俗眼妒。","鸡鸣迅宵征，近午起风雾。","将天秘神景，诫此浅士露。","幽閤临长江，中洲蹇独步。","吾欲观逝川，于此巢云构。"]},{"t":"答江山何伦柴惟道徐贤三生问自然之说","f":"五言律诗","c":["客来问自然，本体已见前。","本体何面目？","见之亦至难。","至难有至易，忘助两无间。","两在故不测，而乃疑于天。"]},{"t":"赠南京大理寺正澹轩戴君升任柳州府太守诗","f":"五言古诗","c":["皇化渐以普，风气日以开。","昔时荒服地，今日须贤才。","蔼蔼贯城彦，五马朱轮来。","问俗柳江头，柳树何人栽？","春到柳眼青，君来春意回。","无然蹙其根，而使枝叶摧。","君看甘棠树，遗爱何悠哉。"]},{"t":"赠麦前军升任山东盐运同诗","f":"五言古诗","c":["吾欲观太山，苍苍天际头。","吾欲望东海，浩浩连天流。","鸡鸣日观晓，日动海光浮。","照见负盐子，嗟嗟齐相谋。","利国日以始，强兵日以起。","利害互纷拿，无乃盻于此。","选君二盐运，以君能守已。","畴昔倅临吉，止饮清江水。","以此二盐运，寸心群职尽。","子行愈峻洁，性有无穷分。","君看贪墨徒，乡评如秽粪。","太山千仞崖，可以振尘衣。","东海万里流，可濯足底泥。","我若遂东游，与子一共之。"]},{"t":"送考功君南乔参藩广东诗","f":"五言古诗","c":["高鸟亦血肉，羽翼能天飞。","轻车本枯木，骖服能陆驰。","为政在得人，至治以无为。","如彼在一体，指臂恒相随。","达人贵远识，智士炳先几。","无事应大事，畴可与子期。","帝命将普泽，先济东南隅。","失我左右手，我心宁不悲。","福星照吾广，维以慰我私。"]},{"t":"赠侍御沈君南湖佥宪之山东诗","f":"五言古诗","c":["吾庆南湖子，汪汪似南湖。","不以澄而清，而况澄定乎。","袖有双龙剑，身佩明月珠。","珠以明宝善，剑以断奸谀。","清以濯群溷，定以怀永图。","君行有遗则，邹鲁圣贤都。"]},{"t":"诫子诗","f":"五言古诗","c":["忆尔年四五，期尔为圣贤。","尔时亦不辞，冉冉岁相迁。","志学及弱冠，变化忽不然。","龙猪异其质，速利日牵煎。","如藤缠葫芦，所得遂忘天，岂特遂忘天？","于亲亦忘焉。","忘亲都非子，忘天者非人。","哀哉为人子，回驾今勉旃。"]},{"t":"送地官大夫受庵周君谦之迁任云南诗","f":"五言古诗","c":["五马乘指南，万里何阻脩？","溯沿到岷峨，无乃一源流，因之望滇溟，山川郁相纠。","地远俗维迩，道同政易谋。","先王重柔远，行矣壮才猷。"]},{"t":"送黄左军迁任石阡知府","f":"五言古诗","c":["左军滇溟秀，剖符石阡守。","云贵本同宾，如乡东西道。","云山识旧面，回马知熟路。","何况谙土俗，善政因俗好。","君行毋谓遐，二方随左右。"]},{"t":"送中舍谈君相●祭江香祝至南都竣事还京","f":"五言律诗","c":["相见十载前，君颜宛青阳。","相逢十载后，我鬓则已霜。","邂逅道衷素，今昔徒慨慷。","万里禋江使，青天一炷香。"]},{"t":"与成孝子诗","f":"五言律诗","c":["操刀取肝时，心手两不知。","一念但知亲，安知亲之肢。","不识不知处，可以观天机。","自兹通神明，成子其充之。"]},{"t":"赠职方澜石梁君擢宪副之广右诗","f":"五言古诗","c":["平生澜石子，表表冠时贤。","衣葛深怀玉，成蹊以不言。","澜心不足清，石胆不足坠。","持此清坚操，本兵空诸边。","遥边尚折冲，况理宪台前。"]},{"t":"题日惺斋为杬上舍封兼似乡进士郑世迪","f":"五言古诗","c":["日惺名尔斋，尔心日了了。","天理日流行，天运日旋绕。","心日日日惺，神理日日妙。","一惺明德昭，太虚游八表。","退藏外昭心，声臭不闻睹。","惺惺斯不惺，长夜何时晓？"]},{"t":"题曹宁波太守语所藏吕泾野八分书大科训规因以赠之","f":"五言古诗","c":["宁波守执持，爱我大科规，既爱我规条，爱我叙规词。","规条如布幅，叙规如线属。","心几善恶间，敬肆隔云陆。","敬肆慎心几，叙规象施为。","规条应万事，为郡张四维。"]},{"t":"书尹黄门相二代敕命册因以赠之归嘉鱼","f":"五言古诗","c":["黄门清楚客，于于手一册。","大哉称皇言，褒衮何烜赫。","先德以流光，子道益辉煌。","荣亲岂外求，道在立身藏。","道大配天地，全归本无二。","楚山为增高，楚水为增驶。","伏读不见文，惟见两亲存。","亲存以不朽，永矣感皇仁。"]},{"t":"赠和州同知前秋官胡君","f":"五言律诗","c":["和州贯城彦，旷别语合意。","因语知同心，又知理无二。","慨共唐虞天，君相都俞事。","敬哉达上下，民与诚和治。"]},{"t":"赠张君惟行恕尹温州平阳县","f":"五言律诗","c":["吾欲登雁荡，因之临温台。","日月凌倒影，飞锡乘风来。","闻子试牛刀，莞尔襟怀开。","弦歌道有闻，亲见淳风回。"]},{"t":"洪器之梓寿亲","f":"五言律诗","c":["昔憩斗山城，俯视老人星。","还歙多老人，大老百二龄。","我寿本无极，宇宙同生生。","为子侑寿觞，将亲过大庭。"]},{"t":"邵武画士方烨为予作真，予不自知其肖否？若作从游诸生以及厮役，无不曲肖","f":"五言律诗","c":["尔能画我形，能不画我影？","形影既能画，盍画心神境？","心境高同天，心境大同地。","能画天地心，万物可能备。"]},{"t":"戊戌八月四日甘泉子再登牛首山，同游者：洪生梓、郑生经哲、张生文海、洪","f":"五言古诗","c":["驱车曷宵征，感兹秉烛游。","不见牛山春，登高爱清秋。","秋高爽气发，雨后炎嚣收。","鸡鸣群息动，时去众芳休。","达人究终始，故与天同流。"]},{"t":"题西溪卷为俞进士宪乃祖","f":"五言古诗","c":["何以慕西溪？","因见西溪派。","涓涓照人清，澈底清可爱。","弄艇西溪云，月出东溪外。","不见溪畔翁，溪月长相待。","永以贻孙谋，濯缨溪上流。"]},{"t":"送闵仪制旦考满入京","f":"五言古诗","c":["昔在春官年，礼义尚相先。","堂属如一体，斯道共钻研。","闵子于此时，执侍以周旋。","自谗之昌矣，志士若委靡。","日月递昃盈，天地互泰否。","闵子于此时，自反能不惴。","手持天官最，送子朝天去。","感慨难重言，言亦不尽意。","意马防风奔，子其慎御御。"]},{"t":"永思为仪制闵主事旦","f":"五言古诗","c":["永言谁孝思？","孝思思维则。","其则亮不远，反求自天德。","大孝终身慕，自慕终自身。","手足未启前，履薄如临深。","跬步一或忘，不孝与不仁。","不仁者违天，不孝者违亲。","违亲斯不孝，违天斯不人。"]},{"t":"走笔偶赠省元唐子元殊","f":"五言律诗","c":["桂林一枝秀，晖晖清照人。","勿使藤蔓之，可以干高旻。","大临驾六翮，遨游出风尘。","太远不速归，归人念倚门。"]},{"t":"寿大司空蒋公石庵七十华诞","f":"五言古诗","c":["寿公以长生，煌煌两生祠。","生生之谓寿，父母多仁慈。","湖南与江北，处处遗去思。","以兹寿国家，可永万年基。","及乎作司空，六府思若时。","讵能以淫巧，艺事执相规。","●历遍中外，而今跻古稀。","岂逐少年行？","寿耇古不遗。","稽谋能自天，天子自深知。"]},{"t":"赠地官大夫丹山子赵君迁曲靖太守诗","f":"五言古诗","c":["钟山郁苍苍，依佩丽且光。","侯今万里去，谁与予翱翔。","君心江月白，我念滇云长。","云龙乘大泽，油然生霈雱。","西郊久不雨，帝念施远方。","柔远以能迩，此道自虞唐。","忆昔江门游，圣途共相将。","一日期千里，衰老未升堂。","各自笃初敬，之夷不可忘。"]},{"t":"送少司徒王公鹤亭先生考蒲之京","f":"五言古诗","c":["鹤亭海鹤姿，独立未入群。","依然在人寰，翛翛见风神。","古来贤俊者，气习不能沦。","夫君京洛士，衣袂无淄尘。","屡迁不入朝，留都邦计新。","报政或前席，赢绌具能陈。"]},{"t":"戊戌十月二十八日，携徐生世礼、夏生仲、王生奉、黄生耕、黄生牧、刘生誉","f":"五言古诗","c":["鸡鸣出夹冈，过午入上方。","出入寰阓内，如虱处裈裆。","词客悲摇落，俗子爱春芳。","达人玩生意，寂士空坐忘。","我则异于是，大观与时行。","携我八九子，冉冉惜流光。","不因驾言出，焉知草木黄。","王谢俱尘土，●上亦荒凉。","进修贵及时，游衍与出王。"]},{"t":"钟石诗","f":"五言古诗","c":["钟石似钟石，实心历霜星。","鸿钧太古色，直截幽人贞。","幽贞之所庐，钟立四无欹。","怀玉为之纽，玉流为之椎。","君子曷似之？","实以比其德。","特立砺坚操，磨磷终不易。","至乐若无声，一鸣天下惊。","小大随所扣，宰公在司成。","万石之洪钟，维以警聩聋。","夜半攒眉起，昊天日升中。"]},{"t":"奉次舆浦王公冬至前二日韵","f":"五言律诗","c":["剥馀天亦复，天地讵无心。","独观剥复几，千载逢知音。","流行与充塞，浑沦曷升沈？","此事无声臭，茫茫何处寻。"]},{"t":"送长泰尹郑明府赴任便道归省诗","f":"五言古诗","c":["渊明令彭泽，百里去柴桑。","心为醉秫田，折腰乡里郎。","何如郑长泰，违家五日强。","起居可迎养，甘旨得相将。","况有好兄弟，孝友溢庭堂。","由家达之政，一邑见循良。","行行念赤子，竹马迎道旁。"]},{"t":"送符生士亨还南昌三章 其一","f":"五言绝句","c":["十年别子面，千里忆子心。","子心既已见，慰我一何深。"]},{"t":"三凤吟赠伦白山司成送母太夫人还乡","f":"五言古诗","c":["穗城有三凤，五色具文章。","上止三珠树，百鸟惊回翔。","仲氏鸣壁水，将母还离方。","离方朱鸟地，昼锦同辉光。","何时复来仪？","圣人坐明堂。"]},{"t":"题克斋为王奉常炜","f":"五言古诗","c":["奉常有清卿，斋居名曰克。","顾名以思义，思之吾未得。","得非孔颜徒，为仁在一日。","夫克亦何名？","精军以胜敌。","虎贲三千人，一心同一德。","所向尽披靡，不追亡逐北。","何名为精军？","天理乃天则。","颜氏事斯语，养锐有馀力。","至明且至健，勿之不容息。","中军如不精，空拳控勍贼。","天定人亦泯，吾语克斋克。","或言道何克？","能事非持国。","天理天所为，自然本无作。"]},{"t":"赠表弟乡宾陈爱月还甘泉诗","f":"五言古诗","c":["君从甘泉来，色带甘泉云。","今我梦甘泉，悠然得我心。","忆子从予游，十五映青春。","予今各老大，卓立冠乡宾。","不远四千里，访我憩新泉。","倏尔告还山，了此儿女缘。","江风与江月，赠子吟弄船。"]},{"t":"晓如惠化洞会送吕汝德书怀兼似刘子实","f":"五言古诗","c":["晨出安德门，超遥度长林。","恰恰闻鸟声，欣然得予心。","此鸟意何切？","有如求友生。","千载望三益，异道故相嗔。","感彼谷风篇，再拜谢义禽。"]},{"t":"赠春官许仲颐之京","f":"五言古诗","c":["江东盛才俊，今见会真元。","之子富文华，抱负何超全？","一战三千士，独步文场先。","筮仕入春官，礼乐渐得新。","赠子直清诀，夙夜以惟寅。"]},{"t":"题郡博夏念斋先生寿图诗","f":"五言古诗","c":["五翁应五星，五寿仰求天。","一翁坐一室，一德反求身。","求身机在我，求天事茫然。","德者寿之本，身者天一原。","自求自多福，且勿信人言。"]},{"t":"寿全山高士刘先生诗","f":"五言古诗","c":["俗诮全山名，吾以静不迁。","全山偌我訾，因以止安安。","乾坤有五岳，五岳一全山。","何名为全山？","五岳合一观。","何以为合一？","静看先天先。","当其未分时，宇宙同混然。","丈人秉刚直，用志能不分。","凌空俯五岳，寥廓何超全？","以兹孚邦家，闻达无间言。","德教施外内，廉惠人己间。","敬义通幽明，六善如山尊。","丈人自岳降，仙客来如云。","以山祝公寿，寿酒至如川。","贤郎滞西席，吾为歌此篇。"]},{"t":"赠建昌南城张举人崇","f":"古风","c":["吾欲欲跻匡山，照影天地边。","南寻五老宅，西访麻姑坛。","下自状元里，秩宗弘治间。","予时始通籍，亦获瞻温颜。","今见凤毛种，引雏来蹁跹。","问我养毛诀？","君家有直传。","问何为真传？","直清以惟寅。"]},{"t":"送姚侍御奉命之湖广清戎","f":"五言古诗","c":["吾闻国大事，惟在祀与戎。","和协神人际，诰尔治平中。","吾皇古圣神，礼乐政一新。","郊庙焕古制，戎政咨廷臣。","帝曰御史姚，虞尔有风标。","维尔多才敏，理戎维尔优。","遍历湖南北，爬梳与搜剔。","如发乱思栉，如身疡欲释。","前年水旱荒，将御失其粮。","枵腹出死命，十室五逃亡。","调停在大手，往哉念不忘。"]},{"t":"答安福乡进士周君得之所问八条后赋此","f":"五言古诗","c":["翩翩安成子，问我八条目。","吾方欲无言，言中不如默。","默识不识前，万里一处足。"]},{"t":"赠九山汤子还古冈","f":"五言古诗","c":["圣人训三益，直谅与多闻。","予友九山子，何讵非其伦。","同业因伯氏，识君弱冠前。","古心称古服，言动夙驯驯。","亦同江门游，亦钓楚云春。","予昨归沙堤，访我铁江滨。","今秋携公孙，来浴新泉云。","何以养其直，丝毫了不存。","何以养其谅，心口无间然。","何以养多闻，畜德归渊泉。","行矣各努力，相约朱明天。"]},{"t":"己亥六月七日与九山诸同志游夹冈义庄","f":"五言古诗","c":["盛夏万物长，阳德极光辉。","天道代消长，秋阴变萎甤。","携我众友生，及时出游嬉。","天地尚往复，谁能超范围。","形骸非我有，爵禄岂我私。","逍遥大化内，何喜亦何悲。"]},{"t":"荣寿诗赠赵廷评崇信归庆严亲梅月翁","f":"五言古诗","c":["人皆爱世荣，我独爱良贵。","人皆爱年寿，我独不如是。","良贵在我身，世荣从外致。","年寿会有涯，显扬于世世。","我昧梅月翁，知之有贤嗣。","行道与立身，以亲受多祉。","归荐荣寿篇，廷评子赵子。"]},{"t":"严陈生叔莘","f":"古风","c":["忆昔辛巳冬，治任将趋召。","念。","师裔宜昌，携尔来北学。","三载妨职事，迄今憾草草。","乃考睡乡言，命归侍左右。","星霜十五更，相见学如故。","令予生大惭，不觉发孤叹。","念祖脩尔德，否则为不孝。","如彼嘉树根，枝叶谁伤耗？","赠尔作述箴，归读中庸教。"]},{"t":"赠表弟陈谏乡还甘泉洞","f":"五言律诗","c":["新泉亦甘泉，东海即南海。","须识两泉源，方知四海水。","四海尚且同，人心何彼此？","临流饯弟归，静学泉水止。"]},{"t":"叶子新疗涞之有效谢之","f":"五言古诗","c":["吾儿病且懒，懒故志不立。","身病尚可疗，志病药难及。","下体发虚浮，诊者云热温。","旬月再加医，如水投之石。","叶生一二剂，病已去六七。","再加三五之，根株拔且悉。","惟有心志病，懒惰尚如昔。","奄奄若懦夫，邪魔作蟊贼。","子能为药之，赠子以百镒。"]},{"t":"赐故人林南川先生冢子正夫别","f":"五言古诗","c":["而翁我同门，卓焉号先达。","一体分殊理，自翁亦足发。","我乘飞云车，访翁茶园庐。","子年等中军，我始向立馀。","嗣晤国华寺，题诗见真意。","于今四十年，相见如梦寐。","我酌为君歌，君为我婆娑。"]},{"t":"初九日以神告卜得青霞洞","f":"五言古诗","c":["朱明与青霞，相比为近僯。","虾蟆嘘其气，两洞生晴云。","青霞朱明后，朱明青霞前。","前后一间耳，山脊云平分。","天地不爱宝，多藏遗斯人。","贪固人所鄙，贪山未为愆。","让固为美德，让之恐逆天。","乃辟通云路，乃开见日轩。","行馆落天华，天厨引天泉。","再拜谢神贶，吾兹毕吾年。"]},{"t":"题席光亭","f":"五言古诗","c":["吾师一席光，从谁借于是。","一声凤凰鸣，五色映天地。","此光师自光，何预他人事。","自性得自天，无借亦无匮。","不离一席间，天地万物备。"]},{"t":"梁俭庵司徒七十华诞","f":"五言古诗","c":["我闻莘挚言，俭德怀永图。","小俭财用节，大俭意必无。","愈俭德愈精，精一天为徒。","俭翁跻七十，俭化七十遭。","祝过百千●，国脉与长悠。"]},{"t":"送安子静如山考察左迁","f":"五言律诗","c":["尝闻鲁多贤，岂无知人者？","柳下三黜圣，名照千载下。","人有区损益，天地同久大。","子静安汝止，何健羡悲诧。"]},{"t":"走笔代简答庞举人朱明洞","f":"五言古诗","c":["庞公隐鹿门，有人拜床次。","朱明隐庞子，五方执经至。","朱明于鹿门，境胜无以异。","人心有全经，无言住天地。","隐显语默时，畴或知其义。","世有孔颜徒，可以与于是。","明当脱樊笼，与子坐超诣。"]},{"t":"走笔赠萧上舍归潮阳","f":"五言律诗","c":["萧生辞观光，归问潮阳路。","大路在子心，问人在何处。","何处是吾庐？","广居在天宇。","观光一片心，挂住萧台树。"]},{"t":"送刘通政参议转北大理少卿","f":"五言古诗","c":["春冈好春冈，春冈吾爱之。","一名为春台，阳德镇熙熙。","春生变秋杀，仁义贵兼资。","目君去之矣，宁不令人思？","廷尉天下平，平心君莫疑。","圣主具一德，皋陶在唐虞。"]},{"t":"己亥腊月十一、十二日，同职方朱正郎簠、赵副郎伊，连日冒雨雪视卜义阡，","f":"五言古诗","c":["兹晨凌沧波，昨日发姚坊。","仙鹤逐麒麟，高桥度上方。","率属至斯里，遵曲来夹冈。","冲雪非谩游，卜阡何傍徨？","念彼火中人，安得不为伤。","圣仁泽枯骨，推之及无疆。","息徒同人馆，同志致壶浆。","同人风景奇，山水围孤光。","万物正归根，归根为春阳。","会兹同体理，荡荡见虞唐。"]},{"t":"赠宣城掌教陈伯孚迁尹安义","f":"五言古诗","c":["谁是安义者？","吾与治安义。","郑侨称使民，宣尼谓之惠。","安义斯安仁，仁惠民所庇。","仁以庇民生，义以宜民利。","利成如万物，生聚如天地。","天地大父母，君子维恺悌。","问之何能然？","仁义乃兼至。"]},{"t":"赠葛子东应贡北上诗","f":"五言古诗","c":["昔予开观光，葛子自扬至。","芙蓉出秋水，神清绝神气。","棣萼映堂萱，闾阎称孝弟。","挥金辟行窝，昌大斯文地。","再荐乃入京，马群空北冀。","乐近天子光，九五正当位。","众凿混沌馀，古锥乃一试。","且勿访去华，轻言天下事。"]},{"t":"为汪节夫尚和题德馨堂诗","f":"五言古诗","c":["德馨夫何如？","明德以为馨。","君子贵自昭，虚室生天灵。","天地合其德，日月合其明。","先君有贻孝，地义与天经。","尔德尔自馨，神明游其庭。"]},{"t":"送南京大理寺正赵鲲迁守汉中府","f":"五言古诗","c":["闻鲁多君子，于今一见之。","一见雅素心，语默存真机。","大笔见心画，方正无斜欹。","生心发于政，汉中何足治。","使君行无迟，候迎竹马儿。"]},{"t":"谩题赠冼碧山","f":"五言律诗","c":["吾甚爱此山，山石如我心。","石纵可以转，中坚谁能侵。","山面碧如壁，壁立万仞浔。","不有羚羊角，谁能履高深？"]},{"t":"四月二十三日省农上方门，遵河而南，止于夹冈门同人馆，示诸生二首 其一","f":"五言律诗","c":["劳役不为戚，自逸不为休。","休戚本同体，稼穑与民谋。","我世农家子，莘野岂其俦？","受命安民事，我心宁不忧。"]},{"t":"四月二十三日省农上方门，遵河而南，止于夹冈门同人馆，示诸生二首 其二","f":"五言律诗","c":["先时旱妨麦，我心忧忡忡。","一雨幸全收，我心乐沨沨。","忧乐岂以我？","实与人天通。","譬如诸子心，翕然何来同。"]},{"t":"题嘉善寺住持僧大智画","f":"五言绝句","c":["入山是天樵，出山是人樵。","如何不息担，洗足看溪流。"]},{"t":"过东义庄感旧而作","f":"五言古诗","c":["遵河过义庄，忆昔史子贤，三以义让业，附郭二顷田。","养贤为国桢，有功人不然。","又闻溧阳谣，赈饥破什千。","焚券公煤山，允殖王所天。","有功蒙不韪，养贤以殖氓。","贪夫多灭义，反为世人怜。","三代直道行，天运亦何愆？","嗟亦已焉哉，问天天不言。","矢时告来裔，感义同勉旃。"]},{"t":"中秋三首寄伍宗逊尹彦明 其一","f":"五言绝句","c":["有为常扰扰，无事日休休。","江山饱风月，时节忘中秋。"]},{"t":"中秋三首寄伍宗逊尹彦明 其二","f":"五言绝句","c":["佳节闾阎共，清光月十分。","共怜盘里芋，谁是赏秋人。"]},{"t":"中秋三首寄伍宗逊尹彦明 其三","f":"五言绝句","c":["残云忽捲开，长空极高洁。","偶坐归云楼，何处无明月。"]},{"t":"读刘可大内翰题云轩霍君卷次韵","f":"五言绝句","c":["我屋堪全华，君轩半卧云。","酒醒云散后，开卷忽逢君。"]},{"t":"赠吴世英分教宜兴","f":"五言绝句","c":["夜瓮分江水，春茶煮楚云。","为君浇舌本，六籍细条分。"]},{"t":"为永顺彭宣慰题四首 其一 天章阁","f":"五言绝句","c":["云汉昭宸极，人间一阁张。","始知天广大，不外照辰阳。"]},{"t":"为永顺彭宣慰题四首 其二 清心亭","f":"五言绝句","c":["心源无一物，何物更能浑。","活活天泉在，凭君莫挠源。"]},{"t":"为永顺彭宣慰题四首 其三 四贤堂","f":"五言绝句","c":["四贤堂外月，颜色满空梁。","千古贤宣慰，中心一瓣香。"]},{"t":"为永顺彭宣慰题四首 其四 征边录","f":"五言绝句","c":["谁家重生子，血化剑芒腥。","因读征边录，千秋憾武成。"]},{"t":"斗潭八景 其一 圩上观澜","f":"五言绝句","c":["我本望洋客，观澜得小圩。","源头云锁断，山下看何如。"]},{"t":"斗潭八景 其二 沙头唤渡","f":"五言绝句","c":["且莫渡河去，风吹水倒流。","隔沙人不唤，空老济川舟。"]},{"t":"斗潭八景 其三 后溪钓月","f":"五言绝句","c":["钓璜不钓月，钓月不钓璜。","夜来得月处，钓丝俱已忘。"]},{"t":"斗潭八景 其四 南陇耕云","f":"五言绝句","c":["耕陇恐破云，云破成离披。","纵然耕破罢，犹得补山衣。"]},{"t":"斗潭八景 其五 竹屋鸣琴","f":"五言绝句","c":["竹林围翠响，虚室和琴声。","丝已不如竹，风戛自然鸣。"]},{"t":"斗潭八景 其六 柳坛对弈","f":"五言绝句","c":["何处柳坛好，柳坛风景多。","弈声动前浦，惊鸥飞渡河。"]},{"t":"斗潭八景 其七 禅刹云封","f":"五言绝句","c":["古刹云长封，绝顶出云外。","君欲看白云，更上九层刹。"]},{"t":"斗潭八景 其八 书窗雪霁","f":"五言绝句","c":["书窗映雪时，书声已闻世。","留眼看光风，窗前雪初霁。"]},{"t":"新岁六日淩江驿新晴即事四绝句 其一","f":"五言绝句","c":["六日淩江馆，新晴江水深。","居人因暖出，不为听拿音。"]},{"t":"新岁六日淩江驿新晴即事四绝句 其二","f":"五言绝句","c":["新日暄幽坞，断崖过乱霞。","霞消有烟火，树里有人家。"]},{"t":"新岁六日淩江驿新晴即事四绝句 其三","f":"五言绝句","c":["溪叟坐暄背，溪童出采芳。","轻风舞莺燕，平野鸣牛羊。"]},{"t":"新岁六日淩江驿新晴即事四绝句 其四","f":"五言绝句","c":["驿附十家村，虽贫尚可存。","隔林闻吏语，贷廪落人门。"]},{"t":"北峨驿道中口占四首 其一","f":"五言绝句","c":["南风不满旗，新晴日初暖。","草木生光辉，得意流莺啭。"]},{"t":"北峨驿道中口占四首 其二","f":"五言绝句","c":["南极行尽头，南望尚泱漭。","不游八极外，焉识天地广。"]},{"t":"北峨驿道中口占四首 其三","f":"五言绝句","c":["风软旌旗定，山空玉节明。","如闻重译语，圣德比周成。"]},{"t":"北峨驿道中口占四首 其四","f":"五言绝句","c":["何处北峨驿，门前江可怜。","若教居孔老，川上意依然。"]},{"t":"不博驿二首 其一","f":"五言绝句","c":["绝岛生修篁，无风自相拂。","有果不知名，碧枝映丹实。"]},{"t":"不博驿二首 其二","f":"五言绝句","c":["千军金鼓震，十里羽仪趋。","是我曾无事，春风鸟调雏。"]},{"t":"为石泉赠窗友","f":"五言绝句","c":["道旧西樵馆，山尊亦偶同。","独邻归草草，不得看诸峰。"]},{"t":"托吴提舶致书应吉士元忠","f":"五言绝句","c":["七十峰头月，青天一尺书。","不逢贤舶使，那得到仙居。"]},{"t":"再寄吴提舶","f":"五言绝句","c":["偶逢吴舶使，问讯是天台。","雁荡他年约，从吾跨鹤来。"]},{"t":"自甘泉归西樵夜舟风月甚佳 其一","f":"五言绝句","c":["八日夜潮落，扁舟来自东。","天与还山意，为借满帆风。"]},{"t":"自甘泉归西樵夜舟风月甚佳 其二","f":"五言绝句","c":["在山月色好，出山月色微。","山月今多少，还载满船归。"]},{"t":"寄题眠云","f":"五言绝句","c":["西樵亦西华，同睡不同情。","他时传睡法，不是五龙精。"]},{"t":"题陈继宗所赠万竹尹先生画","f":"五言绝句","c":["可堪开画幅，秋思满江湄。","惟有随阳雁，年年朝北飞。"]},{"t":"送周生卫还阳羡卫为医士不中欲弃其业归于儒云","f":"五言绝句","c":["收身岐黄乡，阳羡山中去。","因君问里人，归来拜周处。"]},{"t":"大同春吟己丑作四首 其一","f":"五言绝句","c":["我道本大同，从人自分别。","举首问太虚，太虚亦何说。"]},{"t":"大同春吟己丑作四首 其二","f":"五言绝句","c":["宇宙同胞里，身居太一家。","清平有麟凤，狡狯起猱蛇。"]},{"t":"大同春吟己丑作四首 其三","f":"五言绝句","c":["譊譊誇毗子，东家复西家。","寻常家计事，岂足向人誇。"]},{"t":"大同春吟己丑作四首 其四","f":"五言绝句","c":["天道玄同是，群分自作家。","春诗拈未出，春信已开花。"]},{"t":"题周克道藏脩所二首 其一 静趣坡书馆","f":"五言绝句","c":["无情未发前，可欲已发后。","借问静趣时，此趣更谁受。"]},{"t":"题周克道藏脩所二首 其二 桃溪精舍","f":"五言绝句","c":["桃花映溪水，溪水亦何情。","精舍有高人，端默观化生。"]},{"t":"送江西周节推佐调重庆","f":"五言绝句","c":["周君肮脏姿，方正不合俗。","不信行路难，仍上瞿塘曲。"]},{"t":"赠屠文厚侍御清戎南广","f":"五言绝句","c":["霜旌一夜发，五岭已全摇。","馀事清戎外，秋风待举雕。"]},{"t":"寄镇江钱医士","f":"五言绝句","c":["闻说钱方士，回生一匕中。","众生犹痿痹，吾药愧全功。"]},{"t":"娄江书舍","f":"五言绝句","c":["四海观会同，三山亦既入。","江馆读书心，二业可能一。"]},{"t":"旧作送戴君赴京公事毕还家","f":"五言绝句","c":["观国归来日，华胥梦已空。","此中难着句，把酒送飞鸿。"]},{"t":"寄题讷庵","f":"五言绝句","c":["天下方多巧，讷庵元不知。","庵中人默坐，兀兀到黄羲。"]},{"t":"送曾秋官梧之南畿审刑","f":"五言绝句","c":["秋杀与春生，天德普万物。","子会好生心，大回造化笔。"]},{"t":"张伯怀舍人素扇面","f":"五言绝句","c":["阖辟如变化，用舍如随时。","把柄一入手，炎凉夺天机。"]},{"t":"送胡主客松之北","f":"五言绝句","c":["北风何淩厉，送子渡江汀。","江花与江涨，尽是别离情。"]},{"t":"甲午元宵予奉会于池亭承诸公乘雪见过分得五言绝句体四首因以奉谢 其一","f":"五言绝句","c":["寂寞幽人宅，低回长者车。","坐令门巷迥，情以主宾摅。"]},{"t":"甲午元宵予奉会于池亭承诸公乘雪见过分得五言绝句体四首因以奉谢 其二","f":"五言绝句","c":["柳眼青迎客，禽心乐傍人。","鹤须为起舞，童侍亦相亲。"]},{"t":"甲午元宵予奉会于池亭承诸公乘雪见过分得五言绝句体四首因以奉谢 其三","f":"五言绝句","c":["主办逡巡酒，天开顷刻花。","雪光瑶海月，灯映赤城霞。"]},{"t":"甲午元宵予奉会于池亭承诸公乘雪见过分得五言绝句体四首因以奉谢 其四","f":"五言绝句","c":["酒令军经略，诗旗愚树降。","门前风雪大，更为尽馀缸。"]},{"t":"偶书与诏使陕右白上舍","f":"五言绝句","c":["浩荡天游志，名山欲尽探。","心将钟阜月，随子到终南。"]},{"t":"偶书赠邬青州之任","f":"五言绝句","c":["翩翩贤刺史，问俗古青州。","我若登东岳，传声海岱楼。"]},{"t":"李医诗","f":"五言绝句","c":["人爱李生药，我爱李生心。","谁廓此心用，为世起呻吟。"]},{"t":"赠沈汝渊北上春试","f":"五言绝句","c":["汝渊自如渊，渊深有真龙。","一旦乘云去，弘施泽物功。"]},{"t":"赠柴允中归江山","f":"五言绝句","c":["允中不允中，中在虚无里。","无在无无在，自见天之理。"]},{"t":"赠胡生登第","f":"五言绝句","c":["胡子青云器，意气激青云。","手执万言策，行于万乘君。"]},{"t":"题扇面尽寄陈云山中丞","f":"五言绝句","c":["两舟系彼岸，共说波涛话。","我若归去来，江山胜如画。"]},{"t":"代简寄对山状元","f":"五言绝句","c":["太白归眠日，云山以为徒。","可怜迁史笔，不为世芟芜。"]},{"t":"代简寄王渼陂","f":"五言绝句","c":["渼陂名胜在，不欠杜陵诗。","云山想眉宇，可似玉堂时。"]},{"t":"走笔赠李道行司训还扬州","f":"五言绝句","c":["李生步江来，惓惓问心学。","心学在自心，自求岂云邈。"]},{"t":"走笔赠李司训世用父母双寿","f":"五言绝句","c":["尝闻岷峨下，往往多长年。","把赠李氏子，归以寿双亲。"]},{"t":"走笔寄题守愚高乡宾","f":"五言绝句","c":["偶逢守愚翁，因知古愚直。","直者天之德，大智藏诸默。"]},{"t":"改名至喜泉","f":"五言绝句","c":["何名至喜泉，泉翁至则喜。","后有清似泉，许尔来共此。"]},{"t":"十六日宿句容土桥南庵示周生","f":"五言绝句","c":["蜗室亦自安，华堂亦自安。","同来寄四大，睡醒在南庵。"]},{"t":"闻雁二绝 其一","f":"古风","c":["??北塞雁，肃肃向南飞。","阳气日南矣，尔知人未知。"]},{"t":"闻雁二绝 其二","f":"五言绝句","c":["年年阳气复，是尔北归期。","王孙春草绿，尔归归不归。"]},{"t":"休宁汪节夫尚和以三帕来寿云致三祝之意答之","f":"五言绝句","c":["节夫致三寿，一寿三千年。","我寿无穷极，与天同后先。"]},{"t":"问庵佥宪马君宗孔求题圃中楼亭四首 其一 宗德楼","f":"五言绝句","c":["天德本自崇，为人自卑之。","倚楼会先后，便是死生机。"]},{"t":"问庵佥宪马君宗孔求题圃中楼亭四首 其二 悠然亭","f":"五言绝句","c":["亭子悠然好，况当崇德前。","悠然真境得，何必见南山。"]},{"t":"问庵佥宪马君宗孔求题圃中楼亭及八景，共十绝 其三 房云捧抛","f":"五言绝句","c":["东山云起时，捧日共熙熙。","照见子房心，微尔汉皆非。"]},{"t":"问庵佥宪马君宗孔求题圃中楼亭及八景，共十绝 其四 楚月生明","f":"五言绝句","c":["楚王久泯灭，楚山月长来。","月曾照楚王，楚王安在哉？"]},{"t":"问庵佥宪马君宗孔求题圃中楼亭及八景，共十绝 其五 南山献瑞","f":"五言绝句","c":["南山凤鸟地，何时更来仪？","凤去独留山，山光楼得之。"]},{"t":"问庵佥宪马君宗孔求题圃中楼亭四首 其三 北斗调元","f":"五言绝句","c":["宝瓶应北斗，北斗不酌酒。","若酌入瓶中，可以献万寿。"]},{"t":"问庵佥宪马君宗孔求题圃中楼亭及八景，共十绝 其七 黄彭对峙","f":"五言绝句","c":["黄彭骨已蜕，何年遗两山？","我寿年龄外，后地与先天。"]},{"t":"问庵佥宪马君宗孔求题圃中楼亭四首 其四 河泗环流","f":"五言绝句","c":["河泗争流处，水流心不流。","自流他自止，吾与止流休。"]},{"t":"问庵佥宪马君宗孔求题圃中楼亭及八景，共十绝 其九 桑梓晴辉","f":"五言绝句","c":["楼上望桑梓，依然见旧居。","广居君认得，何处是吾庐？"]},{"t":"问庵佥宪马君宗孔求题圃中楼亭及八景，共十绝 其十 松楸暮霭","f":"五言绝句","c":["亲在松楸下，松楸暮霭中。","望亲存著外，松霭化为空。"]},{"t":"偶题杨生大中君极采芳卷","f":"五言绝句","c":["采芳复采芳，采之何太勤？","芳馨塞天地，吾自美灵根。"]},{"t":"寄题山泉吴兵部号也","f":"五言绝句","c":["何以爱山泉，山泉静且清。","安得挽之去？","尽洗世间盲。"]},{"t":"期邹谦之不至，走笔寄之","f":"五言绝句","c":["我来我有期，我期天不知。","寄语东郭子，可悟天人机。"]},{"t":"送夏官孙君文宿参藩四川诗","f":"五言绝句","c":["直气叫阊阖，同听喜起歌。","心将薇省月，送子到岷峨。"]},{"t":"题曾春官惟馨藏予小影","f":"五言绝句","c":["无言是吾真，君若请益起。","默识如愚外，曾子可与此。"]},{"t":"官源五景为洪侍御峻之五首 其一 洪鹿田","f":"五言绝句","c":["高士昔乘鹿，还同鹿性驯。","遗田千载下，更有远遗人。"]},{"t":"官源五景为洪侍御峻之五首 其二 主龙山","f":"五言绝句","c":["主龙何处是，烟火两三椽。","静卧知龙德，他时或跃渊。"]},{"t":"官源五景为洪侍御峻之五首 其三 官谷泉","f":"五言绝句","c":["源泉官谷里，泉亦未忘官。","泽物司云雨，西风卷却乾。"]},{"t":"官源五景为洪侍御峻之五首 其四 天井峰","f":"五言绝句","c":["天井无人汲，汲之愁太勤。","忘助中间看，天人此处分。"]},{"t":"官源五景为洪侍御峻之五首 其五 黄芝潭","f":"五言绝句","c":["潭中何所有，白石映黄芝。","坐来潭底影，照见本来谁。"]},{"t":"题碧潭为丹山馆人朱挥使","f":"五言绝句","c":["碧潭如碧天，天与碧相连。","欲普乌龙泽，须借雷霆鞭。"]},{"t":"题马雪坡卷","f":"五言绝句","c":["信步北城坡，忘却坡上雪。","不知孟浩然，寻梅有何说。"]},{"t":"送江君一桂之广右太平守","f":"五言绝句","c":["使君刺太平，问讯太平治。","太平本无象，人心平即是。"]},{"t":"赠李一夔分教海丰","f":"五言绝句","c":["境土移毡近，罗浮就眼新。","秪应徐节孝，扶持百年亲。"]},{"t":"送古田尹何君世纶","f":"五言绝句","c":["邂逅郎星使，知是古田侯。","今我长怀古，因君问井丘。"]},{"t":"雨中坐楼上书所见","f":"五言律诗","c":["浊酒不得意，新诗空自酬。","冥冥翳白日，郁郁坐穷愁。","飞鸟冲风堕，归云被雨留。","小舟还数点，寂寞在荒洲。"]},{"t":"望罗浮","f":"五言律诗","c":["对之不敢指，万丈立空青。","影落沧溟得，高分日月明。","阅人幽石老，无主野花馨。","葛老遥相问，西云是友生。"]},{"t":"谒崔菊坡祠","f":"五言律诗","c":["玉颊碧瞳清，想公眉宇成。","傍观知国手，遗表自丹青。","日落西湖晚，云归剑阁灵。","短词吟未罢，款款凤凰鸣。"]},{"t":"元默别后有怀","f":"五言律诗","c":["闭门梦行李，白鸟没青天。","好月将愁去，新梅对恼眠。","相识波罗树，重看玉井莲。","欲申花意思，临别已忘言。"]},{"t":"西云梅花盛开用元默西云韵","f":"五言律诗","c":["梅花清太极，雪月与通灵。","老树从心折，春风就手迎。","映溪流不竞，脱蒂了无声。","惊起罗浮梦，凭轩见八溟。"]},{"t":"赵元默得一鹤将致西云随即病死诗以悼之","f":"五言律诗","c":["空山无一侣，托契九皋君。","引吭轻寥廓，长鸣意绝群。","世有三生血，吾兼一返魂。","敢言屋乌爱，未必主人嗔。"]},{"t":"题易菊趣","f":"五言律诗","c":["菊亦有何趣，渊明独赏真。","后来爱花者，总是学陶人。","秋露与佳色，南山对入神。","不逢易居士，谁识白纶巾。"]},{"t":"夜梦谒石翁墓病中作","f":"五言律诗","c":["黄云不可度，紫水乃无门。","敛衽圭峰下，如公面目存。","想极寻诗稿，哀馀有梦魂。","平生游走意，他日夜台论。"]},{"t":"临病西云之下不得回送元默行舟聊此遣闷","f":"五言律诗","c":["斜阳迎度马，落月下归舟。","举棹意有适，卧家人独愁。","倚树吟三叠，开帆过两洲。","神仙本无累，吹笛酒家楼。"]},{"t":"冬至日一首","f":"五言律诗","c":["年年有此日，此日苦无多。","愁与初长刻，天来奈老何。","新梅惊病眼，短句儗春歌。","板筑过名节，黄鹂度翠萝。"]},{"t":"板筑一首","f":"五言律诗","c":["板筑非吾辈，心期鹿洞前。","凿池得新月，伐竹见全天。","翠嶂围高阁，黄云对小轩。","仲冬岁癸亥，短咏记吾年。"]},{"t":"同元默弟游黄云洞马上口占","f":"五言律诗","c":["联辔敲推入，溪桥风袂斜。","两莺鸣并树，一路转三叉。","紫府千回梦，青春二月花。","直知天路杳，谁管暮归鸦。"]},{"t":"归云窝中卧看鸟群飞","f":"五言律诗","c":["朋飞何处鸟，此去竟何之。","有底轻心性，无家重别离。","入云终自得，高翅与群疑。","世网专相待，稻粮肥未肥。"]},{"t":"将往谒先师石翁墓舟中写怀","f":"五言律诗","c":["初定江门舸，中宵梦倚樯。","精魂不可致，大道有遗光。","雨过白龙出，云消紫水长。","望坟欲饮泣，不觉泪沾裳。"]},{"t":"大行孝宗皇帝挽词二首 其一","f":"五言律诗","c":["泪穿无厚土，目窅有高旻。","敬祖翻材艺，祈年蹶玉身。","恤囚扬末命，放女陋前人。","从有如椽笔，谁能画得春。"]},{"t":"大行孝宗皇帝挽词二首 其二","f":"五言律诗","c":["退朝恭默处，座上见秋旻。","十八全弘治，清修在侧身。","折节延诸老，承平颂一人。","亲王遗谕在，花萼自冬春。"]},{"t":"奉题东山草堂为刘时雍少师","f":"五言律诗","c":["正属苍生望，东山复此亭。","檐虚湖与迥，景胜岳全轻。","三径沿溪辟，千峰就榻迎。","不留廊庙老，乞与草堂荣。"]},{"t":"潘黄门海珠诗次韵","f":"五言律诗","c":["孤根分穗石，树影带城堤。","泛泛星槎外，荒荒日驭西。","两崖烟火断，一啸海云迷。","便欲依僧寺，终同一鹤栖。"]},{"t":"腊二十八日宿三洲滩","f":"五言律诗","c":["岁尽日阴雨，魂销夜荒汀。","寂寞关河黑，咄嗟瘴雾腥。","兵卫起风草，扪虱卧寒铃。","心逐北流水，直到粤王城。"]},{"t":"过永淳县除夕夜宿道庄与潘黄门对酌二首 其一","f":"五言律诗","c":["岁事催行李，时光只客船。","历头忘了日，符面已新年。","北斗天颜近，南溟地脉连。","几时青鸟使，归侍玉皇前。"]},{"t":"过永淳县除夕夜宿道庄与潘黄门对酌二首 其二","f":"五言律诗","c":["此日不再得，此岁其如何。","此岁还此日，一觞当一歌。","往事成陈迹，流光逐逝波。","年徂志不就，歌竟独长嗟。"]},{"t":"人日过长沙乡","f":"五言律诗","c":["人日程途得，伤心花近舲。","仆童当骨肉，梦寐是家庭。","山势迎船转，草色驻桡青。","双双彩羽去，立石愈分明。"]},{"t":"次潘黄门人日韵三首 其一","f":"五言律诗","c":["春自东南至，迎予作伴行。","草新随意长，花故傍人明。","旅处亲童仆，遐方赖友生。","秉芳欲寄汝，路渺又难征。"]},{"t":"次潘黄门人日韵三首 其三","f":"五言律诗","c":["地幻乎天设，奇观纵此行。","也须潘仲鲁，消得湛元明。","日夕黄鹂语，春风碧草生。","只难销此恨，采采念孤征。"]},{"t":"太平道中观石壁次韵二首 其一","f":"五言律诗","c":["岩石可自砺，试观神已疲。","荡胸生磊磈，乱眼幻神奇。","鸟星来作篆，木客上题诗。","不是飞空侣，人间那得知。"]},{"t":"太平道中观石壁次韵二首 其二","f":"五言律诗","c":["景浓不可泥，情缓故无疲。","称意崖云丽，伤心壁月奇。","久婴性尔癖，太瘦是吾诗。","微意凭谁诉，峰头病鹤知。"]},{"t":"次宿布村韵","f":"五言律诗","c":["连云草色润，带雨花枝寒。","物态兼诗得，羁怀共酒欢。","青牛谁谷口，紫气此檐端。","惭愧非吾辈，临关重倚阑。"]},{"t":"早发不博驿次韵","f":"五言律诗","c":["异俗难同调，诗情空自浓。","触人山霭霭，当面水重重。","飞鸟愁攲径，行云无定踪。","自兹欲浮海，高步蓬莱峰。"]},{"t":"次韵潘黄门寿昌河之作二首 其一","f":"五言律诗","c":["却如周宰孔，不似晋临河。","已见天无外，还闻海不波。","影随一苇渡，声接两涯歌。","遥想唐虞化，南郊羲暨和。"]},{"t":"次韵潘黄门寿昌河之作二首 其二","f":"五言律诗","c":["回首千山路，消愁见此河。","滥觞立鹭渚，映阁浴凫波。","有客乘槎过，何人鼓枻歌。","蛮音不须解，以臆宣天和。"]},{"t":"题谏议祠","f":"五言律诗","c":["冬日昌平郭，吟诗谏议祠。","志存时事往，道在后人思。","古木藤萝上，荒庭俎豆微。","瞻鸟下爰止，得意舞阶墀。"]},{"t":"寿故李少师母太夫人九十","f":"五言律诗","c":["寿域开何处，西涯近斗杓。","帝师推八座，母范著三朝。","已见曾孙宴，还誇后物凋。","偷桃惭匪朔，爱听幔亭谣。"]},{"t":"送张公度尹贺县","f":"五言律诗","c":["贺县分符去，苍梧路更西。","青山迎彩旆，明月引花蹊。","谩说能撄虎，还闻笑割鸡。","千家有忠信，赤子在提携。"]},{"t":"送吴孟奇立教迁江","f":"五言律诗","c":["闻道迁江博，高情见五坡。","旌忠立教地，仗义即条科。","春风皋席动，化雨杏坛过。","试问江头水，观澜谁独多。"]},{"t":"送松江陈别驾之任","f":"五言律诗","c":["问俗松江口，松江春若何。","黄堂已风动，上海有弦歌。","民瘼催租拙，儿号乳哺多。","不惭食鲈美，明月满清波。"]},{"t":"题三郡政略","f":"五言律诗","c":["再读刘琨传，南邻太史稽。","甘棠有遗爱，别驾是名騠。","官协三刀梦，桥留十字题。","邦人须考德，更请问松溪。"]},{"t":"送太仆少卿陈先生之南寺","f":"五言律诗","c":["因忆环滁胜，曾登太仆堂。","逍遥王子馆，把别榜兄觞。","戎马论材剧，羁怀吏隐忘。","秉心渊塞处，騋牝自骧骧。"]},{"t":"送大都宪伍松月先生考绩之京","f":"五言律诗","c":["颇忆江西变，微公人恐非。","论功犹众典，超逸与群疑。","贞度僚须肃，精忠帝合知。","会应为前席，南国尚疮痍。"]},{"t":"送大都宪胡先生考绩之京","f":"五言律诗","c":["中丞新画鹢，迤逦傍春行。","北去频瞻斗，南还未计程。","三载虽论绩，诸边尚用兵。","奇才本无最，天诏下青冥。"]},{"t":"和周贞庵中丞操江江上之作","f":"五言律诗","c":["中丞出耀武，横槊赋新诗。","画戟青天杳，楼船白日移。","波光閒水阵，霾气散霜麾。","见我开衷素，论交颇恨迟。"]},{"t":"送张惟信学士主考南畿事毕还朝","f":"五言律诗","c":["吾爱亭溪子，一见眼逾明。","对坐疑醇酒，相将到大羹。","抡材钟阜秀，临决秦淮清。","影绝停云处，天空北斗横。"]},{"t":"健翁费少师寿诗","f":"五言律诗","c":["棣萼真吾爱，楼居接凤台。","因知健翁诞，遥想寿筵开。","金露降南极，文星烛上台。","乘除蘧化里，阅世几回来。"]},{"t":"送蒋中丞石庵考绩之京","f":"五言律诗","c":["爱尔柳塘静，肩舆月屡经。","依稀蒋卿径，阒寂子云亭。","白日三山迥，青天一鹗征。","历扬中外处，报政几回成。"]},{"t":"崦西徐少宰部署藤花盛开佳章见示欲予同和","f":"五言律诗","c":["藤花亦自媚，适逢赏者贤。","托生天署上，偏得主人怜。","万朵娆同色，孤根深不迁。","遥知樵岭发，寂寞在江天。"]},{"t":"次韵和廖洞野翰长院中观莲四首 其一","f":"五言律诗","c":["御气通龙阁，花光接凤池。","清香超圣品，静直不凡姿。","过雨添诗兴，新荷当酒卮。","还闻君子德，在远益相宜。"]},{"t":"次韵和廖洞野翰长院中观莲四首 其二","f":"五言律诗","c":["天然元不作，清水出芙蓉。","自挹瀛洲秀，因思太华峰。","神清天所降，根净地攸钟。","若就观莲赋，名书必蔡邕。"]},{"t":"次韵和廖洞野翰长院中观莲四首 其三","f":"五言律诗","c":["缥缈姮娥府，璀璨碧玉堂。","大千嬉日旭，尺五接天光。","不着群花色，兼闻自性香。","谁云衰白叟，无算尚能觞。"]},{"t":"次韵和廖洞野翰长院中观莲四首 其四","f":"五言律诗","c":["接引谁仙子，观莲无极翁。","浴神群玉府，弄化水晶宫。","杯酒频经眼，芙蓉不耐风。","及时虽领略，真赏在收功。"]},{"t":"咏正堂旁老柏","f":"五言律诗","c":["此柏如有意，森森近我堂。","避檐东干落，碍日北厅凉。","正色难谐俗，何心独傲霜。","春花与夏草，同尔一时芳。"]},{"t":"早出仪凤门过狮子山有感而作","f":"五言律诗","c":["忧世山容蹙，还过狮子山。","即愁狮子吼，未放豹韬閒。","戍卒反金革，天兵压玉关。","如闻飞檄报，生缚渠魁还。"]},{"t":"赠常司教之婺源诗","f":"五言律诗","c":["广文从北斗，肃肃趁春来。","桃李迎门待，春风称意栽。","青毡他自冷，素业是谁开。","若到齐云胜，因风寄语回。"]},{"t":"咏柏木网巾筒子","f":"五言律诗","c":["筒子偏随我，于今三十年。","纪纲舒卷里，汗漫化功全。","素质自贞干，虚心是应缘。","世间炎冷态，于汝不惭然。"]},{"t":"次韵介溪太宰灵谷寺见寄二首 其一","f":"五言律诗","c":["风递歌声过，令人毛骨寒。","我歌青竹枕，公咏白云端。","一啸天地窄，再歌胸膈宽。","即须鞭鹤去，暂结寿厓欢。"]},{"t":"次韵介溪太宰灵谷寺见寄二首 其二","f":"五言律诗","c":["遥忆羊肠路，初行未觉通。","前途须自到，真境与人逢。","五字闻孤唱，三更梦远峰。","诸天在云外，风送隔山钟。"]},{"t":"陈石亭以旧作见示次和灵谷一篇","f":"五言律诗","c":["灵谷寺前树，参天几十寻。","阅人万遍过，怀古一何深。","佛日照群动，慈云送远阴。","因思天下叹，中夜想森森。"]},{"t":"周厚山中丞家鹤产双雏是称瑞鹤为赋此诗","f":"五言律诗","c":["产鹤家奇瑞，亦惟人瑞之。","和鸣学雍睦，脩洁似操持。","乐意将雏舞，成巢愧燕归。","托身已得所，应感主仁慈。"]},{"t":"为夏举人臣寿其乃尊梅湖先生六十华诞","f":"五言律诗","c":["有子怀贞介，因知尊甫贤。","自怡椿树寿，不羡槿花妍。","养志三牲上，扬名万寿前。","在京亲意乐，何必舞华筵。"]},{"t":"陈中舍使事毕将便还姑苏托兴赋此赠之","f":"五言律诗","c":["倾盖逢中舍，停杯问洞庭。","扁舟逐海月，几日到沧溟。","僩尔乘槎使，邦人负弩迎。","早闻侍书召，夜梦笔花生。"]},{"t":"赠别同年陈省斋司寇还朝","f":"五言律诗","c":["酒黄黄似菊，菊色劝杯频。","别后杯停处，遥思菊对人。","世情青眼几，交态白头新。","上苑看花意，如今老更真。"]},{"t":"赠李文舆秋官正郎奉诏归省","f":"五言律诗","c":["天子崇仁孝，陈情诏许归。","望云纡昼锦，计日理班衣。","岭月明空橐，江风满去旂。","抚弦看远翼，心与尔同飞。"]},{"t":"赠钱公溥地官正郎奉诏归省","f":"五言律诗","c":["公溥思亲疏，文舆作伴归。","几年同绛帐，到日两莱衣。","日决冥冥翼，心悬猎猎旂。","樊笼有羁鸟，争得羡群飞。"]},{"t":"松谷为洪侍御峻之外舅胡君洪","f":"五言律诗","c":["夫谷亦幽矣，况复万松深？","丈人此揽结，如入空禅林。","绿云迷慧眼，涛声惊静心。","幽深尔自得，于人何处寻？"]},{"t":"太平诗","f":"五言古诗","c":["绕郭茔心水，沿江破额岑。","巢城天设险，狼寨地还侵。","胡采下空壁，蛮烟出远林。","听歌或成啸，欲语却殊音。","架木怀同寝，编篱巴就擒。","美波形莫辨，朴割歜同斟。","士挽须龙去，人酣艮柳吟。","暂看腰带剑，差别耳圈金。","口与槟榔赤，头兼面目黔。","狫长裙过胫，姑巨结垂簪。","服贾浑箕帚，哺儿并槁砧。","开元泉货旧，昭代品流今。","尝隘三都赋，无论九牧箴。","封疆虽斗大，日月共天临。","一体分冠屦，八荒同裔襟。","驻桡江雨歇，吹笛壁云沈。","铜柱北影外，扶桑西枝阴。","星槎淩斗极，龙节谢氛祲。","刺史堂乌下，皇华亭草深。","使君行县事，驿廪并家寻。"]},{"t":"赠霍渭先进士毕姻归南海长律一百韵","f":"五言古诗","c":["发迹青云上，收身紫极边。","相逢何恨晚，倾倒到忘年。","溟海千龄鹤，风波万斛船。","是源终必达，若火势方然。","斗极应长定，星霜却屡迁。","哲人无习气，圣学谢陈篇。","四宇云消尽，中天月自圆。","有流皆赴海，无地不同天。","锻炼功须此，山林趣已偏。","百途皆适国，一苇亦杭川。","尺蠖时乎屈，羚羊有或悬。","陆沈须似朔，勇退每思钱。","敝帚真谁售，兰膏合自怜。","侧身观世界，引手汲天泉。","铁笛吹何处，蒲团坐欲穿。","前程无税驾，重任未弛肩。","在水应为润，存规必作员。","一心从主宰，万事或因缘。","肯信神为速，还如静者便。","掉头归海岛，障眼扫云烟。","尧舜非无受，羲皇更有前。","多岐分炼术，捷径入金仙。","逝者无停息，斯文久绝传。","开怀舒浩荡，洗耳藉潺湲。","到处逢膏火，将身赴熬煎。","清凉思盥濯，荤血饱腥膻。","大隐金门客，叨陪玉帝筵。","全身徒蛰虺，奋击愧高鹯。","瑗过年将迈，予诛志速悛。","惭无退日手，犹树彗云鋋。","有客利攸往，何人敢与权。","高坚劳钻仰，影响病拘挛。","根本方时发，支离在必蠲。","艺游须有息，德猎迅于畋。","观海知无量，窥天失大全。","中心秉明哲，和气会相宣。","至德酬知己，高谈谢世贤。","庶几犹万一，彷佛见三千。","独步难为继，将开必有先。","时贤生衮衮，粤秀起翩翩。","古调诚孤唱，高山未绝弦。","流行虽宇宙，鱼兔有蹄筌。","蕴藉胡为者，声名骤隐焉。","奎星元朗矅，文运亦回旋。","讨论随毛颖，游居即楮玄。","骐骝产渥水，毛羽长青田。","子史如珠贯，经书以类连。","玉金声互戛，苕翠色相鲜。","古器看黄吕，和音听铎舷。","纷纷惊藻思，稍稍弄云笺。","历块迷途辙，追风累缠牵。","同行常似砥，皇路忽如邅。","弃席还当惜，君恩忍遽捐。","瓶冰占气候，尺水起漪涟。","枯草知兴废，元龟定涧瀍。","七三梅有摽，花柳昼连阡。","去路瞻南斗，归途转北鞭。","寿筵舞锦绣，月殿见婵娟。","珠剃先隆翟，峨冠细玩蝉。","李桃酬种种，瓜瓞祝绵绵。","家徒四白壁，业有一青毡。","永怀梁子节，不愧孟光钿。","牧犊心悲雉，东莱笔胜椽。","光生魁堡里，华发秀山巅。","泉石宁耽恋，膏肓可疗痊。","依依看院草，冉冉见池莲。","倒蔗渐如境，么荷苦似拳。","会前釐室席，已兆讲堂鳣。","尘土浑缁素，风埃没锦鞯。","灵源殊濯濯，静溜自涓涓。","习静依山下，行歌到海壖。","大醒尘土梦，勇斩葫芦缠。","閒倚孤崖啸，魂酣绝嶂眠。","未须游远骑，祇合坐中坚。","花发馨香远，云开锦绮妍。","抢榆无大翼，止棘是轻翾。","允矣谁能拔，招之或以旃。","尘头障霾雾，足底动星躔。","衾影恒存畏，盘盂亦致虔。","至人无彼我，举世入陶甄。","谁捧寻常土，时方四六骈。","醯鸡生翰简，负蝂累尘编。","开户誇新学，名家业旧专。","诚能通内外，不必佩韦弦。","槁槁修形客，泠泠古寺禅。","到头还自得，入手要求诠。","蜀犬多骇日，南辕岂适燕。","十千凭奋迅，九万快高骞。","看剑歌还叠，拈杯语更延。","途危防骥足，江涨慑蛟涎。","西土无仪凤，南州有杜鹃。","笔谈先远寓，书舫蚤言还。","蹈海休从鲁，寻山谩觅佺。","临流悲影独，涉水惜裳褰。","渊静忻潜鲤，天空看戾鸢。","如君多直谅，合我补遗愆。","壶子机将杜，西铭意独镌。","王孙何伥伥，芳草又芊芊。","远到仍胜重，孤征岂惮孱。","为言同志子，共赴胜流铨。"]},{"t":"遗庵任丘张君寿七十太史李宗易令岳也恳予作寿诗二十韵","f":"五言古诗","c":["丈人河上秀，蓟子朔方英。","素履终全节，金天独孕精。","留侯无事汉，仲蔚不居城。","入粟都随例，褒官自当荣。","寿筵开赤县，真箓授神京。","福地通玄极，神仙接岛瀛。","东床分玉液，北斗下金茎。","燮理存交酢，调和付太烹。","挥杯邀玉兔，举手揖长庚。","月底排鸾驭，云中听凤笙。","过从皆抱朴，招引或篯铿。","蔼蔼闻歌至，翩翩倒屣迎。","各酣真率酒，共进太和羹。","自有延年诀，谁称介福觥。","诸郎传世德，别驾振家声。","何日延三老，如公亦五更。","由来知玉润，应不愧冰清。","上寿元平格，遗安乃利贞。","至仁须永命，无事即长生。","缕舞纷仙乐，清谣尽胜名。"]},{"t":"奉寿毛阁老六十长律","f":"五言古诗","c":["旧说山东相，东莱更毓灵。","近分洙泗润，不了岱宗青。","维岳生申甫，斯文睹日星。","芝生饶秀色，玉立映明庭。","弱冠终军少，三冬曼倩成。","汪怀欺汉宪，雅量似辽宁。","文彩云中豹，清修海上䴇。","九流兼猎涉，六籍在参订。","世识公侯器，人誇宰相形。","色言无疾厉，胸次没畦町。","四世勤供奉，三朝谨侍经。","纾徐登相府，洞达见灵扃。","黾勉艰危际，裁成靖难能。","刚柔须吐茹，剂量费调停。","定册终推让，承恩若战兢。","居成惊宠利，在治念伶俜。","寿域开初度，神都锡百龄。","金天授丹箓，紫阁出仙醽。","东海誇桃宴，西王说幔亭。","未须辞富贵，长与作仪刑。"]},{"t":"大司徒九峰孙先生七十华诞诗以奉寿十二韵","f":"五言古诗","c":["我慕孙思邈，知圆行且方。","遥遥九峰秀，鼎鼎四朝望。","文苑开郎署，魁星近斗芒。","群公皆雅器，三命每循墙。","赤舄多肤逊，丹心在庙廊。","云归天地闭，龙起楚江光。","大老来东海，精忠答圣皇。","召司仍会计，疏达必流亡。","祚国须兵食，匡时乃历扬。","甫申神岳重，平格寿天长。","瑶宴张仙府，金茎下建章。","凤雏供戏彩，诗咏祝无疆。"]},{"t":"寿留余先生得生字","f":"五言古诗","c":["自亲吾榜弟，如已拜先生。","尚想趋庭教，无论翼世荣。","着鞭骢马逸，脱蹝柏台轻。","平格多延考，留馀与戒盈。","逢辰歌岳降，初度纪王正。","北斗斟元气，东皇进寿觥。","百龄符帝锡，三老会时亨。","莫憾莱衣旷，贤劳在野坰。"]},{"t":"于赵类庵宗伯宅修会得五言排律二十韵","f":"五言古诗","c":["宗伯开文苑，春光际景辰。","吟鞭乘岛兴，谈麈静规尘。","忝窃瀛洲彦，叨陪讲幄臣。","诗坛寻地主，酒伴尽天人。","等作他乡客，犹惭入幕宾。","游从兼吏隐，人物是丝纶。","花意妍堪恨，山容巧作颦。","云行西岳雨，蝶梦上林春。","燮理存杯酒，忧虞损绣茵。","逍遥鸡阜月，寂寞凤台滨。","潭府初张宴，明公对饮醇。","大羹滋味永，雅咏愫情申。","蔼蔼衣冠俊，恢恢笑语亲。","兰亭无放达，金马更清真。","咄咄书空札，嚣嚣谢众嚚。","天心自流运，物态尚悲辛。","仰阁依珠斗，瞻云恋紫宸。","食芹思有献，投壁恐无因。","盐鼎非公辈，清修报主身。","南溟起大翼，九万谁能驯。"]},{"t":"贺张母胡太夫人华诞诗十韵","f":"五言古诗","c":["阿母江阴望，神明胤厥先。","尹门兼二养，孟氏自三迁。","未拜慈颜胜，占知令嗣贤。","瞻丸开翰学，闺范得家传。","帝锡褒贤自，人誇教子然。","金茎分玉斝，珠翟映瑶钿。","宝箓传天姥，年龄各地仙。","锦筵云起处，彩服月华边。","道算千年外，真羞五鼎前。","平生寿亲意，不以慕彭篯。"]},{"t":"赠地官副郎赵丹山考绩取道南归诗三十四韵","f":"五言古诗","c":["忆昔全弘治，相逢嘉会楼。","时方岁戊已，人各富春秋。","我出乘孤蹇，尔来携小舟。","终军初弱冠，思叔晚从游。","碧玉同分席，圭峰到上头。","论才师有眷，请事子能休。","宴笑筑场际，执丧诸楚咻。","心将深丽泽，期以各藏脩。","并马铁桥过，联诗径口遛。","西云石路滑，南海古祠幽。","辛酉登秋榜，甘泉系晚桴。","经年而傍母，一纪亦盟鸥。","观国亲言感，同舟友义稠。","岭猿愁寂寂，洞鹿喜呦呦。","留滞南雍帐，先开北蓟艘。","春光惭老帽，秋翮落凡韝。","碧水芹香远，枫山礼数优。","自衔三载恤，独抱百年忧。","静坐烟霞迥，闻歌海若愁。","多君左凤尾，索我大科丘。","感激飞龙诏，朋从菲采收。","叫阍上封事，歌朴下东周。","澧北紫兰圃，江东白鹭洲。","异方音渺渺，相望路悠悠。","入贰南宫省，来参中府谋。","缤纷皆礼乐，驽马愧骅骝。","出并寅清舸，勤操会计筹。","奏功兼府部，赠处似回由。","天上千龄鹤，人间万火牛。","樊笼淹健翮，寥廓放高眸。","心逐鸿飞远，形同匏系留。","需沙终有意，艮背乃无俦。","咄咄勿复道，冥冥不可求。","鲁连如欲见，为我试穷搜。"]},{"t":"次韵答郭总戎武定题烟霞洞二首 其一","f":"古风","c":["百万胸中藏甲，悬河口里生波。","顾我烟霞何意，无能知我无他。"]},{"t":"次韵答郭总戎武定题烟霞洞二首 其二","f":"古风","c":["七十二峰光影，二百里外风波。","不笑人间冷澹，高情那识其他。"]},{"t":"画","f":"古风","c":["山霭参差屋树，江烟灭没风舠。","一笑渔鱼得失，危机共在波涛。"]},{"t":"晓发仆山驿至丕礼驿四首 其一","f":"古风","c":["草色初看过雨，山光乍见收霞。","烟火数椽茆栋，荒篱一树桃花。"]},{"t":"晓发仆山驿至丕礼驿四首 其二","f":"古风","c":["摇曳旌旗十里，斑趍甲士三千。","着处春风满意，殊方化日同天。"]},{"t":"晓发仆山驿至丕礼驿四首 其三","f":"古风","c":["阴晴养花天气，士女游衍风晨。","一翻佳人拾翠，满城桃李争春。"]},{"t":"晓发仆山驿至丕礼驿四首 其四","f":"古风","c":["冠屦不伦之分，圭璋特达之尊。","秉节会成周礼，曳裾归去王门。"]},{"t":"市桥道中四首 其一","f":"古风","c":["春草气蒸行李，朝花露滴征衣。","怅望平原雨湿，欲寻旧路云迷。"]},{"t":"市桥道中四首 其二","f":"古风","c":["树杪鸠鸣雨霁，稻畦秧送风凉。","欲采楚襟香草，已辞越橐难将。"]},{"t":"市桥道中四首 其三","f":"古风","c":["云去竹间露坠，风来草际波生。","忽逐黄牛别垄，惊飞白鹭一行。"]},{"t":"市桥道中四首 其四","f":"古风","c":["断桥两涯流水，孤村一带平芜。","乡梦初惊唤渡，每怀想见乘桴。"]},{"t":"题洗罗江司空画菜","f":"古风","c":["谁能笔底生春，老眼触处皆仁。","生意可留此看，无然咬尽菜根。"]},{"t":"晓枕偶成六言六首 其一","f":"古风","c":["正写引年一疏，梦寐中夜思归。","心逐南翔宾雁，插翅不能奋飞。"]},{"t":"晓枕偶成六言六首 其二","f":"古风","c":["阳鸟木落南征，欲托阳鸟寄声。","先扫烟霞荒径，阳鸟谢予不能。"]},{"t":"晓枕偶成六言六首 其三","f":"古风","c":["铁江新筑钓台，长竿待予归来。","若出九井之璜，世人无然见猜。"]},{"t":"晓枕偶成六言六首 其四","f":"古风","c":["欲鞭九龙上天，九龙藏而不云。","云龙不期而会，雷雨之动如神。"]},{"t":"晓枕偶成六言六首 其五","f":"古风","c":["云谷依稀南亩，乐尧执穗北庄。","怅想助耕诸弟，屈指大半云亡。"]},{"t":"晓枕偶成六言六首 其六","f":"古风","c":["垂虹珊珊从天，流落人间不还。","归挹飞泉洗耳，耳畔寂无尘喧。"]},{"t":"精舍甫成寄怀觉山侍御","f":"古风","c":["讲堂一悟天开，上起亭云高台。","台下三千弟子，梦想觉山归来。"]},{"t":"东牧为同年王君坊外舅翁题","f":"七言古诗","c":["牧牛四方亦无着，牧牛东原爱朝暾。","西北幽昧不可居，南方离火残牛群。","善牧牛者随牛意，牛不能言臆自申。","手攀扶叶折牛箠，蹊人之田即鞭之。","若然不蹊亦不鞭，此牛与我同无为。","丈人牧牛从养性，行往坐卧吾无疑。","驯致白牛露迥迥，勿令斗伤扶桑枝。","扶桑枝伤亦未恶，扶桑日出无光辉。"]},{"t":"我所思三章 其一","f":"楚辞体","c":["我所思兮在河西。","一人独往何人迷。","天寒古道行人稀。","我若言之天亦悲。","江流东去西日微。","愿回中天照我私。","朝宗日夜无停时。"]},{"t":"我所思三章 其二","f":"楚辞体","c":["我所思兮在龙场，何年龙卧今遗芳。","潜者勿用用者伤，孔颜当之亦则藏。","思君思君白发长，乘彼白云归故乡。"]},{"t":"我所思三章 其三","f":"楚辞体","c":["我所思兮阳明麓。","空山无人又多木。","犬惊春云鸡升屋。","泉鸣琴兮山鸟歌，山人负暄与鸣犊。","嗟此乐兮乐无殃，我不归来君耻独。"]},{"t":"题华山希夷睡图","f":"七言古诗","c":["陈桥数万之扰扰，不供堕驴之一笑。","宋家四百之历年，不足开眉之一觉。","五龙睡法不可传，虚以待之无所先。","一阖一辟皆自然，此辈岂是作梦人。","引筇卓地脱笠顶，自有天地为衾枕。","何须更费买山钱，落花啼鸟春无穷，欲尽此梦须梦中。"]},{"t":"答邕州别驾邓诚之","f":"七言绝句","c":["美人昔别藤江湄，藤江山前云满溪。","翳门关外春草萋，王孙王孙归不归。"]},{"t":"送泰州博何道充","f":"七言古诗","c":["通州广文何道充，和气可挹如春风。","四载泠泠振铎声，至今闻者开盲聋。","此风传播自扬泰，欲得师者人人同。","鹿门文选知在扬，补之泰州从众公。","何君义气更喷薄，生死交情不改矱。","安溪倾盖始定交，临死后事以相托。","君之高义激秋云，携丧并子同南舶。","教子全丧谢九原，略无难色见然诺。","嗟嗟世上平生交，临难反眼若不识。","临难反眼若不识，闻君之义宁无怍。","始知动人自有本，知本可与共圣学。","愿君充此恻隐端，优与诸生入圣门。"]},{"t":"送望江令余君纮","f":"七言律诗","c":["县名望江吾独隣，大江滚滚来县前。","欲挽天瓢汲江水，尽为人间洗怨冤。","闻彼疮痍尚民瘼，请君濯热与疗痊。","尤溪溪水深几许，润泽百里长涓涓。"]},{"t":"送浔州别驾陈一之","f":"七言古诗","c":["浔州壬癸吾旧游，大藤峡贼窥城头。","忆昔韩公霹雳手，断藤大藤今无有。","于今此辈交市货，骄子饱暖虎则饿。","明公别驾展骥足，此辈应须窜林麓。","从来感格在信恩，潢池赤子皆王民。"]},{"t":"赠彭鸣卿下第还五羊","f":"七言律诗","c":["白云山下五羊城，西江水流东海清。","毓才有如二彭者，长使老夫双眼青。","翩翩宛若两朱鸟，一留瑶阙一沧溟。","三年定静养奇翅，会看翀天时一鸣。"]},{"t":"赠明卿周君赴衡府伴读","f":"七言律诗","c":["去年遇君淮水北，今日见君江水南。","江淮渺渺波浪阔，道路修阻愁人深。","清秋天高一雁征，公子独曳长裾行。","会见玉门称乐善，梁园赋雪风泠泠。"]},{"t":"送大中丞林石厓巡抚保定诸府提督紫荆诸关","f":"七言律诗","c":["石厓如心铁如面，霜风凛凛不可犯。","化作两畿桃李春，为两棘寺洗冤怨。","世传斧钺授天庭，内抚天关外紫荆。","旧日春风皆识面，株株桃李忻相迎。"]},{"t":"送大司成陈琴溪之南雍 其一","f":"七言律诗","c":["忆昔与君尸璧水，东厢南厢只尺耳。","嗟予有行君不疑，德业相成同一致。","琴溪溪上风泠泠，君归予南旋北征。","诗歌钟鼓停夜月，观光庭草待君青。"]},{"t":"贺沈氏二母双寿","f":"七言古诗","c":["沈生情事久未伸，衷曲区区难向人。","襁褓命者麟台君，守斋仲父为后昆。","本生离怀未离乳，所后鞠之应甚仁。","一母生之一母成，爱根天性俱天经。","王母孀居七十零，手和熊胆学业精。","帝推所自锡恩荣，表与令尹为式矜。","许母劬劳裂肺腑，生男不获食男报。","但知祖命为尊严，不谓终惭矍相圃。","只今垂垂八十龄，私恩耿耿负中抱。","秋春之杪双萱秀，寿盏斑衣随左右。","三月花光照寿筵，三秋寿域花更妍。","二母欢心一子尽，移治移忠皆性分。","当今圣明重孝理，两宫并寿因心起。"]}]};